-- Все workflow: прод ← локальная база (сверка 2026-08-18)
--
-- Зачем вручную: seed применяется только к пустой базе, а прод заполнен. Workflow,
-- заведённые и правленные локально, на проде не появляются ни при деплое, ни при
-- рестарте. Раньше их переносили по одному (`2026-08-13_wf55_*`, `2026-08-14_wf56*`);
-- этот файл выравнивает всё разом, взяв за основу локальные данные.
--
-- ЧТО ПЕРЕНОСИТСЯ (919 строк):
--   agent_workflow                     51  — все workflow
--   agent_workflow_variable           212  — все переменные
--   agent_workflow_variable_workflow  234  — их связи с workflow
--   agent_workflow_step               408  — все шаги
--   node_variable                       3  — переменные узлов (промпт девушки и т.п.)
--   node_variable_role                  5  — кому они видны
--   node_variable_workflow              6  — где применяются
--   agent_workflow_step_type            7  — типы шагов; без них шаги не вставляются
--
-- ЧТО ЭТО ДАЁТ ПРОДУ (сверка перед выпуском):
--   * 20 workflow, которых там нет вовсе: 28 `research_loop`, 30–40 и 42, 47, 49–54
--     (планирование, design, генерация страниц, `task_ai_generator`, `design_tokens_generate`);
--   * 10 workflow, которые разошлись по шагам — локально их больше:
--     #12 (18 против 16), #20–#24, #26 (5 против 3), #15, #19, #25 (правки шагов);
--   * 21 workflow совпадают полностью — для них файл ничего не меняет.
--
-- БЕЗОПАСНОСТЬ. Прод — строгое подмножество локального по номерам строк: ни одного
-- id шага или workflow, которого нет локально, там не нашлось (проверено сверкой
-- списков id). Поэтому `ON DUPLICATE KEY UPDATE` только добавляет и обновляет —
-- удалять нечего, и ни одна прод-строка не осиротеет.
--
-- Два исключения, которые НЕ трогаются: переменные 252 `max_goals_iterations` и
-- 261 `max_split_iterations` есть только на проде и привязаны к #55. Локально их нет
-- ни под этими номерами, ни под этими именами. Файл их не удаляет: они безвредны, а
-- снос ссылок из связей #55 сломал бы то, что там работает.
--
-- ⚠️ ID ШАГОВ ПЕРЕНОСЯТСЯ КАК ЕСТЬ, и это главное условие. Шаги ссылаются друг на
--   друга двумя способам: явным `step_id` внутри `metadata.transitions_after` и
--   именем результата `<инструмент>_<id шага>_result_<тип>`, которое читают соседние
--   шаги. Переназначить id при вставке — сломать и переходы, и чтение результатов,
--   причём молча: workflow пройдёт шаги и вернёт пустоту.
--
-- ⚠️ АГЕНТОВ ЗДЕСЬ НЕТ. К новым workflow локально привязаны 10 агентов
--   (`planning_scorer`, `planning_idea_generator`, `planning_designer`,
--   `planning_html_prototyper`, `planning_prototype_refiner`,
--   `planning_prototype_sitemap_checker`, `planning_wireframe_composer`,
--   `planning_block_regenerator`, `task_ai_generator`, `design_tokens_manager`),
--   и на проде их нет. Без них эти workflow некому вызвать — но переносить агентов
--   пачкой нельзя: локально среди них живут тестовые (анкеты, `*_runner`), которым
--   на проде не место. Их перенос — отдельным файлом и отдельным решением.
--
-- `created_at` при обновлении не трогается: время появления строки не должно ездить.
--
-- Порядок таблиц по внешним ключам: workflow → переменные → связи → шаги → узловые.
--
-- ПЕРЕД ПРОГОНОМ: свежий бэкап через `/admin/backup`.

USE `project`;

SET NAMES utf8mb4;

-- ---------------------------------------------------------------- До
SELECT 'ДО' AS этап,
       (SELECT COUNT(*) FROM agent_workflow)                   AS workflow,
       (SELECT COUNT(*) FROM agent_workflow_step)              AS шагов,
       (SELECT COUNT(*) FROM agent_workflow_variable)          AS переменных,
       (SELECT COUNT(*) FROM agent_workflow_variable_workflow) AS связей,
       (SELECT COUNT(*) FROM node_variable)                    AS узловых;

-- ---------- 0. Типы шагов — раньше всего остального
--
-- Шаг ссылается на свой тип внешним ключом, и вставка шага с неизвестным типом
-- падает целиком (`fk_ws_workflow_step_workflow_step_type`). На проде не хватало
-- `llm_to_image` (id 7) — он появился локально вместе с генерацией картинок,
-- а типы шагов ничем не синхронизируются: они лежат в базе, а не в коде.
-- Всего типов: 7.
INSERT INTO `agent_workflow_step_type` (`id`, `name`, `icon`, `description`, `description_full`, `metadata`) VALUES (1,'return_response_llm','↩L','Вернуть LLM ответ','Собираем полный запрос на LLM с учетом короткой и длинной памяти, всей связанной информации в БД и отдаем LLM для формирования наиболее качественного ответа.','')
  ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `icon` = VALUES(`icon`), `description` = VALUES(`description`), `description_full` = VALUES(`description_full`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step_type` (`id`, `name`, `icon`, `description`, `description_full`, `metadata`) VALUES (2,'llm_to_json','🧠','LLM -> JSON','Ожидает ответ от LLM в виде JSON. Далее каждый ключ JSON доступен в последующих шагах','')
  ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `icon` = VALUES(`icon`), `description` = VALUES(`description`), `description_full` = VALUES(`description_full`), `metadata` = VALUES(`metadata`);
