INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (19,2,2,'LLM -> JSON',12,'{\"transitions_before\":[],\"transitions_after\":[],\"llm_to_json_variable\":[{\"variable\":\"facts\",\"text\":\"список фактов\"}],\"prompt_user\":\"Ниже приведена краткая биография девушки %girl_title_saved%, написанная пользователем. Составь на её основе структурированный список фактов.\\n\\n=== Биография ===\\n%prompt_user%\\n\\nПравила:\\n1. Главный источник — биография: каждое её утверждение преврати в отдельный короткий факт (один факт — одно утверждение).\\n2. Факты не должны противоречить биографии и друг другу.\\n3. Если каких-то тем в биографии нет, аккуратно дополни правдоподобными деталями в согласии с текстом. Темы: подростковый возраст, учеба, отношения с родителями, любимые занятия и увлечения, любовные отношения, путешествия, работа.\\n4. Всего фактов должно быть 24-32.\\n\\n=== Important information about final response ===\\nPlease return your response in JSON format. The JSON response must contain follow keys: \\n- \\\"facts\\\": список фактов\\n\\ndocument_id всегда \'%text_to_lower_37_result_str%\'\\n\\nExample of JSON response:\\n{\\n  \\\"facts\\\": %fact_collection_output_format_18_result_str%\\n}\"}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (20,2,3,'fact_collection_add',15,'{\"tool_invoke\":{\"tool_name\":\"fact_collection_add\",\"inputs_map\":{\"collection_name\":\"fact_collection_girl_name\",\"data\":\"facts\",\"document_title\":\"girl_title_saved\",\"user_id\":\"user_id\"},\"outputs_map\":{\"facts_qty\":\"facts_qty\"}},\"transitions_before\":[],\"transitions_after\":[]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
