INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (23,2,3,'agent_create_or_update',9,'{\"tool_invoke\":{\"tool_name\":\"agent_create_or_update\",\"inputs_map\":{\"name\":\"text_to_lower_37_result_str\",\"title\":\"girl_title_saved\",\"node_id\":\"node_id\",\"workflow_id\":\"agent_workflow_id_28_result_int\",\"workflow_variable\":\"workflow_variable\",\"prompt_system\":\"girl_prompt_system\",\"description\":\"girl_description\",\"greeting\":\"girl_greeting\",\"user_id\":\"user_id\"},\"outputs_map\":{}},\"transitions_before\":[],\"transitions_after\":[]}')
