INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (24,5,2,'Генерация ответа',10,'{\"llm_to_json_variable\": [{\"variable\": \"girl_response\", \"text\": \"ответ девушки собеседнику (пустая строка, если отвечать не нужно)\"}], \"prompt_user\": \"=== Текущее время ===\\n%datetime_current_get_45_result_str%\\n\\n%if session_messages_29_result_str%\\n=== История переписки (детально, время сообщений в квадратных скобках) ===\\n%session_messages_29_result_str%\\n%endif%\\n\\n%if session_messages_result_processed%\\n=== Краткая выдержка истории переписки ===\\n%session_messages_result_processed%\\n%endif%\\n\\n%if qdrant_fact_search_25_result_str%\\n=== Информация о %agent_name% в базе данных ===\\n%qdrant_fact_search_25_result_str%\\n%endif%\\n\\n%if qdrant_fact_search_38_result_str%\\n=== Информация о %companion_title% в базе данных ===\\n%qdrant_fact_search_38_result_str%\\n%endif%\\n\\n%if qdrant_fact_search_39_result_str%\\n=== Информация о предыдущих соглашениях ===\\n%qdrant_fact_search_39_result_str%\\n%endif%\\n\\n=== %companion_title% пишет ===\\n%prompt_user%\\n\\n=== Что нужно ===\\n1. Вернуть короткий ответ: одно-два предложения, до 20 слов, как в мессенджере.\\n2. Тон приземленный и современный: реальная жизнь — работа, быт, кафе, сериалы, спорт, поездки, планы. Без поэзии, высокопарных метафор и старомодной романтики (стихи, кружева, шелк, винтажные духи), если %companion_title% сам об этом не спросил.\\n3. Ответ должен соответствовать текущему времени суток и времени сообщений в истории (в квадратных скобках): не здоровайся и не описывай утренние дела вечером или ночью, и наоборот.\\n4. КРИТИЧЕСКОЕ ПРАВИЛО: Если сообщение %companion_title% — это неразборчивый набор букв, опечатка, случайные символы или у тебя нет четкого понимания, что ответить, ты ОБЯЗАНА вернуть абсолютно пустую строку (ни одного символа, пробела или знака препинания). Не пытайся отшучиваться или переспрашивать в таких случаях.\\n5. Отвечай строго на языке: %user_language%.\\n\\n=== Important information about final response ===\\nPlease return your response in JSON format. The JSON response must contain follow keys: \\n- \\\"girl_response\\\": твой ответ собеседнику; если по правилам выше отвечать не нужно - строго пустая строка\\n\\nExample of JSON response:\\n{\\n  \\\"girl_response\\\": \\\"привет, как прошел день?\\\"\\n}\\n\\nExample of JSON response one more:\\n{\\n  \\\"girl_response\\\": \\\"\\\"\\n}\", \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (25,5,3,'qdrant_fact_search_girl',7,'{\"tool_invoke\":{\"tool_name\":\"qdrant_fact_search\",\"inputs_map\":{\"query_text\":\"search_query\",\"collection_name\":\"fact_collection_girl_name\",\"metadata_filter\":\"fact_collection_girl_filter\",\"limit\":\"fact_collection_limit\"},\"outputs_map\":{\"str\":\"qdrant_fact_search_result_girl\"}},\"transitions_before\":[],\"transitions_after\":[{\"variable\":\"prompt_user_question\",\"operator\":\"==\",\"value\":\"1\",\"step_id\":\"48\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (26,5,5,'Переменные',6,'{\"variable_conversion\": [{\"variable\": \"fact_collection_girl_filter\", \"text\": \"{\\\"document_id\\\":\\\"%girl_id%\\\"}\"}, {\"variable\": \"fact_collection_man_filter\", \"text\": \"{\\\"document_id\\\":\\\"%companion_name%\\\",\\\"tags\\\":\\\"%prompt_user_tags%\\\"}\"}, {\"variable\": \"fact_collection_talk_filter\", \"text\": \"{\\\"document_id\\\":\\\"%girl_id%_%companion_name%\\\",\\\"tags\\\":\\\"%prompt_user_tags%\\\"}\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (27,5,2,'Анализ сообщения',4,'{\"transitions_before\":[],\"transitions_after\":[{\"variable\":\"prompt_user_ignore\",\"operator\":\"==\",\"value\":\"1\",\"step_id\":\"107\"}],\"llm_to_json_variable\":[{\"variable\":\"session_messages_result_processed\",\"text\":\"краткая выдержка истории переписки: самое важное одним абзацем с привязкой ко времени (вчера вечером обсуждали.., сегодня утром договорились..), опираясь на метки времени сообщений\"},{\"variable\":\"prompt_user_category\",\"text\":\"категории, к которым можно отнести текст, что написаный %companion_title%. Например: образование, личная жизнь, любовь\"},{\"variable\":\"prompt_user_tags\",\"text\":\"таги через запятую, которые встречаются в тексте написаный %companion_title%. Например: машина,права,пунктуальность\"},{\"variable\":\"prompt_user_question\",\"text\":\"принимает значение 0 по умолчанию или 1, где:\\n1 означает - что в тексте написаный %companion_title%, есть вопрос к девушке о ее прошлом, ее увлечениях и на этот вопрос %girl_id% должна ответить. Если вопрос общий, например какая погода, время, новости, все что не касается лично девушки ответ только 0.\"},{\"variable\":\"search_query\",\"text\":\"самодостаточная переформулировка сообщения %companion_title% для векторного поиска по базе фактов: местоимения заменены на конкретные референты из истории переписки\"},{\"variable\":\"prompt_user_facts_companion\",\"text\":\"список фактов что касаются персонально о %companion_title%, его биографии, любимые занятия, образование, работа, жизненные факты. Если явных фактов нет - 0\"},{\"variable\":\"prompt_user_facts_talk\",\"text\":\"список фактов, что связаны с перепиской с %companion_title%, это могут быть какие-то договоронности, споры, дискусии на разные темы, мнения, мысли, желания, планы на будущее. Если явных фактов нет - 0\"},{\"variable\":\"prompt_user_ignore\",\"text\":\"принимает значение 0 по умолчанию или 1, где 1 означает - что отвечать не нужно: диалог уже завершен прощанием (девушка попрощалась или написала, что идет спать), а новое сообщение %companion_title% не несет нового содержания - только подтверждение (\'ок\', смайл, повторное \'спокойной ночи\') или повтор его предыдущих сообщений. ВАЖНО: сверяй текущее время со временем сообщений в истории (указано в квадратных скобках). Если после прощания реально прошла ночь и наступило утро нового дня - это новый диалог: отвечать нужно, строго 0, даже на простое \'доброе утро\'. Если же прощание было совсем недавно (минуты назад) и утро еще не наступило, то \'доброе утро\' не соответствует реальности - девушка уже спит и отвечать не нужно, строго 1\"}],\"prompt_user\":\"=== Текущее время ===\\n%datetime_current_get_45_result_str%\\n\\n=== %companion_title% пишет ===\\n%prompt_user%\\n%if session_messages_108_result_str%\\n\\n=== История переписки (время сообщений в квадратных скобках) ===\\n%session_messages_108_result_str%\\n%endif%\\n\\n=== Important information about final response ===\\nPlease return your response in JSON format. The JSON response must contain follow keys: \\n- \\\"session_messages_result_processed\\\": краткая выдержка истории переписки - самое важное одним абзацем с привязкой ко времени (вчера вечером обсуждали.., сегодня утром договорились..), опираясь на метки времени сообщений и текущее время. Если истории нет - пустая строка\\n- \\\"prompt_user_category\\\": категория (одно-два слова), к которым можно отнести текст написаный %companion_title%. Например: образование, личная жизнь, любовь\\n- \\\"prompt_user_tags\\\": таги через запятую, которые относятся к тексту %companion_title%. Например: машина,права,пунктуальность\\n- \\\"prompt_user_question\\\": принимает значение 0 по умолчанию или 1, где 1 означает - что в тексте написаный %companion_title%, есть вопрос к девушке о ее прошлом, ее увлечениях и на этот вопрос %girl_id% должна ответить. Если вопрос общий, например какая погода, время, новости, все что не касается лично девушки - только 0\\n- \\\"search_query\\\": самодостаточная переформулировка сообщения %companion_title% для поиска по базе фактов: замени местоимения на конкретные референты с учетом истории переписки; если сообщение уже самодостаточно - верни его как есть\\n- \\\"prompt_user_facts_companion\\\": список фактов что касаются персонально о %companion_title%: биографии, любимые занятия, образование, работа, жизненные факты\\n- \\\"prompt_user_facts_talk\\\": список фактов, что связаны с перепиской с %companion_title%, это могут быть какие-то договоронности, споры, дискусии на разные темы, мнения, мысли, желания\\n- \\\"prompt_user_ignore\\\": принимает значение 0 по умолчанию или 1, где 1 означает - что отвечать не нужно: диалог уже завершен прощанием (девушка попрощалась или написала, что идет спать), а новое сообщение %companion_title% не несет нового содержания - только подтверждение (\'ок\', смайл, повторное \'спокойной ночи\') или повтор его предыдущих сообщений. ВАЖНО: сверяй текущее время со временем сообщений в истории (указано в квадратных скобках). Если после прощания реально прошла ночь и наступило утро нового дня - это новый диалог: отвечать нужно, строго 0, даже на простое \'доброе утро\'. Если же прощание было совсем недавно (минуты назад) и утро еще не наступило, то \'доброе утро\' не соответствует реальности - девушка уже спит и отвечать не нужно, строго 1\\n\\nдля \'prompt_user_facts_companion\' используй document_id: \'%companion_name%\'\\nдля \'prompt_user_facts_talk\' используй document_id: \'%girl_id%_%companion_name%\'\\n\\nФакты не нужно придумывать и создавать. Они должны быть в тексте %companion_title% написаны явно. Если явных фактов нет - нужно вернуть 0 для ключей фактов.\\n\\nExample of JSON response:\\n{\\n  \\\"session_messages_result_processed\\\": \\\"вчера вечером говорили про работу и сериалы, она пожаловалась на усталость, попрощались на ночь\\\",\\n  \\\"prompt_user_category\\\": \\\"образование\\\",\\n  \\\"prompt_user_tags\\\": \\\"чтение,училище,фильмы\\\",\\n  \\\"prompt_user_question\\\": 0,\\n  \\\"search_query\\\": \\\"что Анна любит читать\\\",\\n  \\\"prompt_user_facts_companion\\\": %fact_collection_output_format_63_result_str%,\\n  \\\"prompt_user_facts_talk\\\": %fact_collection_output_format_63_result_str%,\\n  \\\"prompt_user_ignore\\\": 0\\n}\\n\\nExample of JSON response one more:\\n{\\n  \\\"session_messages_result_processed\\\": \\\"\\\",\\n  \\\"prompt_user_category\\\": \\\"погода\\\",\\n  \\\"prompt_user_tags\\\": \\\"дождь\\\",\\n  \\\"prompt_user_question\\\": 0,\\n  \\\"search_query\\\": \\\"какая погода\\\",\\n  \\\"prompt_user_facts_companion\\\": 0,\\n  \\\"prompt_user_facts_talk\\\": 0,\\n  \\\"prompt_user_ignore\\\": 1\\n}\"}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
