INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (50,6,2,'Новый факты',3,'{\"transitions_before\":[],\"transitions_after\":[],\"llm_to_json_variable\":[{\"variable\":\"prompt_user_facts_girl\",\"text\":\"в тексте написаный мужчиной есть вопрос к девушке о ее прошлом, ее увлечениях и на этот вопрос %girl_name% должна ответить. Придумай пару новых фактов о себе, которые помогут ответить на вопрос. Если уже существующие факты достаточно и конкретно отвечают на вопрос — новые придумывать НЕ нужно: верни 0 для ключа prompt_user_facts_girl. Каждый факт — одно-два коротких предложения (до 25 слов), обычным текстом без markdown-разметки. ВАЖНО: не выдумывай конкретные номера школ, точные адреса и названия реальных заведений — выдуманная конкретика противоречит реальности. Не называй город, район, улицу, реку или заведение, которых нет в уже существующих фактах: правдоподобный, но чужой топоним переселяет девушку в другой город. Если город в фактах назван — все места только в нём. Если города там нет — обобщай: школа рядом с домом, кафе в центре, набережная неподалёку. То же с именами собственными: имя человека или кличку питомца не придумывай. Если имя уже названо в существующих фактах — используй ровно его, буква в букву. Если имени там нет — пиши без имени: бабушка, попугай, подруга. Выдуманная кличка ссорится с той, что девушка уже называла, и собеседник ловит её на вранье.\"}],\"prompt_user\":\"=== %companion_title% пишет ===\\n%prompt_user%\\n%if qdrant_fact_search_65_result_str%\\n\\n=== Уже существующие факты о девушке %girl_title% ===\\n%qdrant_fact_search_65_result_str%\\n%endif%\\n\\n=== Important information about final response ===\\nPlease return your response in JSON format. The JSON response must contain follow keys: \\n- \\\"prompt_user_facts_girl\\\": в тексте написаный мужчиной есть вопрос к девушке о ее прошлом, ее увлечениях и на этот вопрос %girl_title% должна ответить. Придумай пару новых фактов о себе, которые помогут ответить на вопрос. Новые факты не должны противоречить уже существующим. Если уже существующие факты достаточно и конкретно отвечают на вопрос — новые придумывать НЕ нужно: верни 0 для ключа prompt_user_facts_girl. Каждый факт — одно-два коротких предложения (до 25 слов), обычным текстом без markdown-разметки. ВАЖНО: не выдумывай конкретные номера школ, точные адреса и названия реальных заведений — выдуманная конкретика противоречит реальности. Не называй город, район, улицу, реку или заведение, которых нет в уже существующих фактах: правдоподобный, но чужой топоним переселяет девушку в другой город. Если город в фактах назван — все места только в нём. Если города там нет — обобщай: школа рядом с домом, кафе в центре, набережная неподалёку. То же с именами собственными: имя человека или кличку питомца не придумывай. Если имя уже названо в существующих фактах — используй ровно его, буква в букву. Если имени там нет — пиши без имени: бабушка, попугай, подруга. Выдуманная кличка ссорится с той, что девушка уже называла, и собеседник ловит её на вранье.\\n\\nдля \'prompt_user_facts_girl\' используй для document_id: значение \'%girl_name%\' (пример: \\\"document_id\\\":\\\"%girl_name%\\\")\\n\\nExample of JSON response:\\n{\\n  \\\"prompt_user_facts_girl\\\": %fact_collection_output_format_49_result_str%\\n}\"}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
