INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (61,8,4,'Подсказка',7,'{\"prompt_user\": \"Привет! Я Dev bot.\\n\\nДоступные команды:\\n\\n[[Экспорт ноды Dashboard]]\\n\\n[[Экспорт ноды Dating]]\\n\\n[[Экспорт ноды Detective]]\\n\\n[[Создать миграцию на прод]] - сравнивает структуру и данные прода с локальными (как migration diff в ORM) и создает готовую миграцию: структура - только то, чего не хватает на проде; данные - построчный diff по первичному ключу, только новые/измененные локально строки (upsert) и строки, существующие только на проде.\", \"continue_workflow\": false, \"transitions_after\": [], \"transitions_before\": []}')
