INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (67,9,2,'Сообщение тестера',25,'{\"transitions_before\":[],\"transitions_after\":[],\"llm_to_json_variable\":[{\"variable\":\"test_message\",\"text\":\"следующее сообщение собеседника-тестера: короткое, естественное, по сценарию\"}],\"prompt_user\":\"Ты тестировщик чат-агента: играешь роль собеседника по имени %companion_title%, который переписывается с агентом %target_agent_title%.\\n\\n=== Сценарий тестирования ===\\n%prompt_user%\\n%if test_dialog%\\n\\n=== Диалог до этого момента ===\\n%test_dialog%\\n%endif%\\n\\nПридумай СЛЕДУЮЩЕЕ сообщение собеседника: короткое (до 30 слов), естественное, продолжает диалог и следует сценарию. Не повторяй уже отправленные сообщения.\\n\\n=== Important information about final response ===\\nPlease return your response in JSON format. The JSON response must contain follow keys: \\n- \\\"test_message\\\": следующее сообщение собеседника\\n\\nExample of JSON response:\\n{\\n  \\\"test_message\\\": \\\"Привет! Чем увлекаешься?\\\"\\n}\"}')
