INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (96,9,4,'Спросить сценарий',23,'{\"transitions_before\":[],\"transitions_after\":[],\"prompt_user\":\"Цель: %target_agent_title% (workflow #%test_workflow_id%, документ «%girl_id%»).\\n\\nНапишите сценарий тестирования: кто собеседник, о чем говорит, чего добивается. Итераций диалога: %test_iterations_limit%.\\n\\nЗаготовки (клик вставит текст в поле, отредактируйте под себя):\\n\\n[[+Ты мужчина 35 лет, познакомился с %target_agent_title% в приложении знакомств. Пиши коротко и неформально, как в мессенджере. Расспрашивай о ее увлечениях, работе и прошлом, делись фактами о себе (работа, машина, хобби) и мягко добивайся личной встречи.]]\\n\\n[[+Ты скептичный собеседник: подозреваешь, что %target_agent_title% — бот. Задавай личные вопросы о ее прошлом, ищи противоречия в ответах, возвращайся к ранее сказанному и проверяй, помнит ли она детали переписки.]]\\n\\n[[+Ты немногословный мужчина: пишешь по 2-5 слов, иногда с опечатками, отвечаешь односложно и редко задаешь вопросы. Проверка, как %target_agent_title% поддерживает вялый диалог.]]\",\"continue_workflow\":true}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (97,5,5,'Влить придуманные факты',17,'{\"transitions_before\":[],\"transitions_after\":[{\"variable\":\"agent_id\",\"operator\":\">\",\"value\":\"0\",\"step_id\":\"38\"}],\"variable_conversion\":[{\"variable\":\"qdrant_fact_search_25_result_str\",\"text\":\"%qdrant_fact_search_25_result_str%%if workflow_invoke_48_result_str%\\n%workflow_invoke_48_result_str%%endif%\"}]}')
