INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (101,2,4,'Спросить биографию',10,'{\"transitions_before\":[],\"transitions_after\":[],\"prompt_user\":\"Добавьте краткую биографию девушки %girl_title_saved%.\\n\\nНапишите свободным текстом 15-20 предложений: сколько лет, где родилась и живет, чем занимается, где училась, увлечения, семья, характер.\\n\\nПример:\\n[[+%girl_bio_example%]]\",\"continue_workflow\":true}')
