INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (109,5,2,'Валидация ответа',11,'{\"transitions_before\":[],\"transitions_after\":[{\"variable\":\"girl_response_skip\",\"operator\":\"==\",\"value\":\"1\",\"step_id\":\"107\"}],\"llm_to_json_variable\":[{\"variable\":\"girl_response_skip\",\"text\":\"1 - ответ не обязателен, пропускаем (девушка молчит), 0 - ответ важен, отправляем\"}],\"prompt_user\":\"=== Текущее время ===\\n%datetime_current_get_45_result_str%\\n\\n%if session_messages_29_result_str%=== История переписки (время сообщений в квадратных скобках) ===\\n%session_messages_29_result_str%\\n\\n%endif%=== %companion_title% пишет ===\\n%prompt_user%\\n\\n=== Черновик ответа девушки ===\\n%girl_response%\\n\\n=== Что нужно ===\\nТы строгий редактор реалистичности переписки. Реальная девушка не отвечает на каждое сообщение: часть реплик она оставляет без ответа, иногда просто молчит. Автоответ на все подряд выглядит фальшиво. Критически оцени, обязателен ли этот ответ.\\n\\ngirl_response_skip = 1 (пропустить ответ), если:\\n- сообщение %companion_title% - реплика-реакция, не требующая ответа: ок, ясно, понятно, ахах, круто, одиночный смайл\\n- черновик не несет новой информации: поддакивание, повтор уже сказанного, вежливое поддержание разговора ради разговора\\n- на суть сообщения девушка уже ответила ранее в истории\\n- черновик пустой или бессодержательный\\n\\ngirl_response_skip = 0 (ответ нужен), если:\\n- есть прямой вопрос к девушке или запрос информации\\n- обсуждаются планы, договоренности, место или время встречи\\n- новая тема или сообщение с новыми фактами, на которые естественно отреагировать\\n- если уже пропустила два или три обращения, то из вежливости можно ответить, но только по делу, если запросы вежливые и не навязчивые\\n- первое сообщение диалога или сообщение после долгой паузы (сравни метки времени с текущим временем)\\n- %companion_title% делится чем-то личным и молчание выглядело бы грубо\\n\\nЕсли сомневаешься между 0 и 1 - выбирай 1: молчание реалистичнее лишнего ответа.\\n\\n=== Important information about final response ===\\nPlease return your response in JSON format. The JSON response must contain follow keys: \\n- \\\"girl_response_skip\\\": 0 или 1, где 1 - ответ пропускаем (девушка молчит), 0 - ответ отправляем\\n\\nExample of JSON response:\\n{\\n  \\\"girl_response_skip\\\": 1\\n}\"}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (110,10,1,'Перевод',0,'{\"transitions_before\": [], \"transitions_after\": [], \"prompt_user\": \"Переведи текст с языка [%language_from%] на язык [%language_to%].\\n\\n=== Текст ===\\n%prompt_user%\\n\\n=== Правила ===\\n1. Верни ТОЛЬКО перевод, без пояснений, вступлений и кавычек вокруг результата.\\n2. Сохраняй стиль, тон, регистр и форматирование исходного текста (переносы строк, списки, эмодзи).\\n3. Имена собственные не переводи.\\n4. Если текст уже на целевом языке - верни его без изменений.\"}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
