INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (115,2,4,'Нет девушек',23,'{\"transitions_before\": [], \"transitions_after\": [], \"prompt_user\": \"У вас пока нет созданных девушек. Создать: [[/girl_create]]\", \"continue_workflow\": false}')
