INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (116,11,2,'Анализ факта',0,'{\"transitions_before\":[],\"transitions_after\":[{\"variable\":\"verify_query\",\"operator\":\"==\",\"value\":\"0\",\"step_id\":\"119\"}],\"llm_to_json_variable\":[{\"variable\":\"verify_query\",\"text\":\"поисковый запрос для проверки привязки факта к реальности или 0, если проверять нечего\"}],\"prompt_user\":\"=== Факт из базы ===\\n%prompt_user%\\n\\n=== Что нужно ===\\nПерсонаж выдуманный, но привязки к реальному миру должны быть правдоподобны. Найди в факте привязки, которые можно проверить веб-поиском: школы и вузы с номерами, адреса, названия заведений, утверждения что находится где (район, город). Если такие есть - сформулируй ОДИН короткий поисковый запрос для проверки самой конкретной привязки (например: школа 157 Киев какой район). Если проверяемых привязок нет (вкусы, характер, обобщенные места вроде кафе в центре) - верни 0.\\n\\n=== Important information about final response ===\\nPlease return your response in JSON format. The JSON response must contain follow keys: \\n- \\\"verify_query\\\": поисковый запрос или 0, если проверять нечего\\n\\nExample of JSON response:\\n{\\n  \\\"verify_query\\\": \\\"школа 157 Киев какой район\\\"\\n}\\n\\nExample of JSON response one more:\\n{\\n  \\\"verify_query\\\": 0\\n}\"}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (117,11,3,'web_search',1,'{\"tool_invoke\":{\"tool_name\":\"web_search\",\"inputs_map\":{\"query\":\"verify_query\",\"limit\":\"verify_search_limit\"},\"outputs_map\":{}},\"transitions_before\":[],\"transitions_after\":[]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (118,11,2,'Вердикт',2,'{\"transitions_before\":[],\"transitions_after\":[],\"llm_to_json_variable\":[{\"variable\":\"verify_status\",\"text\":\"вердикт проверки: ok | corrected | unverifiable\"},{\"variable\":\"document_corrected\",\"text\":\"исправленный текст факта при corrected, иначе пустая строка\"}],\"prompt_user\":\"=== Проверяемый факт ===\\n%prompt_user%\\n\\n=== Поисковый запрос ===\\n%verify_query%\\n\\n=== Результаты веб-поиска ===\\n%web_search_117_result_results%\\n\\n=== Что нужно ===\\nСверь привязки факта с результатами поиска и вынеси вердикт:\\n- ok: привязки не противоречат реальности\\n- corrected: есть противоречие (заведение в другом районе, не существует) - исправь факт минимальной правкой, сохранив суть: замени привязку на реальную из результатов поиска или обобщи (школа рядом с домом)\\n- unverifiable: результаты поиска не позволяют судить\\n\\n=== Important information about final response ===\\nPlease return your response in JSON format. The JSON response must contain follow keys: \\n- \\\"verify_status\\\": ok | corrected | unverifiable\\n- \\\"document_corrected\\\": исправленный полный текст факта, только при corrected; иначе пустая строка\\n\\nExample of JSON response:\\n{\\n  \\\"verify_status\\\": \\\"corrected\\\",\\n  \\\"document_corrected\\\": \\\"Училась в лицее на Оболони, недалеко от дома\\\"\\n}\"}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (119,11,3,'Сохранить вердикт',3,'{\"tool_invoke\":{\"tool_name\":\"fact_verify_result_save\",\"inputs_map\":{\"fact_id\":\"fact_id\",\"verify_status\":\"verify_status\",\"document_corrected\":\"document_corrected\"},\"outputs_map\":{}},\"transitions_before\":[],\"transitions_after\":[]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (120,11,4,'Отчет',4,'{\"transitions_before\":[],\"transitions_after\":[],\"prompt_user\":\"%verify_status%\",\"continue_workflow\":false}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (121,12,4,'Вернуть список команд',0,'{\"prompt_user\": \"%agent_greeting%\", \"continue_workflow\": false, \"transitions_after\": [], \"transitions_before\": [{\"value\": \"/new_case\", \"step_id\": \"156\", \"operator\": \"==\", \"variable\": \"prompt_user\"}, {\"value\": \"/accuse\", \"step_id\": \"131\", \"operator\": \"==\", \"variable\": \"prompt_user\"}, {\"value\": \"/close_case\", \"step_id\": \"207\", \"operator\": \"==\", \"variable\": \"prompt_user\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (122,12,2,'Сгенерировать дело',3,'{\"transitions_before\": [], \"transitions_after\": [], \"llm_to_json_variable\": [{\"variable\": \"victim_name\", \"text\": \"имя жертвы\"}, {\"variable\": \"crime_description\", \"text\": \"описание преступления для игрока, без намека на виновного\"}, {\"variable\": \"guilty_suspect_name\", \"text\": \"имя виновного подозреваемого\"}, {\"variable\": \"solution_reveal\", \"text\": \"финальная разгадка дела\"}, {\"variable\": \"suspect_1_name\", \"text\": \"имя подозреваемого 1\"}, {\"variable\": \"suspect_1_sheet\", \"text\": \"легенда подозреваемого 1\"}, {\"variable\": \"suspect_1_greeting\", \"text\": \"приветствие подозреваемого 1\"}, {\"variable\": \"suspect_2_name\", \"text\": \"имя подозреваемого 2\"}, {\"variable\": \"suspect_2_sheet\", \"text\": \"легенда подозреваемого 2\"}, {\"variable\": \"suspect_2_greeting\", \"text\": \"приветствие подозреваемого 2\"}, {\"variable\": \"suspect_3_name\", \"text\": \"имя подозреваемого 3\"}, {\"variable\": \"suspect_3_sheet\", \"text\": \"легенда подозреваемого 3\"}, {\"variable\": \"suspect_3_greeting\", \"text\": \"приветствие подозреваемого 3\"}, {\"variable\": \"suspect_4_name\", \"text\": \"имя подозреваемого 4\"}, {\"variable\": \"suspect_4_sheet\", \"text\": \"легенда подозреваемого 4\"}, {\"variable\": \"suspect_4_greeting\", \"text\": \"приветствие подозреваемого 4\"}, {\"variable\": \"autopsy_report\", \"text\": \"отчет судмедэксперта о вскрытии\"}, {\"variable\": \"evidence_report\", \"text\": \"отчет полиции о найденных на месте уликах\"}, {\"variable\": \"witness_statements\", \"text\": \"показания свидетелей (не подозреваемых)\"}, {\"variable\": \"bank_records\", \"text\": \"банковские записи, релевантные подозреваемым\"}, {\"variable\": \"scene_inventory\", \"text\": \"опись примечательных предметов на месте преступления\"}, {\"variable\": \"suspect_1_interrogation\", \"text\": \"протокол предварительного допроса подозреваемого 1 полицией\"}, {\"variable\": \"suspect_2_interrogation\", \"text\": \"протокол предварительного допроса подозреваемого 2 полицией\"}, {\"variable\": \"suspect_3_interrogation\", \"text\": \"протокол предварительного допроса подозреваемого 3 полицией\"}, {\"variable\": \"suspect_4_interrogation\", \"text\": \"протокол предварительного допроса подозреваемого 4 полицией\"}, {\"variable\": \"suspect_1_brief\", \"text\": \"краткая опорная справка по подозреваемому 1: алиби в двух словах + мотив\"}, {\"variable\": \"suspect_2_brief\", \"text\": \"краткая опорная справка по подозреваемому 2: алиби в двух словах + мотив\"}, {\"variable\": \"suspect_3_brief\", \"text\": \"краткая опорная справка по подозреваемому 3: алиби в двух словах + мотив\"}, {\"variable\": \"suspect_4_brief\", \"text\": \"краткая опорная справка по подозреваемому 4: алиби в двух словах + мотив\"}, {\"variable\": \"suspect_1_relation\", \"text\": \"короткая связь подозреваемого 1 с жертвой (сосед/родственник/коллега/друг и т.п.)\"}, {\"variable\": \"suspect_2_relation\", \"text\": \"короткая связь подозреваемого 2 с жертвой (сосед/родственник/коллега/друг и т.п.)\"}, {\"variable\": \"suspect_3_relation\", \"text\": \"короткая связь подозреваемого 3 с жертвой (сосед/родственник/коллега/друг и т.п.)\"}, {\"variable\": \"suspect_4_relation\", \"text\": \"короткая связь подозреваемого 4 с жертвой (сосед/родственник/коллега/друг и т.п.)\"}], \"prompt_user\": \"Придумай честное, разрешимое детективное дело в жанре классического детектива (как Агата Кристи). Правила:\\n\\n1. Ровно 4 подозреваемых с разными именами.\\n2. Ровно один из них виновен в убийстве.\\n3. У каждого подозреваемого есть алиби, личность, отношение к жертве и мотив (или его отсутствие).\\n4. Алиби невиновных подозреваемых логически непротиворечивы и не имеют дыр.\\n5. Алиби виновного имеет ОДНУ подходящую, но не самоочевидную нестыковку (например, упоминает деталь, которая противоречит времени/месту/показаниям другого подозреваемого) - ее можно найти, если задать точные уточняющие вопросы, но виновный сам никогда не признается напрямую.\\n6. Все подозреваемые знают общие факты дела (время, место, орудие) одинаково - не противоречь себе между персонажами.\\n7. Пиши строго на языке: %user_language%.\\n8. Место преступления должно быть основано на теме: \\\"%location_theme%\\\". Придумай конкретные детали (какое именно помещение/локация в рамках этой темы, планировка, атмосфера) своими словами - не используй клише вроде кабинета/окна/кинжала, если они не связаны с этой темой напрямую.\\n9. Орудие убийства должно быть основано на теме: \\\"%weapon_theme%\\\". Опиши, как именно оно было применено в этом деле, с деталями, специфичными для места преступления.\\n10. Виновным должен быть РОВНО подозреваемый под номером %guilty_suspect_index% - то есть guilty_suspect_name должно точно совпадать с suspect_%guilty_suspect_index%_name. Остальные три подозреваемых невиновны.\\n11. Мотив должен быть минимум у ДВУХ подозреваемых, включая виновного. У невиновного(ых) с мотивом - это ложный след: мотив выглядит правдоподобно, но не имеет отношения к настоящему убийству. У виновного - мотив настоящий. НЕ делай мотив виновного самым сильным, самым очевидным или единственным в деле - подавай мотивы разных подозреваемых одинаково правдоподобно, чтобы само наличие мотива не выдавало виновного с первого взгляда.\\n12. У каждого подозреваемого должна быть РАЗНАЯ по типу связь с жертвой (не повторяй один и тот же тип дважды): например сосед, родственник (уточни степень родства), коллега по работе, близкий друг, деловой партнер, бывший супруг(а), прислуга/наемный работник и т.п.\\n\\n=== Что нужно вернуть (основное дело) ===\\n- victim_name: имя жертвы\\n- crime_description: 2-4 предложения для игрока: кто жертва, где и как произошло убийство, орудие, примерное время - БЕЗ намека на виновного\\n- guilty_suspect_name: имя виновного (см. правило 10 - должно совпадать с suspect_%guilty_suspect_index%_name)\\n- solution_reveal: финальная разгадка на 3-5 предложений, которая будет показана игроку ПОСЛЕ обвинения - объясняет мотив виновного и в чем именно была нестыковка в его алиби\\n- suspect_1_name, suspect_2_name, suspect_3_name, suspect_4_name: имена подозреваемых\\n- suspect_1_sheet, suspect_2_sheet, suspect_3_sheet, suspect_4_sheet: полная легенда персонажа текстом (5-8 предложений): кто он жертве, где был во время убийства (алиби), характер, как себя ведет на допросе. Для виновного - явно опиши его мотив (см. правило 11) и ОСТОРОЖНО впиши нестыковку в алиби, но не пиши прямо \'он виновен\'\\n- suspect_1_greeting, suspect_2_greeting, suspect_3_greeting, suspect_4_greeting: короткая фраза (1 предложение) в характере, которой подозреваемый встречает детектива на допросе\\n\\n=== Дополнительные материалы дела (для сержанта полиции и досье) - ВСЕ должны быть согласованы друг с другом и с основным делом выше, без противоречий ===\\n- autopsy_report (3-5 предложений): заключение судмедэксперта - причина смерти, орудие (см. правило 9), примерное время смерти, дополнительные медицинские наблюдения. Должно согласовываться с crime_description и с нестыковкой в алиби виновного.\\n- evidence_report (3-5 предложений): улики, найденные на месте преступления, специфичные для места (см. правило 8) - дают зацепки, но не раскрывают виновного напрямую.\\n- witness_statements (2-3 показания): что видели/слышали свидетели (НЕ подозреваемые, например соседи, прислуга, прохожие) - без прямого разоблачения виновного.\\n- bank_records (2-4 предложения): финансовые записи 1-2 подозреваемых с мотивом (см. правило 11) - правдоподобный финансовый мотив.\\n- scene_inventory (4-6 предметов списком): примечательные предметы, найденные в помещении/на месте преступления, специфичные для места (см. правило 8), часть из которых может быть уликами.\\n- suspect_1_interrogation, suspect_2_interrogation, suspect_3_interrogation, suspect_4_interrogation (3-5 предложений каждый): протокол ПЕРВИЧНОГО опроса подозреваемого полицией (до начала игры) - должен покрывать: краткое алиби, род занятий/профессию, физические приметы (рост, телосложение, возраст), характер отношений с жертвой, семейное положение. Должен ТОЧНО СОВПАДАТЬ с фактами из suspect_N_sheet, не противоречить им.\\n- suspect_1_brief, suspect_2_brief, suspect_3_brief, suspect_4_brief (ОДНО короткое предложение каждый, 10-15 слов): опорная справка для игрока сразу под именем подозреваемого в списке - алиби в двух словах + есть ли видимый мотив. Например: \'Утверждает, что был в своей комнате всю ночь; видимого мотива нет.\' или \'Был в саду; крупный долг перед жертвой.\' ДОЛЖНО совпадать по сути с suspect_N_interrogation и suspect_N_sheet, просто короче.\\n- suspect_1_relation, suspect_2_relation, suspect_3_relation, suspect_4_relation (2-5 слов каждый): короткая категория связи с жертвой (см. правило 12) - например \'сосед\', \'двоюродный брат\', \'коллега по работе\', \'близкий друг детства\', \'деловой партнер\', \'бывшая супруга\'. ДОЛЖНА совпадать с фактами из suspect_N_sheet, не противоречить им.\\n\\n=== Important information about final response ===\\nPlease return your response in JSON format with exactly these keys: victim_name, crime_description, guilty_suspect_name, solution_reveal, suspect_1_name, suspect_1_sheet, suspect_1_greeting, suspect_2_name, suspect_2_sheet, suspect_2_greeting, suspect_3_name, suspect_3_sheet, suspect_3_greeting, suspect_4_name, suspect_4_sheet, suspect_4_greeting, autopsy_report, evidence_report, witness_statements, bank_records, scene_inventory, suspect_1_interrogation, suspect_2_interrogation, suspect_3_interrogation, suspect_4_interrogation, suspect_1_brief, suspect_2_brief, suspect_3_brief, suspect_4_brief, suspect_1_relation, suspect_2_relation, suspect_3_relation, suspect_4_relation.\"}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (123,12,3,'agent_workflow_id_talk',4,'{\"transitions_before\": [], \"transitions_after\": [], \"tool_invoke\": {\"tool_name\": \"agent_workflow_id\", \"inputs_map\": {\"name\": \"detective_talk_workflow_name\"}, \"outputs_map\": {}}}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (124,12,3,'Собрать очередь подозреваемых',5,'{\"transitions_before\": [], \"transitions_after\": [], \"tool_invoke\": {\"tool_name\": \"detective_suspects_queue_build\", \"inputs_map\": {\"session_uuid\": \"session_uuid\", \"suspect_1_name\": \"suspect_1_name\", \"suspect_1_sheet\": \"suspect_1_sheet\", \"suspect_1_greeting\": \"suspect_1_greeting\", \"suspect_1_interrogation\": \"suspect_1_interrogation\", \"suspect_2_name\": \"suspect_2_name\", \"suspect_2_sheet\": \"suspect_2_sheet\", \"suspect_2_greeting\": \"suspect_2_greeting\", \"suspect_2_interrogation\": \"suspect_2_interrogation\", \"suspect_3_name\": \"suspect_3_name\", \"suspect_3_sheet\": \"suspect_3_sheet\", \"suspect_3_greeting\": \"suspect_3_greeting\", \"suspect_3_interrogation\": \"suspect_3_interrogation\", \"suspect_4_name\": \"suspect_4_name\", \"suspect_4_sheet\": \"suspect_4_sheet\", \"suspect_4_greeting\": \"suspect_4_greeting\", \"suspect_4_interrogation\": \"suspect_4_interrogation\"}, \"outputs_map\": {}}}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (129,12,3,'Сохранить дело',10,'{\"transitions_before\": [], \"transitions_after\": [], \"tool_invoke\": {\"tool_name\": \"detective_case_create\", \"inputs_map\": {\"session_uuid\": \"session_uuid\", \"user_id\": \"user_id\", \"victim_name\": \"victim_name\", \"crime_description\": \"crime_description\", \"guilty_suspect_name\": \"guilty_suspect_name\", \"solution_reveal\": \"solution_reveal\"}, \"outputs_map\": {}}}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (130,12,4,'Дело открыто',11,'{\"prompt_user\": \"🕵️ Открыто новое дело\\n\\nЖертва: %victim_name%\\n\\n%crime_description%\\n\\n📋 Сержант Ковальски докладывает: сразу после обнаружения тела полиция собрала первичные данные.\\n\\nВскрытие: %autopsy_report%\\n\\nПодозреваемые:\\n[[%suspect_1_name%]] (%suspect_1_relation%) — %suspect_1_brief%\\n[[%suspect_2_name%]] (%suspect_2_relation%) — %suspect_2_brief%\\n[[%suspect_3_name%]] (%suspect_3_relation%) — %suspect_3_brief%\\n[[%suspect_4_name%]] (%suspect_4_relation%) — %suspect_4_brief%\\n\\nПолное досье (улики, свидетели, банк, опись места) можно узнать у Сержанта полиции в списке агентов.\\n\\nВыбери подозреваемого в списке слева и начни допрос. Когда будешь готов назвать виновного, напиши [[/accuse]].\", \"continue_workflow\": false, \"transitions_after\": [], \"transitions_before\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
