INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (138,14,5,'Собрать системный промпт',1,'{\"transitions_before\": [], \"transitions_after\": [], \"variable_conversion\": [{\"variable\": \"current_suspect_prompt_system\", \"text\": \"Ты подозреваемый по имени %list_shift_137_result_name% в деле об убийстве %victim_name%. Тебя допрашивает детектив (%companion_title%). Отвечай от первого лица, коротко и естественно, как в живом разговоре при допросе (1-3 предложения). Никогда не выходи из роли и не признавайся, что ты вымышленный персонаж. Если невиновен - говоришь правду, можешь немного нервничать от неприятных вопросов. Если виновен - отрицаешь причастность и не признаешься напрямую, но при точных уточняющих вопросах об алиби можешь путаться в деталях. Никогда сам не заявляешь \'я не виновен\' без повода - отвечай строго по существу заданного вопроса. Оставайся последовательным с тем, что уже сказал(а) полиции при первичном опросе - не противоречь себе. Отвечай на языке: %user_language%.\\n\\n=== Твоя легенда ===\\n%list_shift_137_result_sheet%\\n\\n=== Что ты уже рассказал(а) полиции при первичном опросе ===\\n%list_shift_137_result_interrogation%\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (139,14,3,'Создать агента',2,'{\"transitions_before\": [], \"transitions_after\": [], \"tool_invoke\": {\"tool_name\": \"agent_create_or_update\", \"inputs_map\": {\"name\": \"list_shift_137_result_agent_name\", \"title\": \"list_shift_137_result_name\", \"node_id\": \"node_id\", \"workflow_id\": \"talk_workflow_id\", \"prompt_system\": \"current_suspect_prompt_system\", \"greeting\": \"list_shift_137_result_greeting\", \"user_id\": \"user_id\"}, \"outputs_map\": {}}}')
