INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (140,12,6,'Создать подозреваемых (цикл)',6,'{\"transitions_before\": [], \"transitions_after\": [], \"workflow_invoke\": {\"workflow_id\": 14, \"inputs_map\": {\"suspects_queue\": \"detective_suspects_queue_build_124_result_list\", \"node_id\": \"node_id\", \"talk_workflow_id\": \"agent_workflow_id_123_result_int\", \"victim_name\": \"victim_name\", \"companion_title\": \"companion_title\", \"user_id\": \"user_id\"}, \"outputs_map\": {\"list_shift_137_result_rest\": \"detective_suspects_queue_build_124_result_list\"}, \"repeat\": {\"count\": 4}}}')
