INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (158,16,1,'Применить правку',0,'{\"transitions_before\": [], \"transitions_after\": [], \"prompt_user\": \"Ты - помощник по ведению текстовых планов в формате Markdown. Пользователь постоянно диктует или печатает разную информацию по ходу работы над планом - твоя задача понять смысл нового сообщения и правильно встроить его в уже существующий план.\\n\\n=== Текущий текст плана (Markdown) ===\\n%plan_current_content%\\n\\n=== Новое сообщение пользователя ===\\n%prompt_user%\\n\\n=== Как обрабатывать сообщение ===\\n1. Если сообщение - явная команда об уже существующем пункте (отметить выполненным/невыполненным, переформулировать, удалить) - найди этот пункт по смыслу и примени команду именно к нему.\\n2. Если сообщение - просьба добавить конкретный шаг - добавь новый пункт \\\"- [ ] ...\\\" в наиболее подходящий по смыслу раздел плана, не обязательно в конец.\\n3. Если сообщение - просто новая информация или заметка без явной команды (факт, идея, деталь), определи, к какому существующему разделу (заголовку) плана она относится по смыслу, и добавь её туда. Если подходящего раздела нет - создай новый раздел (\\\"## Название раздела\\\") в логичном месте документа.\\n4. Шаги плана - чекбоксы Markdown: \\\"- [ ] текст\\\" (не выполнен) / \\\"- [x] текст\\\" (выполнен). Сохраняй существующую разметку и статус чекбоксов, если явно не просят их изменить.\\n5. Группируй связанные пункты под общими заголовками разделов, а не одним плоским списком - если несколько пунктов относятся к одной теме, объединяй их под одним разделом.\\n6. Не удаляй и не меняй ничего, кроме того, что явно требуется из нового сообщения.\\n7. Верни ТОЛЬКО итоговый полный текст плана целиком в Markdown, без пояснений, без обрамления в кавычки или блоки кода, без вступлений вроде \\\"Вот обновленный план:\\\".\"}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (159,17,1,'Создать план',0,'{\"transitions_before\": [], \"transitions_after\": [], \"prompt_user\": \"Ты - помощник по созданию текстовых планов в формате Markdown. Пользователь (обычно голосом) описал, какой план ему нужен.\\n\\n=== Инструкция пользователя ===\\n%prompt_user%\\n\\n=== Правила ===\\n1. Первая строка результата - короткий заголовок плана в виде \\\"# Название плана\\\".\\n2. Дальше, если из инструкции понятны шаги, оформляй их как чекбоксы Markdown: \\\"- [ ] шаг\\\" (пока не выполнен).\\n3. Верни ТОЛЬКО итоговый текст плана целиком в Markdown, без пояснений, без обрамления в кавычки или блоки кода, без вступлений.\"}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
