INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (162,19,3,'Загрузить проект',0,'{\"tool_invoke\":{\"tool_name\":\"planning_project_load\",\"inputs_map\":{\"project_id\":\"planning_project_id\"},\"outputs_map\":{\"idea\":\"project_idea\",\"phases_context\":\"phases_context\"}},\"transitions_before\":[],\"transitions_after\":[]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (163,19,2,'Анализ идеи',1,'{\"prompt_user\": \"=== ИДЕЯ ПРОДУКТА ===\\n%project_idea%\\n\\nПроанализируй идею продукта. Верни JSON с ключом phase_result содержащим Markdown.\\n\\nСтруктура документа (строго соблюдать все разделы):\\n## Суть идеи\\n## Целевая аудитория\\n## Ключевая проблема\\n## Гипотеза решения\\n## Уникальный угол\\n## Ключевые допущения\\n## Риски\\n## Рекомендации\\n## Ключевые выводы\\n\\n## 🔴 Критический разбор — Devil\'s Advocate (ОБЯЗАТЕЛЬНЫЙ раздел)\\nНезависимо от привлекательности идеи — три конкретные причины провала, что уже закрывает эту потребность бесплатно/дёшево, три условия которые должны оказаться правдой для успеха.\\n\\n## Phase Summary (ОБЯЗАТЕЛЬНЫЙ раздел в конце документа)\\n- KEY_INSIGHT: одно предложение — главное открытие этой фазы\\n- MAIN_RISK: один главный риск\\n- TARGET_CUSTOMER: конкретный сегмент, не «все»\\n- MARKET_SIZE: конкретная цифра SAM в USD\\n- CRITICAL_ASSUMPTION: одно ключевое условие для успеха\\n\\nПравильно экранируй кавычки.\\\\n\\\\nОтвечай на языке: %user_language%.\", \"transitions_after\": [], \"transitions_before\": [], \"llm_to_json_variable\": [{\"text\": \"структурированный анализ идеи продукта (800-1200 слов Markdown) с разделами: ## Суть идеи, ## Целевая аудитория, ## Ключевая проблема, ## Гипотеза решения, ## Уникальный угол, ## Ключевые допущения, ## Риски. Используй маркированные списки и выделение жирным, ## Рекомендации (3-5 конкретных следующих шагов для основателя), ## Ключевые выводы (топ-3 инсайта маркированным списком).\\n\\n## 🔴 Критический разбор — Devil\'s Advocate (обязательный раздел)\\nНезависимо от привлекательности идеи — найди и сформулируй честно:\\n1. Три конкретные причины, почему эта идея провалится\\n2. Что уже существует бесплатно или дёшево и закрывает ту же потребность\\n3. Три ключевых условия, которые должны оказаться правдой для успеха\\n\\n---\\n\\n## Phase Summary для следующих фаз (обязательный раздел, добавить в конце)\\n- KEY_INSIGHT: одно предложение — главное открытие этой фазы\\n- MAIN_RISK: один главный риск, который может уничтожить проект\\n- TARGET_CUSTOMER: кто именно платит, кто пользуется (конкретный сегмент, не «все»)\\n- MARKET_SIZE: конкретная цифра SAM в USD (для tech-фазы — N/A)\\n- CRITICAL_ASSUMPTION: одно ключевое условие, которое должно оказаться правдой для успеха\", \"variable\": \"phase_result\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
