INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (166,20,2,'Исследование рынка',3,'{\"prompt_user\": \"=== ИДЕЯ ПРОДУКТА ===\\n%project_idea%\\n\\n=== ПРЕДЫДУЩИЙ АНАЛИЗ ===\\n%phases_context%\\n\\n=== ДАННЫЕ ИЗ ИНТЕРНЕТА ===\\n%research_loop_217_result_str%\\n\\nСинтезируй детальное исследование рынка на основе найденных данных. Используй конкретные цифры и факты. Верни JSON с ключом phase_result содержащим Markdown-отчёт.\\\\n\\\\nОтвечай на языке: %user_language%.\", \"chunk_variable\": \"research_loop_217_result_str\", \"transitions_after\": [], \"transitions_before\": [], \"llm_to_json_variable\": [{\"text\": \"полное исследование рынка (1000-1500 слов Markdown) с разделами: ## Обзор рынка, ## Размер рынка (TAM/SAM/SOM с оценками), ## Конкуренты (таблица: Название | Сегмент | Ключевая фича | Цена | Сильные стороны | Слабые стороны), ## Тренды (макро и продуктовые), ## Белые пятна и возможности, ## Ключевые инсайты, ## Рекомендации (на какой сегмент фокусироваться и как позиционироваться относительно конкурентов), ## Ключевые выводы (топ-3 рыночных инсайта).\\n\\n---\\n\\n## Phase Summary для следующих фаз (обязательный раздел, добавить в конце)\\n- KEY_INSIGHT: одно предложение — главное открытие этой фазы\\n- MAIN_RISK: один главный риск, который может уничтожить проект\\n- TARGET_CUSTOMER: кто именно платит, кто пользуется (конкретный сегмент, не «все»)\\n- MARKET_SIZE: конкретная цифра SAM в USD (для tech-фазы — N/A)\\n- CRITICAL_ASSUMPTION: одно ключевое условие, которое должно оказаться правдой для успеха\", \"variable\": \"phase_result\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
