INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (169,21,2,'Продуктовый план',3,'{\"prompt_user\":\"=== ИДЕЯ ПРОДУКТА ===\\n%project_idea%\\n\\n=== ПРЕДЫДУЩИЙ АНАЛИЗ ===\\n%phases_context%\\n\\n=== ДАННЫЕ ИЗ ИНТЕРНЕТА ===\\n%research_loop_230_result_str%\\n\\nСоздай детальный продуктовый план на основе реальных отзывов, болей пользователей и фич конкурентов. Опирайся на найденные данные. Верни JSON с ключом phase_result содержащим Markdown.\\n\\nОтвечай на языке: %user_language%.\",\"chunk_variable\":\"research_loop_230_result_str\",\"transitions_after\":[],\"transitions_before\":[],\"llm_to_json_variable\":[{\"text\":\"продуктовый план (1000-1500 слов Markdown) с разделами: ## Видение продукта, ## Стратегические цели (SMART с KPI), ## Боли пользователей (из реальных отзывов), ## Функции (таблица: Функция | Приоритет MoSCoW | Описание | Ценность), ## MVP scope (что входит / что нет), ## Дорожная карта (таблица: Фаза | Срок | Ключевые deliverables | Цель), ## Метрики успеха, ## Рекомендации (приоритеты для первого MVP-спринта), ## Ключевые выводы (топ-3 продуктовых решения).\\n\\n---\\n\\n## Phase Summary для следующих фаз (обязательный раздел, добавить в конце)\\n- KEY_INSIGHT: одно предложение — главное открытие этой фазы\\n- MAIN_RISK: один главный риск, который может уничтожить проект\\n- TARGET_CUSTOMER: кто именно платит, кто пользуется (конкретный сегмент, не «все»)\\n- MARKET_SIZE: конкретная цифра SAM в USD (для tech-фазы — N/A)\\n- CRITICAL_ASSUMPTION: одно ключевое условие, которое должно оказаться правдой для успеха\",\"variable\":\"phase_result\"}],\"thinking_enable\":false}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
