INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (172,22,2,'Тех. архитектура',3,'{\"prompt_user\": \"=== ИДЕЯ ПРОДУКТА ===\\n%project_idea%\\n\\n=== ПРЕДЫДУЩИЙ АНАЛИЗ ===\\n%phases_context%\\n\\n=== ДАННЫЕ ИЗ ИНТЕРНЕТА ===\\n%research_loop_232_result_str%\\n\\nСпроектируй техническую архитектуру продукта на основе найденных данных о стеках конкурентов и open-source аналогов. Учти MVP scope из продуктового плана. Верни JSON с ключом phase_result.\\n\\nОтвечай на языке: %user_language%.\", \"chunk_variable\": \"research_loop_232_result_str\", \"transitions_after\": [], \"transitions_before\": [], \"llm_to_json_variable\": [{\"text\": \"техническая архитектура (1000-1500 слов Markdown) с разделами: ## Технологический стек (таблица: Слой | Технология | Версия | Обоснование), ## Архитектурная схема (текстовое ASCII-описание компонентов), ## Ключевые компоненты и их взаимодействие, ## Инфраструктура (cloud, CI/CD, мониторинг), ## API Design (ключевые endpoints), ## Технические риски и митигация, ## Оценка сложности (S/M/L/XL по компонентам), ## Рекомендации (технические решения первого приоритета), ## Ключевые выводы (топ-3 архитектурных инсайта).\\n\\n---\\n\\n## Phase Summary для следующих фаз (обязательный раздел, добавить в конце)\\n- KEY_INSIGHT: одно предложение — главное открытие этой фазы\\n- MAIN_RISK: один главный риск, который может уничтожить проект\\n- TARGET_CUSTOMER: кто именно платит, кто пользуется (конкретный сегмент, не «все»)\\n- MARKET_SIZE: конкретная цифра SAM в USD (для tech-фазы — N/A)\\n- CRITICAL_ASSUMPTION: одно ключевое условие, которое должно оказаться правдой для успеха\", \"variable\": \"phase_result\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
