INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (175,23,2,'GTM-стратегия',3,'{\"prompt_user\": \"=== ИДЕЯ ПРОДУКТА ===\\n%project_idea%\\n\\n=== ПРЕДЫДУЩИЙ АНАЛИЗ ===\\n%phases_context%\\n\\n=== ДАННЫЕ ИЗ ИНТЕРНЕТА ===\\n%research_loop_219_result_str%\\n\\nРазработай GTM-стратегию на основе найденных данных о каналах, CAC и активностях конкурентов. Верни JSON с ключом phase_result.\\\\n\\\\nОтвечай на языке: %user_language%.\", \"chunk_variable\": \"research_loop_219_result_str\", \"transitions_after\": [], \"transitions_before\": [], \"llm_to_json_variable\": [{\"text\": \"GTM-стратегия (1000-1500 слов Markdown) с разделами: ## Идеальный клиент ICP (firmographics, психографика, trigger events), ## Позиционирование (positioning statement + value proposition), ## Топ-3 канала привлечения (таблица: Канал | CAC-оценка | Time-to-revenue | Scalability), ## Воронка продаж (этапы с метриками конверсии), ## Sales motion (self-serve/inside-sales/enterprise), ## Retention (онбординг, health score, churn prevention), ## Milestones (первые 10 клиентов → первые 100 → $10K MRR), ## Рекомендации (GTM-приоритеты на первые 90 дней), ## Ключевые выводы (топ-3 GTM-инсайта).\\n\\n---\\n\\n## Phase Summary для следующих фаз (обязательный раздел, добавить в конце)\\n- KEY_INSIGHT: одно предложение — главное открытие этой фазы\\n- MAIN_RISK: один главный риск, который может уничтожить проект\\n- TARGET_CUSTOMER: кто именно платит, кто пользуется (конкретный сегмент, не «все»)\\n- MARKET_SIZE: конкретная цифра SAM в USD (для tech-фазы — N/A)\\n- CRITICAL_ASSUMPTION: одно ключевое условие, которое должно оказаться правдой для успеха\", \"variable\": \"phase_result\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (176,23,3,'Сохранить фазу',4,'{\"tool_invoke\":{\"tool_name\":\"planning_phase_save\",\"inputs_map\":{\"project_id\":\"planning_project_id\",\"phase\":\"planning_phase_name\",\"result\":\"phase_result\"},\"outputs_map\":{\"saved\":\"phase_saved\"}},\"transitions_before\":[],\"transitions_after\":[]}')
