INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (178,24,2,'Финансовая модель',3,'{\"prompt_user\": \"=== ИДЕЯ ПРОДУКТА ===\\n%project_idea%\\n\\n=== ПРЕДЫДУЩИЙ АНАЛИЗ ===\\n%phases_context%\\n\\n=== ДАННЫЕ ИЗ ИНТЕРНЕТА ===\\n%research_loop_221_result_str%\\n\\nСоздай детальную финансовую модель. Верни JSON с ключом phase_result содержащим Markdown.\\n\\nСтруктура документа (строго соблюдать все разделы):\\n## Допущения\\n## Unit-экономика (таблица: ARPU | CAC | LTV | Payback Period | LTV/CAC)\\n## MRR Waterfall (таблица: Месяц 1-12 | New MRR | Churn MRR | Expansion MRR | Total MRR)\\n## Структура затрат (таблица: Категория | $/мес | % от расходов)\\n## P&L прогноз (3 сценария: base/optimistic/pessimistic)\\n## Runway и break-even анализ\\n## Инвестиционные потребности\\n## Таблица работ по ролям (Роль | Задачи | Часов на MVP | Часов/месяц | Ставка $/ч | Стоимость MVP $)\\n## Рекомендации\\n## Ключевые выводы\\n\\n## 🔴 Sanity Check — проверка реализма (ОБЯЗАТЕЛЬНЫЙ раздел)\\n- LTV/CAC: значение из модели — если > 10, добавь ⚠️ WARNING и объясни почему это реалистично\\n- Year 1 Revenue: сравни с реальным конкурентом на аналогичной стадии\\n- Break-even: реальный месяц с учётом рампы привлечения\\n- Главный финансовый риск: конкретный триггер («если X превысит Y — модель ломается»)\\n\\n## Phase Summary (ОБЯЗАТЕЛЬНЫЙ раздел в конце документа)\\n- KEY_INSIGHT: одно предложение — главное открытие этой фазы\\n- MAIN_RISK: один главный риск\\n- TARGET_CUSTOMER: конкретный сегмент\\n- MARKET_SIZE: конкретная цифра SAM в USD\\n- CRITICAL_ASSUMPTION: одно ключевое условие\\n\\nВсе цифры должны быть реалистичными. Зарплаты — рыночные.\\\\n\\\\nОтвечай на языке: %user_language%.\", \"chunk_variable\": \"research_loop_221_result_str\", \"transitions_after\": [], \"transitions_before\": [], \"llm_to_json_variable\": [{\"text\": \"финансовая модель (1200-1800 слов Markdown) с разделами: ## Допущения (ключевые финансовые предположения), ## Unit-экономика (таблица: ARPU | CAC | LTV | Payback Period | LTV/CAC), ## MRR Waterfall (таблица: Месяц 1-12 | New MRR | Churn MRR | Expansion MRR | Total MRR), ## Структура затрат (таблица: Категория | $/мес | % от расходов | Растёт с клиентами?), ## P&L прогноз (3 сценария: base/optimistic/pessimistic), ## Runway и break-even анализ, ## Инвестиционные потребности (сколько нужно и на что), ## ТАБЛИЦА РАБОТ ПО РОЛЯМ: Роль | Задачи | Часов на MVP | Часов/месяц после | Ставка $/ч | Стоимость MVP $, ## Рекомендации (финансовые приоритеты и точки оптимизации), ## Ключевые выводы (топ-3 финансовых инсайта).\\n\\n## 🔴 Sanity Check — проверка реализма модели (обязательный раздел)\\n- LTV/CAC: фактическое значение из модели — если > 10, добавь ⚠️ WARNING и объясни почему\\n- Year 1 Revenue: сравни с реальным конкурентом на аналогичной стадии (найди пример)\\n- Break-even: укажи реальный месяц с учётом рампы привлечения\\n- Главный финансовый риск: конкретный триггер («если CAC превысит $X — модель становится убыточной»)\\n\\n---\\n\\n## Phase Summary для следующих фаз (обязательный раздел, добавить в конце)\\n- KEY_INSIGHT: одно предложение — главное открытие этой фазы\\n- MAIN_RISK: один главный риск, который может уничтожить проект\\n- TARGET_CUSTOMER: кто именно платит, кто пользуется (конкретный сегмент, не «все»)\\n- MARKET_SIZE: конкретная цифра SAM в USD (для tech-фазы — N/A)\\n- CRITICAL_ASSUMPTION: одно ключевое условие, которое должно оказаться правдой для успеха\", \"variable\": \"phase_result\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
