INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (181,25,2,'Compose Blueprint',1,'{\"llm_to_json_variable\": [{\"variable\": \"phase_result\", \"text\": \"главный Blueprint-документ продукта (1000-1500 слов Markdown). НЕ повторяй данные из предыдущих фаз — только синтез, решения и выводы. Структура:\\n# [Название продукта] — Blueprint\\n## Executive Summary (5 предложений: что строим, для кого, почему сработает, главный риск, итоговая рекомендация)\\n## The Bet (3 условия, которые должны оказаться правдой через 12 мес)\\n## Ключевые решения (3 критических решения до запуска — с вариантами и рекомендацией)\\n## Go/No-Go условия (MVP ✓ если..., Beta ✓ если..., Growth ✓ если... — конкретные метрики)\\n## 30-дневный план первых действий (конкретные шаги, не абстракции)\\n## Минимальные ресурсы (бюджет MVP, минимальная команда, время до первой продажи)\\n## Red Flags (3 конкретных признака, что нужно остановить или развернуть проект)\\n## Verdict (go / maybe / no-go + 2-3 предложения обоснования)\"}], \"prompt_user\": \"=== ИДЕЯ ПРОДУКТА ===\\n%project_idea%\\n\\n=== ПОЛНЫЙ АНАЛИЗ ВО ВСЕХ ФАЗАХ ===\\n%phases_context%\\n\\nСоздай компактный Blueprint — документ для принятия решений.\\nНЕ повторяй данные из фаз — синтезируй выводы. Верни JSON с ключом phase_result содержащим Markdown.\\n\\nСтруктура документа (строго соблюдать, 1000-1500 слов):\\n# [Название продукта] — Blueprint\\n\\n## Executive Summary\\n5 предложений: что строим, для кого, почему сработает, главный риск, итоговая рекомендация.\\n\\n## The Bet\\n3 условия, которые должны оказаться правдой через 12 месяцев для успеха.\\n\\n## Ключевые решения\\n3 критических решения до запуска — с вариантами и рекомендацией по каждому.\\n\\n## Go/No-Go условия\\nЧёткие метрики: MVP ✓ если..., Beta ✓ если..., Growth ✓ если...\\n\\n## 30-дневный план первых действий\\nКонкретные шаги, не абстракции.\\n\\n## Минимальные ресурсы\\nБюджет MVP, минимальная команда, время до первой продажи.\\n\\n## Red Flags\\n3 конкретных признака, что нужно остановить или развернуть проект.\\n\\n## Verdict\\ngo / maybe / no-go + 2-3 предложения обоснования.\\n\\nОтвечай на языке: %user_language%.\", \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
