INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (184,26,2,'Compose Supplement',3,'{\"llm_to_json_variable\": [{\"variable\": \"phase_result\", \"text\": \"детализированное дополнение к Blueprint для направления: %planning_supplement_type% (2000-3000 слов Markdown). Раскрой это направление максимально глубоко с конкретными данными, таблицами, примерами и actionable рекомендациями. Начни с # [Название направления] — Детальный анализ\"}], \"prompt_user\": \"=== ИДЕЯ ПРОДУКТА ===\\n%project_idea%\\n\\n=== ПОЛНЫЙ АНАЛИЗ ===\\n%phases_context%\\n\\n=== ДАННЫЕ ИЗ ИНТЕРНЕТА ===\\n%research_loop_228_result_str%\\n\\nНаправление для детализации: %planning_supplement_type%\\n\\nСоздай детализированное дополнение к Blueprint. Используй реальные данные из интернета — конкретные цифры, примеры, источники. Максимальная глубина, таблицы, actionable рекомендации. Верни JSON с ключом phase_result.\\n\\nОтвечай на языке: %user_language%.\", \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
