INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (213,28,2,'Судья: достаточно?',4,'{\"prompt_user\": \"=== Цель исследования ===\\n%research_goal%\\n\\n=== Найденные данные (итерация %search_iteration% из %max_iterations%) ===\\n%accumulated_data%\\n\\nОцени: достаточно ли найденных данных для достижения цели? Если да — is_complete=yes. Если нет — is_complete=no и укажи следующий поисковый запрос.\\n\\nПравила для next_query:\\n1. Заголовки === ... === в accumulated_data — это уже выполненные запросы. Не повторяй и не перефразируй их.\\n2. Выбирай аспект, который ещё НЕ исследован.\\n3. Формулируй конкретно: включай бренды, метрики, год.\\n\\n=== Important information about final response ===\\nPlease return your response in JSON format. The JSON response must contain follow keys: \\n- \\\"is_complete\\\": yes или no\\n- \\\"next_query\\\": следующий поисковый запрос или пустая строка\\n\\nExample of JSON response:\\n{\\n  \\\"is_complete\\\": \\\"no\\\",\\n  \\\"next_query\\\": \\\"Notion competitors traffic SimilarWeb 2024\\\"\\n}\", \"transitions_after\": [{\"value\": \"yes\", \"step_id\": \"215\", \"operator\": \"==\", \"variable\": \"is_complete\"}, {\"value\": \"%max_iterations%\", \"step_id\": \"215\", \"operator\": \">=\", \"variable\": \"search_iteration\"}], \"transitions_before\": [], \"llm_to_json_variable\": [{\"text\": \"yes если данных достаточно для достижения цели, no если нужно искать ещё\", \"variable\": \"is_complete\"}, {\"text\": \"следующий поисковый запрос (если is_complete=no), пустая строка если yes\", \"variable\": \"next_query\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (214,28,5,'Обновить запрос',5,'{\"variable_conversion\":[{\"variable\":\"current_query\",\"text\":\"%next_query%\"}],\"transitions_before\":[],\"transitions_after\":[{\"variable\":\"current_query\",\"operator\":\"exists\",\"value\":\"\",\"step_id\":\"210\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
