  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (216,20,2,'Параметры поиска',1,'{\"llm_to_json_variable\": [{\"variable\": \"initial_query\", \"text\": \"конкретный поисковый запрос на английском (5-10 слов) для исследования: рынок: конкурентов с ценами/трафиком, TAM/SAM/SOM, тренды 2024-2025, незанятые ниши\"}, {\"variable\": \"research_goal\", \"text\": \"чёткая цель исследования — рынок: конкурентов с ценами/трафиком, TAM/SAM/SOM, тренды 2024-2025, незанятые ниши — для данного конкретного продукта\"}], \"prompt_user\": \"=== ИДЕЯ ПРОДУКТА ===\\n%project_idea%\\n\\nСгенерируй параметры для исследования market:\\n\\n1. initial_query — первый поисковый запрос на английском. Используй ключевые слова из домена идеи: тип продукта, аналоги, рынок. Хороший пример: \'project management SaaS competitors Asana Monday pricing 2025\'. НЕ используй общие слова вроде \'SaaS market research competitors\'.\\n2. research_goal — что именно исследовать: рынок: конкурентов с ценами/трафиком, TAM/SAM/SOM, тренды 2024-2025, незанятые ниши — для данного конкретного продукта.\\n\\nВерни JSON с ключами initial_query и research_goal.\", \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (217,20,6,'Интернет-поиск рынка',2,'{\"workflow_invoke\":{\"workflow_id\":28,\"inputs_map\":{\"research_goal\":\"research_goal\",\"initial_query\":\"initial_query\"},\"outputs_map\":{}},\"transitions_before\":[],\"transitions_after\":[]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (218,23,2,'Параметры поиска',1,'{\"llm_to_json_variable\": [{\"variable\": \"initial_query\", \"text\": \"конкретный поисковый запрос на английском (5-10 слов) для исследования: GTM: реальные каналы привлечения, CAC по каналам, ICP конкурентов, онбординг и retention-стратегии\"}, {\"variable\": \"research_goal\", \"text\": \"чёткая цель исследования — GTM: реальные каналы привлечения, CAC по каналам, ICP конкурентов, онбординг и retention-стратегии — для данного конкретного продукта\"}], \"prompt_user\": \"=== ИДЕЯ ПРОДУКТА ===\\n%project_idea%\\n\\nСгенерируй параметры для исследования gtm:\\n\\n1. initial_query — первый поисковый запрос на английском. Используй ключевые слова из домена идеи: тип продукта, аналоги, рынок. Хороший пример: \'CRM startup customer acquisition channels CAC 2025\'. НЕ используй общие слова вроде \'B2B SaaS go-to-market strategy\'.\\n2. research_goal — что именно исследовать: GTM: реальные каналы привлечения, CAC по каналам, ICP конкурентов, онбординг и retention-стратегии — для данного конкретного продукта.\\n\\nВерни JSON с ключами initial_query и research_goal.\", \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (219,23,6,'Интернет-поиск GTM',2,'{\"workflow_invoke\":{\"workflow_id\":28,\"inputs_map\":{\"research_goal\":\"research_goal\",\"initial_query\":\"initial_query\"},\"outputs_map\":{}},\"transitions_before\":[],\"transitions_after\":[]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (220,24,2,'Параметры поиска',1,'{\"llm_to_json_variable\": [{\"variable\": \"initial_query\", \"text\": \"конкретный поисковый запрос на английском (5-10 слов) для исследования: финансы: unit economics конкурентов, зарплаты разработчиков по ролям 2024-2025, runway/burn rate, примеры MRR роста\"}, {\"variable\": \"research_goal\", \"text\": \"чёткая цель исследования — финансы: unit economics конкурентов, зарплаты разработчиков по ролям 2024-2025, runway/burn rate, примеры MRR роста — для данного конкретного продукта\"}], \"prompt_user\": \"=== ИДЕЯ ПРОДУКТА ===\\n%project_idea%\\n\\nСгенерируй параметры для исследования financial:\\n\\n1. initial_query — первый поисковый запрос на английском. Используй ключевые слова из домена идеи: тип продукта, аналоги, рынок. Хороший пример: \'EdTech SaaS ARR funding benchmarks 2025 developer salaries\'. НЕ используй общие слова вроде \'SaaS startup unit economics\'.\\n2. research_goal — что именно исследовать: финансы: unit economics конкурентов, зарплаты разработчиков по ролям 2024-2025, runway/burn rate, примеры MRR роста — для данного конкретного продукта.\\n\\nВерни JSON с ключами initial_query и research_goal.\", \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (221,24,6,'Интернет-поиск финансов',2,'{\"workflow_invoke\":{\"workflow_id\":28,\"inputs_map\":{\"research_goal\":\"research_goal\",\"initial_query\":\"initial_query\"},\"outputs_map\":{}},\"transitions_before\":[],\"transitions_after\":[]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (222,30,3,'Загрузить Blueprint',0,'{\"tool_invoke\":{\"tool_name\":\"planning_phase_blueprint_load\",\"inputs_map\":{\"project_id\":\"planning_project_id\"},\"outputs_map\":{\"blueprint_content\":\"blueprint_content\",\"project_title\":\"project_title\"}},\"transitions_before\":[],\"transitions_after\":[]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (223,30,2,'Оценить Blueprint',1,'{\"llm_to_json_variable\": [{\"variable\": \"score_market\", \"text\": \"оценка рынка от 1 до 10 (размер, конкуренция, тайминг)\"}, {\"variable\": \"score_feasibility\", \"text\": \"оценка реализуемости от 1 до 10 (техническая сложность, необходимые ресурсы)\"}, {\"variable\": \"score_financial\", \"text\": \"оценка финансовой модели от 1 до 10 (unit-экономика, путь к прибыльности)\"}, {\"variable\": \"score_verdict\", \"text\": \"итоговый вердикт: go | maybe | no\"}, {\"variable\": \"score_investment\", \"text\": \"необходимые инвестиции, например: 0K-100K\"}, {\"variable\": \"score_time_to_market\", \"text\": \"время до первых продаж, например: 6-9 месяцев\"}, {\"variable\": \"score_summary\", \"text\": \"2-3 предложения: главные сильные стороны и главные риски\"}], \"prompt_user\": \"=== BLUEPRINT ПРОДУКТА ===\\n%blueprint_content%\\n\\nОцени потенциал этого продукта по трём критериям (1-10) и вынеси вердикт. Оценки должны быть реалистичными: большинство идей 5-7, хорошие 8, выдающиеся 9-10. Вердикт go = реальный шанс при правильном исполнении; maybe = нужны изменения; no = фундаментальные проблемы. Верни JSON с ключами: score_market, score_feasibility, score_financial, score_verdict, score_investment, score_time_to_market, score_summary.\\\\n\\\\nОтвечай на языке: %user_language%.\", \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (224,30,3,'Сохранить оценки',2,'{\"tool_invoke\":{\"tool_name\":\"planning_project_score_save\",\"inputs_map\":{\"project_id\":\"planning_project_id\",\"score_market\":\"score_market\",\"score_feasibility\":\"score_feasibility\",\"score_financial\":\"score_financial\",\"score_verdict\":\"score_verdict\",\"score_investment\":\"score_investment\",\"score_time_to_market\":\"score_time_to_market\",\"score_summary\":\"score_summary\"},\"outputs_map\":{\"saved\":\"score_saved\"}},\"transitions_before\":[],\"transitions_after\":[]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (225,31,2,'Генерировать идеи',0,'{\"llm_to_json_variable\":[{\"variable\":\"ideas_json\",\"text\":\"JSON-массив из 7 идей: [{\\\"title\\\":\\\"...\\\",\\\"idea\\\":\\\"...\\\"}] — title краткое название, idea описание 2-3 предложения\"}],\"prompt_user\":\"Придумай 7 идей продуктов или SaaS-сервисов для ниши/темы:\\n%planning_niche%\\n\\nДля каждой идеи:\\n- title: краткое название (5-8 слов)\\n- idea: описание 2-3 предложения (что за продукт, кто клиент, какую проблему решает)\\n\\nИдеи конкретные и реалистичные.\\n\\nВерни ТОЛЬКО JSON объект (без markdown, без кода) с ключом ideas_json:\\n{\\\"ideas_json\\\": [{\\\"title\\\":\\\"...\\\",\\\"idea\\\":\\\"...\\\"}]}\\\\n\\\\nОтвечай на языке: %user_language%.\",\"transitions_before\":[],\"transitions_after\":[]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (226,31,4,'Вернуть идеи',1,'{\"prompt_user\": \"json:%ideas_json%\", \"continue_workflow\": false, \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (227,26,2,'Параметры поиска',1,'{\"llm_to_json_variable\": [{\"variable\": \"initial_query\", \"text\": \"конкретный поисковый запрос на английском для глубокого исследования данного направления в данном домене\"}, {\"variable\": \"research_goal\", \"text\": \"точная цель: какие данные, метрики, примеры и кейсы нужно найти для детального дополнения\"}], \"prompt_user\": \"=== ИДЕЯ ПРОДУКТА ===\\n%project_idea%\\n\\n=== КОНТЕКСТ АНАЛИЗА ===\\n%phases_context%\\n\\n=== НАПРАВЛЕНИЕ ДЛЯ ДЕТАЛИЗАЦИИ ===\\n%planning_supplement_type%\\n\\nСгенерируй параметры для глубокого интернет-исследования по данному направлению:\\n\\n1. initial_query — первый конкретный поисковый запрос на английском. Учти домен продукта И специфику направления. Примеры: для market-supplement EdTech — \'online learning platform market size competitors Coursera 2025\'; для tech-supplement — \'online learning platform tech stack video streaming WebRTC scalability\'. Запрос должен вести к реальным данным, а не к общим статьям.\\n2. research_goal — что конкретно найти: данные, метрики, кейсы и примеры для детального дополнения по направлению %planning_supplement_type% для данного продукта.\\n\\nВерни JSON с ключами initial_query и research_goal.\", \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (228,26,6,'Интернет-поиск',2,'{\"workflow_invoke\": {\"workflow_id\": 28, \"inputs_map\": {\"research_goal\": \"research_goal\", \"initial_query\": \"initial_query\"}, \"outputs_map\": {}}, \"transitions_before\": [], \"transitions_after\": []}')
