INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (231,22,2,'Параметры поиска',1,'{\"llm_to_json_variable\": [{\"variable\": \"initial_query\", \"text\": \"\\u043a\\u043e\\u043d\\u043a\\u0440\\u0435\\u0442\\u043d\\u044b\\u0439 \\u043f\\u043e\\u0438\\u0441\\u043a\\u043e\\u0432\\u044b\\u0439 \\u0437\\u0430\\u043f\\u0440\\u043e\\u0441 \\u043d\\u0430 \\u0430\\u043d\\u0433\\u043b\\u0438\\u0439\\u0441\\u043a\\u043e\\u043c (5-10 \\u0441\\u043b\\u043e\\u0432) \\u0434\\u043b\\u044f \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u043d\\u0438\\u044f: tech stack \\u0430\\u043d\\u0430\\u043b\\u043e\\u0433\\u0438\\u0447\\u043d\\u044b\\u0445 \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0442\\u043e\\u0432, GitHub \\u0440\\u0435\\u043f\\u043e\\u0437\\u0438\\u0442\\u043e\\u0440\\u0438\\u0438, \\u0430\\u0440\\u0445\\u0438\\u0442\\u0435\\u043a\\u0442\\u0443\\u0440\\u043d\\u044b\\u0435 \\u043f\\u0430\\u0442\\u0442\\u0435\\u0440\\u043d\\u044b, ADR\"}, {\"variable\": \"research_goal\", \"text\": \"\\u0447\\u0451\\u0442\\u043a\\u0430\\u044f \\u0446\\u0435\\u043b\\u044c \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u043d\\u0438\\u044f \\u2014 \\u0442\\u0435\\u0445\\u043d\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u0441\\u0442\\u0435\\u043a \\u043a\\u043e\\u043d\\u043a\\u0443\\u0440\\u0435\\u043d\\u0442\\u043e\\u0432, open-source \\u0430\\u043d\\u0430\\u043b\\u043e\\u0433\\u0438 \\u043d\\u0430 GitHub, \\u0430\\u0440\\u0445\\u0438\\u0442\\u0435\\u043a\\u0442\\u0443\\u0440\\u043d\\u044b\\u0435 \\u0440\\u0435\\u0448\\u0435\\u043d\\u0438\\u044f \\u0438 \\u0438\\u0445 \\u043e\\u0431\\u043e\\u0441\\u043d\\u043e\\u0432\\u0430\\u043d\\u0438\\u044f \\u2014 \\u0434\\u043b\\u044f \\u0434\\u0430\\u043d\\u043d\\u043e\\u0433\\u043e \\u043a\\u043e\\u043d\\u043a\\u0440\\u0435\\u0442\\u043d\\u043e\\u0433\\u043e \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0442\\u0430\"}], \"prompt_user\": \"=== \\u0418\\u0414\\u0415\\u042f \\u041f\\u0420\\u041e\\u0414\\u0423\\u041a\\u0422\\u0410 ===\\n%project_idea%\\n\\n=== \\u041f\\u0420\\u0415\\u0414\\u042b\\u0414\\u0423\\u0429\\u0418\\u0419 \\u0410\\u041d\\u0410\\u041b\\u0418\\u0417 ===\\n%phases_context%\\n\\n\\u0421\\u0433\\u0435\\u043d\\u0435\\u0440\\u0438\\u0440\\u0443\\u0439 \\u043f\\u0430\\u0440\\u0430\\u043c\\u0435\\u0442\\u0440\\u044b \\u0434\\u043b\\u044f \\u0442\\u0435\\u0445\\u043d\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0433\\u043e \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u043d\\u0438\\u044f:\\n\\n1. initial_query \\u2014 \\u043f\\u0435\\u0440\\u0432\\u044b\\u0439 \\u043f\\u043e\\u0438\\u0441\\u043a\\u043e\\u0432\\u044b\\u0439 \\u0437\\u0430\\u043f\\u0440\\u043e\\u0441 \\u043d\\u0430 \\u0430\\u043d\\u0433\\u043b\\u0438\\u0439\\u0441\\u043a\\u043e\\u043c. \\u0418\\u0449\\u0435\\u043c tech stack \\u0438 \\u0430\\u0440\\u0445\\u0438\\u0442\\u0435\\u043a\\u0442\\u0443\\u0440\\u0443 \\u0430\\u043d\\u0430\\u043b\\u043e\\u0433\\u0438\\u0447\\u043d\\u044b\\u0445 \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0442\\u043e\\u0432. \\u0425\\u043e\\u0440\\u043e\\u0448\\u0438\\u0439 \\u043f\\u0440\\u0438\\u043c\\u0435\\u0440: \'CRM SaaS tech stack FastAPI React PostgreSQL GitHub open source 2025\'. \\u041d\\u0415 \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u0443\\u0439 \\u043e\\u0431\\u0449\\u0438\\u0435 \\u0441\\u043b\\u043e\\u0432\\u0430 \\u0432\\u0440\\u043e\\u0434\\u0435 \'SaaS tech architecture\'.\'\\n2. research_goal \\u2014 \\u0447\\u0442\\u043e \\u0438\\u043c\\u0435\\u043d\\u043d\\u043e \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u044c: \\u0442\\u0435\\u0445\\u043d\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u0441\\u0442\\u0435\\u043a, open-source \\u0430\\u043d\\u0430\\u043b\\u043e\\u0433\\u0438, \\u0430\\u0440\\u0445\\u0438\\u0442\\u0435\\u043a\\u0442\\u0443\\u0440\\u043d\\u044b\\u0435 \\u043f\\u0430\\u0442\\u0442\\u0435\\u0440\\u043d\\u044b \\u2014 \\u0434\\u043b\\u044f \\u0434\\u0430\\u043d\\u043d\\u043e\\u0433\\u043e \\u043a\\u043e\\u043d\\u043a\\u0440\\u0435\\u0442\\u043d\\u043e\\u0433\\u043e \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0442\\u0430.\\n\\n\\u0412\\u0435\\u0440\\u043d\\u0438 JSON \\u0441 \\u043a\\u043b\\u044e\\u0447\\u0430\\u043c\\u0438 initial_query \\u0438 research_goal.\", \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
