INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (252,34,2,'Параметры поиска',0,'{\"prompt_user\": \"=== ИДЕЯ ПРОДУКТА ===\\n%project_idea%\\n\\nТы дизайн-исследователь. Сформируй параметры для интернет-поиска визуальных UI/UX референсов.\\n\\nПроанализируй идею и определи:\\n- Тип интерфейса (новостной портал, SaaS дашборд, маркетплейс и т.д.)\\n- Прямые конкуренты или аналоги — конкретные сервисы по имени\\n- Ключевые экраны продукта (главная, карточка контента, подписка и т.д.)\\n\\nСгенерируй:\\n\\n1. **initial_query** — поисковый запрос на английском для поиска ВИЗУАЛЬНЫХ примеров UI:\\n   [тип продукта] + [ниша] + [design system | UI screenshots | color palette | component library]\\n   Примеры:\\n   - \\\"Bloomberg Reuters Axios news website UI design patterns 2024\\\"\\n   - \\\"subscription content platform paywall UX dark light mode\\\"\\n   - \\\"SaaS analytics dashboard UI component library Figma\\\"\\n\\n2. **research_goal** — цель серии поисков. Укажи: конкурентов, цветовые схемы, типографику, паттерны навигации, ключевые экраны.\\n\\nВерни JSON с ключами initial_query и research_goal.\", \"transitions_after\": [], \"transitions_before\": [], \"llm_to_json_variable\": [{\"text\": \"конкретный поисковый запрос на английском для поиска UI/UX референсов, скриншотов конкурентов, цветовых палитр и дизайн-систем\", \"variable\": \"initial_query\"}, {\"text\": \"чёткая цель: какие UI/UX референсы, цветовые схемы конкурентов, паттерны высокой конверсии и дизайн-системы нужно найти\", \"variable\": \"research_goal\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
