INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (258,35,2,'Создать дизайн-систему',3,'{\"prompt_user\": \"=== ПРОДУКТ ===\\n%project_idea%\\n\\n%if design_system_quality_critique%=== ИСПРАВИТЬ ===\\n%design_system_quality_critique%\\n%endif%\\n\\nСоздай дизайн-систему. Верни строго JSON:\\n{\\\"design_system_content\\\": \\\"colors: primary=#HEX primary-dark=#HEX secondary=#HEX success=#HEX warning=#HEX error=#HEX background=#HEX surface=#HEX text-primary=#HEX text-secondary=#HEX border=#HEX | font: NAME | sizes: 12/14/16/20/24/32px | spacing: 4/8/12/16/24/32/48px | Button: v1/v2/v3 | Input: v1/v2/v3 | Card: v1/v2/v3 | Badge: v1/v2/v3\\\"}\\n\\nПример (SaaS для аналитики):\\n{\\\"design_system_content\\\": \\\"colors: primary=#2563EB primary-dark=#1D4ED8 secondary=#7C3AED success=#16A34A warning=#D97706 error=#DC2626 background=#F8FAFC surface=#FFFFFF text-primary=#0F172A text-secondary=#64748B border=#E2E8F0 | font: Inter | sizes: 12/14/16/20/24/32px | spacing: 4/8/12/16/24/32/48px | Button: primary/secondary/outline/ghost | Input: default/focus/error/disabled | Card: flat/elevated/bordered | Badge: success/warning/error/neutral\\\"}\\n\\nЯзык: %user_language%\", \"transitions_after\": [], \"transitions_before\": [], \"llm_to_json_variable\": [{\"variable\": \"design_system_content\", \"text\": \"компактная строка дизайн-системы: colors, font, sizes, spacing, компоненты\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
