INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (261,35,2,'Судья: дизайн-система',6,'{\"prompt_user\": \"=== ДИЗАЙН-СИСТЕМА ===\\n%design_system_content%\\n\\nИтерация %design_system_iteration%.\\n\\nПроверь наличие ВСЕХ обязательных элементов:\\n1. Цветовая палитра: 11 токенов с #hex (primary, primary-dark, secondary, success, warning, error, background, surface, text-primary, text-secondary, border)\\n2. Типографика: font: NAME и sizes: ...\\n3. Spacing: spacing: ...\\n4. Компоненты: Button, Input, Card, Badge с вариантами через /\\n\\nВерни JSON:\\n{\\\"design_system_ok\\\": \\\"yes\\\" или \\\"no\\\", \\\"design_system_score\\\": <0-10>, \\\"design_system_quality_critique\\\": \\\"краткий список замечаний или пусто если всё ок\\\"}\", \"transitions_after\": [{\"value\": \"yes\", \"step_id\": \"317\", \"operator\": \"==\", \"variable\": \"design_system_ok\"}, {\"value\": \"3\", \"step_id\": \"317\", \"operator\": \">=\", \"variable\": \"design_system_iteration\"}], \"transitions_before\": [], \"llm_to_json_variable\": [{\"text\": \"yes если дизайн-система полная (цвета, типографика, spacing, компоненты, токены), иначе no\", \"variable\": \"design_system_ok\"}, {\"text\": \"оценка 1-10\", \"variable\": \"design_system_score\"}, {\"text\": \"конкретный список дефектов (пустая строка если yes)\", \"variable\": \"design_system_quality_critique\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
