INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (265,36,2,'Выбрать ключевые страницы',3,'{\"llm_to_json_variable\": [{\"variable\": \"selected_pages_json\", \"text\": \"JSON-массив [{name, filename, roles, description}] — 5-7 ключевых страниц\"}], \"prompt_user\": \"=== ПРОДУКТ ===\\n%project_idea%\\n\\n=== СПИСОК СТРАНИЦ (дерево) ===\\n%pages_tree_json%\\n\\n%if ux_spec_quality_critique%=== ЗАМЕЧАНИЯ СУДЬИ ===\\n%ux_spec_quality_critique%\\n\\n%endif%Выбери 5-7 ключевых страниц для UX-спецификации. Отвечай на языке: %user_language%.\\n\\nВерни JSON:\\n{\\\"selected_pages_json\\\": [{\\\"name\\\": \\\"Главная\\\", \\\"filename\\\": \\\"index.html\\\", \\\"roles\\\": [\\\"гость\\\", \\\"пользователь\\\"], \\\"description\\\": \\\"Главный лендинг с ключевыми блоками\\\"}]}\", \"transitions_before\": [], \"transitions_after\": []}')
