INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (268,36,2,'Судья: UX-спецификации',10,'{\"llm_to_json_variable\": [{\"variable\": \"ux_spec_ok\", \"text\": \"yes если UX-спецификации содержат все 4 обязательных раздела (дизайн-токены, UI-компоненты, карта страниц, вайрфреймы) и score >= 8, иначе no\"}, {\"variable\": \"ux_spec_score\", \"text\": \"оценка 1-10\"}, {\"variable\": \"ux_spec_quality_critique\", \"text\": \"конкретный список дефектов (пустая строка если yes)\"}], \"prompt_user\": \"=== UX-СПЕЦИФИКАЦИИ (JSON) ===\\n%ux_spec_pages%\\n\\nИтерация %ux_spec_iteration%.\\n\\nПроверь наличие ВСЕ обязательных элементов в каждой странице:\\n1. Минимум 3 страницы\\n2. У каждой страницы есть: roles, components (минимум 3), wireframe (хотя бы 5 строк в ASCII), states\\n3. Упомянуты состояния: loading, empty или error\\n\\nВерни JSON:\\n{\\\"ux_spec_ok\\\": \\\"yes\\\" или \\\"no\\\", \\\"ux_spec_score\\\": <0-10>, \\\"ux_spec_quality_critique\\\": \\\"краткий список замечаний или пусто если всё ок\\\"}\", \"transitions_before\": [], \"transitions_after\": [{\"variable\": \"ux_spec_ok\", \"operator\": \"==\", \"value\": \"yes\", \"step_id\": \"286\"}, {\"variable\": \"ux_spec_iteration\", \"operator\": \">=\", \"value\": \"%max_ux_iterations%\", \"step_id\": \"286\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
