INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (280,37,1,'Доработать HTML',4,'{\"prompt_user\": \"Страница: %page_name%\\n\\nТекущий HTML:\\n%prototype_html%\\n\\nЗапрос: %refinement_request%\\n\\n%if reference_html%=== Выделенный блок с референс-сайта ===\\nИспользуй этот HTML и CSS как точный источник — интегрируй структуру и стили в прототип:\\n\\nHTML:\\n%reference_html%\\n\\n%if reference_css%CSS:\\n%reference_css%\\n\\n%endif%%endif%%if target_url%=== Сайт-референс ===\\nURL: %target_url%\\n\\nСодержимое страницы:\\n%web_read_page_283_result_str%\\n\\nИспользуй структуру и стиль этого сайта как вдохновение.\\n%endif%Верни ТОЛЬКО полный HTML-документ без пояснений, без markdown-блоков, без кавычек.\", \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
