INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (282,37,2,'Извлечь URL сайта',2,'{\"llm_to_json_variable\": [{\"variable\": \"target_url\", \"text\": \"полный URL (https://...) главной страницы найденного сайта — пустая строка если сайт не найден\"}], \"prompt_user\": \"Запрос пользователя: %refinement_request%\\n\\nРезультаты поиска:\\n%web_search_281_result_results%\\n\\nНайди URL главной страницы сайта, который пользователь хочет использовать как референс.\\n\\nВерни ТОЛЬКО JSON-объект:\\n{\\\"target_url\\\": \\\"https://ukr.net\\\"}\\nили если не найден:\\n{\\\"target_url\\\": \\\"\\\"}\", \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
