INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (285,37,2,'Анализ запроса',0,'{\"llm_to_json_variable\":[{\"variable\":\"search_query\",\"text\":\"поисковый запрос на английском для нахождения сайта (например: Stripe payments homepage) — пустая строка если пользователь не упоминает конкретный сайт\"},{\"variable\":\"target_url\",\"text\":\"полный URL (https://...) если пользователь явно написал его в запросе — пустая строка в остальных случаях\"}],\"prompt_user\":\"Страница: %page_name%\\nЗапрос пользователя: %refinement_request%\\n\\nОпредели, хочет ли пользователь использовать конкретный сайт как визуальный референс для дизайна.\\n\\nВерни ТОЛЬКО JSON с двумя ключами:\\n- search_query: поисковый запрос если пользователь назвал сайт без URL, иначе пустая строка\\n- target_url: URL если пользователь написал его явно, иначе пустая строка\\n\\nПримеры:\\n{\\\"search_query\\\": \\\"\\\", \\\"target_url\\\": \\\"\\\"}\\n{\\\"search_query\\\": \\\"Stripe payments homepage\\\", \\\"target_url\\\": \\\"\\\"}\\n{\\\"search_query\\\": \\\"\\\", \\\"target_url\\\": \\\"https://stripe.com\\\"}\",\"transitions_before\":[],\"transitions_after\":[]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (286,36,2,'Извлечь карту страниц',12,'{\"llm_to_json_variable\": [{\"variable\": \"sitemap_pages_json\", \"text\": \"JSON-строка — массив объектов [{\\\"filename\\\": \\\"index.html\\\", \\\"title\\\": \\\"Landing Page\\\"}, ...] со всеми страницами из раздела Карта страниц. Только страницы с .html именами.\"}], \"prompt_user\": \"=== UX-СПЕЦИФИКАЦИИ ===\\n%ux_spec_content%\\n\\nИзвлеки все страницы из раздела \\\"## Карта страниц\\\".\\n\\nВерни JSON:\\n{\\\"sitemap_pages_json\\\": [{\\\"filename\\\": \\\"FILENAME.html\\\", \\\"title\\\": \\\"TITLE\\\"}, ...]}\\n\\nПравила:\\n- Только страницы с реальными .html именами из текста\\n- Не добавляй страницы которых нет\", \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
