INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (303,40,2,'Рендеринг компонента (LLM)',2,'{\"llm_to_json_variable\": [{\"variable\": \"component_html\", \"text\": \"HTML-код компонента (без html/head/body)\"}], \"prompt_user\": \"=== ДИЗАЙН-ТОКЕНЫ ===\\n%design_tokens%\\n\\n=== СПЕЦИФИКАЦИЯ КОМПОНЕНТА ===\\n%current_ui_component_spec%\\n\\n%if design_sitemap%=== КАРТА СТРАНИЦ ===\\n%design_sitemap%\\n%endif%%if hero_image_url%=== HERO IMAGE ===\\n%hero_image_url%\\n%endif%=== КОМПОНЕНТ ДЛЯ РЕНДЕРИНГА ===\\nID: %current_component_id%\\nТип: %current_component_name%\\nОписание: %current_component_description%\\n\\nЗадача: сгенерируй ТОЛЬКО HTML-код компонента \\\"%current_component_id%\\\".\\n\\nТРЕБОВАНИЯ:\\n1. Только внутренний HTML — БЕЗ <!DOCTYPE>, <html>, <head>, <body>, <script>\\n2. HTML вставляется внутрь: <div id=\\\"%current_component_id%\\\">ТВОЙ HTML</div>\\n3. Tailwind CSS классы (CDN уже подключён в каркасе страницы)\\n4. Цвета/шрифты строго из design_tokens\\n5. Реалистичный контент на русском языке\\n%if current_component_tag_navigation%6. Рабочие <a href=\\\"...\\\"> ссылки на ВСЕ страницы из карты страниц (точные .html имена)\\n%endif%7. Адаптивный дизайн с Tailwind-брейкпоинтами\\n%if hero_image_url%8. Для \\\"hero\\\": использовать <img src=\\\"%hero_image_url%\\\" alt=\\\"Hero\\\">\\n%endif%9. КОМПАКТНОСТЬ: рендерить строго то, что описано в \\\"Описании\\\". Не добавлять лишних секций, не дублировать элементы. SVG-иконки — простые (viewBox, 1-2 path). Максимум 80 строк HTML.\\n%if current_component_tag_auth%10. ФОРМА АВТОРИЗАЦИИ — обязательные ссылки (используй точные .html имена из карты страниц):\\n    - Форма ВХОДА: ссылка \\\"Забыли пароль?\\\" на страницу восстановления пароля + ссылка \\\"Зарегистрироваться\\\" на страницу регистрации\\n    - Форма РЕГИСТРАЦИИ: ссылка \\\"Уже есть аккаунт? Войти\\\" на страницу входа\\n    - Форма ВОССТАНОВЛЕНИЯ ПАРОЛЯ: ссылка \\\"Вернуться к входу\\\" на страницу входа\\n%endif%\\n=== Important information about final response ===\\nReturn your response in JSON format with key:\\n- \\\"component_html\\\": inner HTML of the component (no html/head/body tags)\\n\\nExample: {\\\"component_html\\\": \\\"<div class=\\\\\\\"p-4\\\\\\\">...</div>\\\"}\", \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
