INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (317,35,2,'Токены дизайн-системы',8,'{\"llm_to_json_variable\":[{\"variable\":\"design_tokens_json\",\"text\":\"JSON-объект с 11 токенами: primary, primary-dark, secondary, success, warning, error, background, surface, text-primary, text-secondary, border — только hex-значения\"}],\"prompt_user\":\"Из дизайн-системы ниже извлеки цветовую палитру и верни JSON с ровно 11 токенами.\\n\\n=== ДИЗАЙН-СИСТЕМА ===\\n%design_system_content%\\n\\nОтвет строго в формате:\\n{\\n  \\\"design_tokens_json\\\": {\\\"primary\\\":\\\"#hex\\\",\\\"primary-dark\\\":\\\"#hex\\\",\\\"secondary\\\":\\\"#hex\\\",\\\"success\\\":\\\"#hex\\\",\\\"warning\\\":\\\"#hex\\\",\\\"error\\\":\\\"#hex\\\",\\\"background\\\":\\\"#hex\\\",\\\"surface\\\":\\\"#hex\\\",\\\"text-primary\\\":\\\"#hex\\\",\\\"text-secondary\\\":\\\"#hex\\\",\\\"border\\\":\\\"#hex\\\"}\\n}\",\"transitions_before\":[],\"transitions_after\":[]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
