INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (319,42,2,'Теги, сущности и роли',1,'{\"prompt_user\": \"=== ИДЕЯ ПРОДУКТА ===\\n%project_idea%\\n\\nПроанализируй идею. \\n\\nВерни JSON:\\n{\\n  \\\"cloud_tags_json\\\": [\\\"тег1\\\", \\\"тег2\\\", ...],\\n  \\\"project_entities_json\\\": [\\\"Пользователь\\\", \\\"Статья\\\", ...],\\n  \\\"project_roles_json\\\": [\\\"guest\\\", \\\"admin\\\", ...]\\n}\\n\\ncloud_tags_json — 30-60 ключевых тегов (функции, домен, ЦА, UX-паттерны).\\nproject_entities_json — 8-20 основных бизнес-сущностей продукта.\\nproject_roles_json — роли пользователей (всегда включая \\\"guest\\\" и \\\"admin\\\", плюс специфичные).\", \"llm_to_json_variable\": [{\"variable\": \"cloud_tags_json\", \"text\": \"JSON-массив строк: облако тегов (30-60 элементов)\"}, {\"variable\": \"project_entities_json\", \"text\": \"JSON-массив строк: бизнес-сущности системы\"}, {\"variable\": \"project_roles_json\", \"text\": \"JSON-массив строк: роли пользователей (включая guest, admin)\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (320,42,3,'Сохранить метаданные',2,'{\"tool_invoke\": {\"tool_name\": \"planning_project_meta_save\", \"inputs_map\": {\"project_id\": \"planning_project_id\", \"cloud_tags\": \"cloud_tags_json\", \"entities\": \"project_entities_json\", \"roles\": \"project_roles_json\"}, \"outputs_map\": {}}, \"transitions_before\": [], \"transitions_after\": []}')
