INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (321,42,2,'Сценарии поведения',3,'{\"prompt_user\": \"=== ИДЕЯ ПРОДУКТА ===\\n%project_idea%\\n\\n=== РОЛИ ===\\n%project_roles_json%\\n\\n=== СУЩНОСТИ ===\\n%project_entities_json%\\n\\nДля каждой роли составь 3-5 ключевых сценариев (user stories). \\n\\nВерни JSON:\\n{\\\"user_scenarios_json\\\": {\\\"роль1\\\": [\\\"сценарий 1\\\", \\\"сценарий 2\\\"], \\\"роль2\\\": [...]}}\", \"llm_to_json_variable\": [{\"variable\": \"user_scenarios_json\", \"text\": \"JSON-объект: роль → массив сценариев поведения\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (322,42,2,'Дерево страниц',4,'{\"prompt_user\": \"=== ИДЕЯ ПРОДУКТА ===\\n%project_idea%\\n\\n=== РОЛИ ===\\n%project_roles_json%\\n\\n=== СУЩНОСТИ ===\\n%project_entities_json%\\n\\n=== СЦЕНАРИИ ===\\n%user_scenarios_json%\\n\\nСоставь ПОЛНЫЙ список страниц продукта с древовидной структурой.\\n\\nВключи ВСЕ типы страниц:\\n- feature: функциональные (главная, дашборд, профиль, списки, детали, настройки)\\n- auth: авторизация, регистрация, восстановление пароля\\n- technical: 404, 500, обслуживание, политика, контакты\\n\\nТЕГИ (поле tags — список строк):\\n- \'direct\' — страница проверяется напрямую (не требует навигации): все technical-страницы, страницы политики/контактов\\n- \'index\' — точка входа в раздел для авторизованных пользователей: главный дашборд, кабинет автора, панель администратора, любая \'home\'-страница роли\\n- [] — обычная страница, достижима через навигацию\\n\\nПРАВИЛА:\\n- Все технические страницы (page_type=technical) ДОЛЖНЫ иметь tag \'direct\'\\n- Главная страница каждой роли (первая точка входа после логина) ДОЛЖНА иметь tag \'index\'\\n- auth-страницы: обычно [] (достижимы через кнопку Войти), но страница восстановления пароля может иметь \'direct\'\\n\\nВерни JSON:\\n{\\\"pages_tree_json\\\": [\\n  {\\\"name\\\": \\\"Название\\\", \\\"description\\\": \\\"1-2 предложения\\\", \\\"page_type\\\": \\\"feature\\\", \\\"tags\\\": [], \\\"roles\\\": [\\\"guest\\\"], \\\"children\\\": [\\n    {\\\"name\\\": \\\"Подстраница\\\", \\\"description\\\": \\\"...\\\", \\\"page_type\\\": \\\"feature\\\", \\\"tags\\\": [], \\\"roles\\\": [\\\"user\\\"], \\\"children\\\": []}\\n  ]}\\n]}\", \"llm_to_json_variable\": [{\"variable\": \"pages_tree_json\", \"text\": \"JSON-массив страниц с полем children — полное дерево навигации\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (323,42,3,'Сохранить страницы в БД',8,'{\"tool_invoke\": {\"tool_name\": \"design_page_save\", \"inputs_map\": {\"project_id\": \"planning_project_id\", \"pages_json\": \"pages_tree_json\"}, \"outputs_map\": {\"pages_count\": \"pages_count\"}}, \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (324,42,4,'Вернуть список страниц',10,'{\"prompt_user\": \"%pages_tree_json%\", \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (325,36,6,'Генерация дерева страниц (WF42)',1,'{\"workflow_invoke\": {\"workflow_id\": 42, \"inputs_map\": {\"planning_project_id\": \"planning_project_id\", \"project_idea\": \"project_idea\"}, \"outputs_map\": {\"pages_tree_json\": \"pages_tree_json\"}}, \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (326,42,2,'Блоки UI',5,'{\"prompt_user\": \"=== ИДЕЯ ПРОДУКТА ===\\n%project_idea%\\n\\n=== РОЛИ ===\\n%project_roles_json%\\n\\n=== СУЩНОСТИ ===\\n%project_entities_json%\\n\\n=== ДЕРЕВО СТРАНИЦ ===\\n%pages_tree_json%\\n\\nСтраницы имеют два состояния: anon (гость) и auth (авторизованный пользователь).\\n\\nПроанализируй страницы и выдели повторяющиеся UI-блоки — переиспользуемые составные элементы интерфейса.\\n\\nБлок — это семантическая группа компонентов с единой функцией (напр. \\\"ArticleCard\\\", \\\"NavBar\\\", \\\"SearchBar\\\", \\\"Footer\\\").\\n\\nДля каждого блока укажи:\\n- name: уникальное название (CamelCase)\\n- description: что делает этот блок (1-2 предложения)\\n- content: JSON-объект с дефолтными значениями UI-компонентов (реальные тексты, лейблы)\\n- components: какие UI-компоненты входят (Image, Title, Button, Avatar и т.д.)\\n- stateless: true если блок выглядит одинаково для любого состояния (например Footer, HeroSection), false если блок имеет разные версии для anon и auth (например NavBar с кнопкой Войти vs аватаром, UserMenu)\\n\\nВерни JSON:\\n{\\\"blocks_json\\\": [\\n  {\\\"name\\\": \\\"NavBar\\\", \\\"description\\\": \\\"Навигационная панель...\\\", \\\"content\\\": {\\\"brand\\\": \\\"AppName\\\", \\\"nav_links\\\": [\\\"Главная\\\", \\\"Цены\\\"], \\\"cta\\\": \\\"Попробовать\\\"}, \\\"components\\\": [\\\"Logo\\\",\\\"NavLinks\\\",\\\"Button\\\"], \\\"stateless\\\": false},\\n  {\\\"name\\\": \\\"Footer\\\", \\\"description\\\": \\\"Подвал сайта...\\\", \\\"content\\\": {\\\"links\\\": [\\\"О нас\\\", \\\"Контакты\\\"], \\\"copyright\\\": \\\"© 2025\\\"}, \\\"components\\\": [\\\"NavLinks\\\",\\\"Text\\\"], \\\"stateless\\\": true}\\n]}\\n\\nImportant: return ONLY valid JSON.\", \"transitions_after\": [], \"transitions_before\": [], \"llm_to_json_variable\": [{\"text\": \"список блоков UI: [{name, description, content:{}, components:[], stateless:bool}]\", \"variable\": \"blocks_json\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (327,42,3,'Сохранить блоки',6,'{\"tool_invoke\": {\"tool_name\": \"design_block_save\", \"inputs_map\": {\"project_id\": \"planning_project_id\", \"blocks_json\": \"blocks_json\"}, \"outputs_map\": {\"blocks_count\": \"blocks_count\"}}, \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (328,47,3,'Загрузить данные sitemap',0,'{\"tool_invoke\":{\"tool_name\":\"planning_sitemap_check\",\"inputs_map\":{\"project_id\":\"planning_project_id\"},\"outputs_map\":{\"sitemap_data\":\"sitemap_data\",\"total_pages\":\"total_pages\",\"total_blocks\":\"total_blocks\"}},\"transitions_before\":[],\"transitions_after\":[]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (330,47,2,'Анализ sitemap',1,'{\"prompt_user\": \"=== ДАННЫЕ SITEMAP ===\\n%sitemap_data%\\n\\nТы — sitemap-аналитик. Проверь полноту карты страниц.\\n\\nНайди:\\n1. Дыры по ролям — роли без ключевых страниц\\n2. Пропущенные технические страницы — 404, 500, политика конфиденциальности\\n3. Auth-coverage — у авторизованных страниц есть anonymous-альтернатива?\\n4. Блоки без state\\n5. Что добавить?\\n\\nВерни JSON: {\\\"sitemap_report\\\": \\\"...краткий текстовый отчёт...\\\", \\\"missing_pages\\\": [\\\"страница1\\\"], \\\"warnings\\\": [\\\"предупреждение1\\\"]}\", \"llm_to_json_variable\": [{\"variable\": \"sitemap_report\", \"text\": \"текстовый отчёт об анализе sitemap\"}, {\"variable\": \"missing_pages\", \"text\": \"список названий недостающих страниц\", \"optional\": true, \"default\": \"[]\"}, {\"variable\": \"warnings\", \"text\": \"список предупреждений\", \"optional\": true, \"default\": \"[]\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (331,47,4,'Вернуть отчёт',2,'{\"prompt_user\": \"%sitemap_report%\", \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (332,42,6,'Проверить Sitemap',9,'{\"workflow_invoke\": {\"workflow_id\": 47, \"inputs_map\": {\"planning_project_id\": \"planning_project_id\"}, \"outputs_map\": {\"sitemap_report\": \"sitemap_report\"}}, \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (333,49,3,'Вызов инструмента',0,'{\"prompt_user\": \"\", \"tool_invoke\": {\"tool_name\": \"design_wireframe_context_load\", \"inputs_map\": {\"page_id\": \"planning_page_id\", \"project_id\": \"planning_project_id\"}, \"outputs_map\": {\"pages_json\": \"pages_json\", \"blocks_json\": \"blocks_json\", \"ui_blocks_json\": \"ui_blocks_json\"}}, \"transitions_after\": [], \"transitions_before\": []}')
