INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (334,49,2,'LLM → вайрфреймы с секциями',2,'{\"prompt_user\": \"=== СТРАНИЦЫ ПРОЕКТА ===\\n%pages_json%\\n\\n=== БЛОКИ ПРОЕКТА ===\\n%blocks_json%\\n\\n=== UI БЛОКИ (библиотека) ===\\n%ui_blocks_json%\\n\\n=== ПАМЯТЬ БЛОК->СЕКЦИЯ ===\\n%block_section_memory%\\n\\nДля каждой страницы составь вайрфрейм.\\n\\nФОРМАТ: [Уровень.Колонка. Блок:Вариант, Блок:Вариант], [Уровень.Колонка. Блок:Вариант]\\n\\nКРИТИЧЕСКИ ВАЖНО:\\n- \\\"Блок\\\" — это ТОЧНОЕ значение поля \\\"name\\\" из списка БЛОКИ ПРОЕКТА или UI БЛОКИ\\n- НЕ придумывай новые имена блоков\\n- Используй только имена блоков из двух списков выше\\n- \\\"Вариант\\\" — произвольный вариант/состояние блока на этой странице\\n\\nПРАВИЛА РАСПОЛОЖЕНИЯ:\\n1. Уровень 1 = шапка (навигационный блок)\\n2. Уровень 2 = основной контент\\n3. Уровень 3 = подвал (навигационный блок повторно, вариант Footer)\\n4. Страницы с сайдбаром: .1 = навигация/сайдбар, .2 = контент\\n5. Если блок в ПАМЯТИ БЛОК->СЕКЦИЯ — используй ту же секцию\\n\\nПРИМЕР (проект с блоками GlobalNavBar, ArticleCard, UserAuthForm, DashboardOverview):\\n{\\\"wireframes\\\": [\\n  {\\\"page_name\\\": \\\"Главная страница\\\", \\\"wireframe\\\": \\\"[1.1. GlobalNavBar:Header], [2.1. ArticleCard:NewsFeed], [3.1. GlobalNavBar:Footer]\\\"},\\n  {\\\"page_name\\\": \\\"Личный кабинет\\\", \\\"wireframe\\\": \\\"[1.1. GlobalNavBar:Header], [2.1. GlobalNavBar:Sidebar], [2.2. DashboardOverview:Main], [3.1. GlobalNavBar:Footer]\\\"},\\n  {\\\"page_name\\\": \\\"Вход в систему\\\", \\\"wireframe\\\": \\\"[1.1. GlobalNavBar:Header], [2.1. UserAuthForm:Login], [3.1. GlobalNavBar:Footer]\\\"}\\n]}\\n\\nВерни JSON со вайрфреймами для КАЖДОЙ страницы из списка СТРАНИЦЫ ПРОЕКТА:\\n{\\\"wireframes\\\": [{\\\"page_name\\\": \\\"ТОЧНОЕ ИМЯ СТРАНИЦЫ\\\", \\\"wireframe\\\": \\\"...\\\"}, ...]}\", \"transitions_after\": [], \"transitions_before\": [], \"llm_to_json_variable\": [{\"text\": \"массив вайрфреймов страниц\", \"variable\": \"wireframes\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (335,49,3,'Вызов инструмента',3,'{\"prompt_user\": \"\", \"tool_invoke\": {\"tool_name\": \"design_wireframe_page_save\", \"inputs_map\": {\"project_id\": \"planning_project_id\", \"filter_page_id\": \"planning_page_id\", \"wireframes_json\": \"wireframes\"}, \"outputs_map\": {\"saved\": \"wireframes_saved\"}}, \"transitions_after\": []}')
