INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (336,49,3,'Вызов инструмента',4,'{\"tool_invoke\":{\"tool_name\":\"planning_phase_save\",\"inputs_map\":{\"project_id\":\"planning_project_id\",\"phase\":\"design_wireframe\",\"result\":\"wireframes_saved\"},\"outputs_map\":{}},\"prompt_user\":\"\",\"transitions_after\":[]}')
