INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (337,50,3,'Вызов инструмента',0,'{\"prompt_user\":\"\",\"tool_invoke\":{\"tool_name\":\"planning_block_regenerate_context_load\",\"inputs_map\":{\"block_id\":\"block_id\",\"project_id\":\"planning_project_id\"},\"outputs_map\":{\"block_json\":\"block_json\",\"pages_json\":\"pages_json\",\"project_idea\":\"project_idea\",\"blocks_context\":\"blocks_context\",\"page_states_json\":\"page_states_json\"}},\"transitions_after\":[],\"transitions_before\":[]}')
