INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (338,50,2,'LLM -> JSON',1,'{\"prompt_user\": \"=== ПРОЕКТ ===\\nИдея: %project_idea%\\n\\n=== БЛОК ДЛЯ ПЕРЕГЕНЕРАЦИИ ===\\n%block_json%\\n\\n(block_json содержит поле stateless: true/false)\\n\\n=== ИСПОЛЬЗУЕТСЯ НА СТРАНИЦАХ ===\\n%pages_json%\\n\\n=== СОСТОЯНИЯ СТРАНИЦ ===\\n%page_states_json%\\n\\n=== ВСЕ БЛОКИ ПРОЕКТА (для согласованности стиля) ===\\n%blocks_context%\\n\\nЗадача:\\n1. Улучши описание блока (description) — что он делает, зачем нужен, ключевые элементы\\n2. Создай content — JSON-объект с дефолтными значениями UI-компонентов этого блока (тексты, лейблы, ссылки). Используй реальные тексты, подходящие для продукта.\\n3. Создай виджеты по правилу:\\n   - Если stateless = true: создай ОДИН виджет с именем = название блока (например \\\"Footer\\\")\\n   - Если stateless = false: создай по ОДНОМУ виджету для каждого состояния из page_states_json. Имя = BlockName_state (например \\\"NavBar_anon\\\", \\\"NavBar_auth\\\")\\n   - html: HTML-разметка ТОЛЬКО этого компонента (без html/head/body тегов). CSS-классы с уникальным префиксом bw-{blockname_lower}-{state}-\\n   - css: plain CSS, не Tailwind.\\n\\nВерни JSON:\\n{\\n  \\\"description\\\": \\\"Улучшенное описание блока\\\",\\n  \\\"content\\\": {\\\"brand\\\": \\\"AppName\\\", \\\"headline\\\": \\\"Заголовок\\\", \\\"cta\\\": \\\"Действие\\\"},\\n  \\\"widgets\\\": [\\n    {\\\"name\\\": \\\"NavBar_anon\\\", \\\"description\\\": \\\"Версия для гостя\\\", \\\"html\\\": \\\"...\\\", \\\"css\\\": \\\"...\\\"}\\n  ]\\n}\\n\\nImportant: return ONLY valid JSON, no additional text.\", \"transitions_after\": [], \"llm_to_json_variable\": [{\"text\": \"новое описание блока\", \"variable\": \"description\"}, {\"text\": \"JSON-объект с дефолтными значениями UI-компонентов\", \"variable\": \"content\"}, {\"text\": \"массив виджетов с HTML и CSS\", \"variable\": \"widgets\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (339,50,3,'Вызов инструмента',2,'{\"tool_invoke\": {\"tool_name\": \"planning_block_ai_update\", \"inputs_map\": {\"block_id\": \"block_id\", \"description\": \"description\", \"content\": \"content\", \"widgets_json\": \"widgets\"}, \"outputs_map\": {\"widgets_count\": \"widgets_saved\"}}, \"prompt_user\": \"\", \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (340,39,3,'Построить CSS Grid scaffold',2,'{\"tool_invoke\": {\"tool_name\": \"planning_prototype_scaffold_build\", \"inputs_map\": {\"grid_layout_json\": \"grid_layout_json\", \"blocks_sections_json\": \"blocks_sections_json\"}, \"outputs_map\": {\"scaffold_html\": \"scaffold_html\", \"blocks_json\": \"page_blocks_raw_json\"}}, \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (341,49,3,'Загрузить память блок→секция',1,'{\"tool_invoke\": {\"tool_name\": \"planning_block_section_memory_load\", \"inputs_map\": {\"project_id\": \"planning_project_id\"}, \"outputs_map\": {\"block_section_memory\": \"block_section_memory\", \"block_section_json\": \"block_section_json\"}}, \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (342,36,2,'Компоненты и состояния',4,'{\"llm_to_json_variable\": [{\"variable\": \"page_components_json\", \"text\": \"JSON-массив [{filename, components: [...], states: [...]}] — UI-компоненты и состояния для каждой страницы\"}], \"prompt_user\": \"=== СТРАНИЦЫ ===\\n%selected_pages_json%\\n\\n=== ДИЗАЙН-СИСТЕМА (доступные компоненты) ===\\n%design_system_content%\\n\\nДля каждой страницы определи UI-компоненты из дизайн-системы и состояния. Отвечай на языке: %user_language%.\\n\\nВерни JSON:\\n{\\\"page_components_json\\\": [{\\\"filename\\\": \\\"index.html\\\", \\\"components\\\": [\\\"Header\\\", \\\"HeroBlock\\\", \\\"Card\\\", \\\"Footer\\\"], \\\"states\\\": [\\\"loading\\\", \\\"empty\\\", \\\"error\\\"]}]}\", \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (343,36,2,'Вайрфреймы страниц',5,'{\"llm_to_json_variable\": [{\"variable\": \"page_wireframes_json\", \"text\": \"JSON-массив [{filename, wireframe}] — ASCII-вайрфреймы страниц\"}], \"prompt_user\": \"=== СТРАНИЦЫ ===\\n%selected_pages_json%\\n\\n=== КОМПОНЕНТЫ ===\\n%page_components_json%\\n\\nНарисуй ASCII-вайрфрейм для каждой страницы, используй символы +, -, |. Отвечай на языке: %user_language%.\\n\\nВерни JSON:\\n{\\\"page_wireframes_json\\\": [{\\\"filename\\\": \\\"index.html\\\", \\\"wireframe\\\": \\\"+--------------------+\\\\n| Logo   Search  Nav |\\\\n+--------------------+\\\\n| [HeroBlock]        |\\\\n+----------+---------+\\\\n| Card     | Sidebar |\\\\n+----------+---------+\\\\n| Footer             |\\\\n+--------------------+\\\"}]}\", \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (344,36,2,'Собрать JSON страниц',6,'{\"llm_to_json_variable\": [{\"variable\": \"ux_spec_pages\", \"text\": \"JSON-массив [{name, filename, roles, components, wireframe, states}] — полные спецификации\"}, {\"variable\": \"sitemap_pages_json\", \"text\": \"Массив [{filename, title}] — карта сайта\"}], \"prompt_user\": \"Объедини данные в итоговый JSON. Отвечай на языке: %user_language%.\\n\\nСТРАНИЦЫ:\\n%selected_pages_json%\\n\\nКОМПОНЕНТЫ:\\n%page_components_json%\\n\\nВАЙРФРЕЙМЫ:\\n%page_wireframes_json%\\n\\nВерни JSON строго:\\n{\\\"ux_spec_pages\\\": [{\\\"name\\\": \\\"Главная\\\", \\\"filename\\\": \\\"index.html\\\", \\\"roles\\\": [\\\"гость\\\"], \\\"components\\\": [\\\"Header\\\", \\\"Card\\\"], \\\"wireframe\\\": \\\"+----+\\\\n| H  |\\\\n+----+\\\", \\\"states\\\": [\\\"loading\\\", \\\"empty\\\"]}], \\\"sitemap_pages_json\\\": [{\\\"filename\\\": \\\"index.html\\\", \\\"title\\\": \\\"Главная\\\"}]}\", \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (345,36,2,'Сформировать документ UX',7,'{\"llm_to_json_variable\": [{\"variable\": \"ux_spec_content\", \"text\": \"Текст с разделами ## Карта страниц, ## Спецификации страниц, ## UI-компоненты, ## Вайрфреймы страниц\"}], \"prompt_user\": \"По данным UX-спецификаций создай текстовый документ с 4 разделами. Отвечай на языке: %user_language%.\\n\\nДАННЫЕ:\\n%ux_spec_pages%\\n\\nКАРТА САЙТА:\\n%sitemap_pages_json%\\n\\nВерни JSON:\\n{\\\"ux_spec_content\\\": \\\"## Карта страниц\\\\nindex.html — Главная\\\\n\\\\n## Спецификации страниц\\\\n### Главная\\\\nРоли: гость\\\\nКомпоненты: Header, Card\\\\nСостояния: loading, empty\\\\n\\\\n## UI-компоненты\\\\nHeader, Card\\\\n\\\\n## Вайрфреймы страниц\\\\n### Главная\\\\n+----+\\\\n| H  |\\\\n+----+\\\"}\", \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (346,52,3,'Извлечь блок по индексу',0,'{\"tool_invoke\": {\"tool_name\": \"design_widget_iter_step\", \"inputs_map\": {\"iter_index\": \"w_iter_index\", \"project_id\": \"w_project_id\", \"block_ids_json\": \"w_block_ids_json\"}, \"outputs_map\": {\"w_is_done\": \"w_is_done\", \"w_block_id\": \"w_block_id\", \"w_block_name\": \"w_block_name\", \"w_next_index\": \"w_next_index\", \"w_project_idea\": \"w_project_idea\", \"w_block_content\": \"w_block_content\", \"w_blocks_context\": \"w_blocks_context\", \"w_block_stateless\": \"w_block_stateless\", \"w_block_components\": \"w_block_components\", \"w_page_states_json\": \"w_page_states_json\", \"w_block_description\": \"w_block_description\"}}, \"transitions_after\": [], \"transitions_before\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (347,52,2,'LLM: сгенерировать виджеты блока',1,'{\"prompt_user\": \"=== ПРОЕКТ ===\\nИдея: %w_project_idea%\\n\\n=== БЛОК ===\\nНазвание: %w_block_name%\\nОписание: %w_block_description%\\nКомпоненты: %w_block_components%\\nКонтент: %w_block_content%\\nStateless: %w_block_stateless%\\n\\n=== СОСТОЯНИЯ СТРАНИЦ ===\\n%w_page_states_json%\\n\\n=== ВСЕ БЛОКИ ПРОЕКТА ===\\n%w_blocks_context%\\n\\nСоздай виджеты (стилизованные HTML/CSS варианты) для этого блока.\\n\\nПРАВИЛО ИМЕНОВАНИЯ:\\n- Если stateless = true: создай ОДИН виджет с именем = название блока (например \\\"Footer\\\")\\n- Если stateless = false: создай по ОДНОМУ виджету для каждого состояния из списка состояний. Имя = BlockName_state (например \\\"NavBar_anon\\\", \\\"NavBar_auth\\\")\\n\\nhtml: только компонент без html/head/body тегов. CSS-классы с уникальным префиксом bw-{blockname_lower}-{state}-\\ncss: plain CSS, не Tailwind.\\n\\nВерни JSON:\\n{\\\"w_widgets\\\": [{\\\"name\\\": \\\"...\\\", \\\"description\\\": \\\"...\\\", \\\"html\\\": \\\"...\\\", \\\"css\\\": \\\"...\\\"}]}\\n\\nImportant: return ONLY valid JSON.\", \"transitions_after\": [], \"transitions_before\": [], \"llm_to_json_variable\": [{\"text\": \"массив виджетов [{name, description, html, css}]\", \"variable\": \"w_widgets\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (348,52,3,'Сохранить виджеты блока',3,'{\"tool_invoke\": {\"tool_name\": \"planning_block_ai_update\", \"inputs_map\": {\"block_id\": \"w_block_id\", \"widgets_json\": \"w_widgets\", \"description\": \"_const_\", \"content\": \"_const_\"}, \"outputs_map\": {\"widgets_count\": \"w_widgets_count\"}}, \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
