  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (351,51,6,'Генерация виджетов: цикл по блокам',2,'{\"workflow_invoke\": {\"workflow_id\": 52, \"inputs_map\": {\"w_block_ids_json\": \"w_block_ids_json\", \"w_iter_index\": \"w_iter_index\", \"w_project_id\": \"planning_project_id\"}, \"outputs_map\": {\"w_next_index\": \"w_iter_index\", \"w_is_done\": \"w_iter_done\"}, \"repeat\": {\"until\": {\"variable\": \"w_iter_done\", \"operator\": \"==\", \"value\": \"true\"}, \"max_iterations\": 30}}, \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (352,42,6,'Генерация виджетов',7,'{\"workflow_invoke\": {\"workflow_id\": 51, \"inputs_map\": {\"planning_project_id\": \"planning_project_id\"}, \"outputs_map\": {}}, \"transitions_before\": [], \"transitions_after\": []}')
