INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (353,52,3,'Валидация виджетов',2,'{\"tool_invoke\": {\"tool_name\": \"design_widget_validate\", \"inputs_map\": {\"w_widgets\": \"w_widgets\"}, \"outputs_map\": {\"w_widgets\": \"w_widgets\", \"w_widgets_valid_count\": \"w_widgets_valid_count\"}}, \"transitions_before\": [], \"transitions_after\": []}')
