INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (354,53,2,'Сгенерировать задачу',0,'{\"prompt_user\":\"Структурируй задачу на основе описания:\\n%task_description%\\n\\nВерни строго JSON объект (без markdown, без пояснений):\\n{\\\"task_json\\\": {\\\"title\\\": \\\"краткое название 3-7 слов\\\", \\\"description\\\": \\\"развёрнутое описание 2-4 предложения\\\", \\\"goals\\\": [\\\"конкретная цель 1\\\", \\\"конкретная цель 2\\\"]}}\\n\\nПравила:\\n- title: 3-7 слов\\n- description: 2-4 предложения\\n- goals: 2-6 конкретных измеримых шагов (массив строк)\\nВерни ТОЛЬКО JSON, ключ task_json обязателен.\",\"llm_to_json_variable\":[{\"text\":\"JSON объект: {title, description, goals:[string]}\",\"variable\":\"task_json\"}],\"transitions_before\":[],\"transitions_after\":[]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (355,53,4,'Вернуть результат',1,'{\"prompt_user\":\"json:%task_json%\",\"continue_workflow\":false}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (356,54,2,'Генерация токенов',0,'{\"llm_to_json_variable\":[{\"variable\":\"design_tokens_json\",\"text\":\"JSON-объект design_tokens_json с цветовой палитрой, типографикой и скруглением\"}],\"prompt_user\":\"%prompt_user%\\n\\nСоздай уникальную цветовую палитру для этого проекта. Выбирай primary-цвет исходя из тематики описания, НЕ используй синий по умолчанию.\\nПримеры: e-commerce/мода → тёплые тона (#E11D48, #F59E0B), фитнес/здоровье → зелёный (#16A34A), еда/ресторан → оранжевый (#EA580C), технологии/SaaS → можно синий (#2563EB), премиум/luxury → тёмный (#1C1917).\\nПодбирай borderRadius исходя из стиля: резкий/корпоративный → 2-4px, современный → 6-10px, friendly/округлый → 12-20px.\\n\\nВерни строго JSON с ключом design_tokens_json.\\nПример (фитнес-приложение — зелёная тема, округлые углы):\\n{\\n  \\\"design_tokens_json\\\": {\\n    \\\"colors\\\": {\\n      \\\"primary\\\": \\\"#16A34A\\\",\\n      \\\"secondary\\\": \\\"#15803D\\\",\\n      \\\"accent\\\": \\\"#84CC16\\\",\\n      \\\"neutral\\\": \\\"#6B7280\\\",\\n      \\\"background\\\": \\\"#F0FDF4\\\",\\n      \\\"surface\\\": \\\"#FFFFFF\\\",\\n      \\\"text\\\": \\\"#14532D\\\",\\n      \\\"textMuted\\\": \\\"#64748B\\\",\\n      \\\"border\\\": \\\"#D1FAE5\\\",\\n      \\\"error\\\": \\\"#DC2626\\\",\\n      \\\"warning\\\": \\\"#D97706\\\",\\n      \\\"success\\\": \\\"#16A34A\\\"\\n    },\\n    \\\"typography\\\": {\\n      \\\"fontFamily\\\": \\\"Nunito\\\",\\n      \\\"fontSize\\\": \\\"16px\\\"\\n    },\\n    \\\"borderRadius\\\": \\\"12px\\\"\\n  }\\n}\",\"transitions_before\":[],\"transitions_after\":[]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (357,54,4,'Вернуть токены',1,'{\"prompt_user\":\"%design_tokens_json%\",\"continue_workflow\":false,\"transitions_before\":[],\"transitions_after\":[]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (404,55,5,'Инициализация',0,'{\"variable_conversion\": [{\"variable\": \"plan_critique\", \"text\": \"\"}, {\"variable\": \"goals_critique\", \"text\": \"\"}, {\"variable\": \"split_critique\", \"text\": \"\"}, {\"variable\": \"review_iteration\", \"text\": \"0\"}, {\"variable\": \"review_retry\", \"text\": \"0\"}, {\"variable\": \"plan_parse_retry\", \"text\": \"0\"}, {\"variable\": \"goals_parse_retry\", \"text\": \"0\"}, {\"variable\": \"split_parse_retry\", \"text\": \"0\"}, {\"variable\": \"task_plan_json\", \"text\": \"\"}, {\"variable\": \"task_goals_json\", \"text\": \"[]\"}, {\"variable\": \"task_subtasks_json\", \"text\": \"[]\"}, {\"variable\": \"task_size\", \"text\": \"large\"}, {\"variable\": \"manager_status\", \"text\": \"\"}, {\"variable\": \"manager_error\", \"text\": \"\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (405,55,5,'Промпт: план',6,'{\"variable_conversion\": [{\"variable\": \"manager_prompt\", \"text\": \"Теперь составь план работ по задаче, которую ты только что разобрал.\\nЗадачу, цели и свою разведку не пересказывай — ты их помнишь. Код по-прежнему не меняй.\\n\\nПланом закрой вопросы, которые сам же сформулировал на разведке, и опирайся на найденные\\nв проекте паттерны, а не на общие рассуждения.\\n\\n%if task_plan_current%=== ТЕКУЩИЙ ПЛАН ===\\n%task_plan_current%\\nЭто режим доработки: опирайся на существующий план, не переписывай с нуля.\\n\\n%endif%%if plan_critique%=== ЗАМЕЧАНИЯ ПО ПРЕДЫДУЩЕЙ ВЕРСИИ ПЛАНА ===\\n%plan_critique%\\nЗакрой все замечания, остальное в плане не трогай.\\n\\n%endif%Правила:\\n- Нумерованные шаги, конкретно — что делать и где (пути к файлам).\\n- Шагов столько, сколько нужно: точечная правка — 3-5, крупная работа — до 12.\\n  Не добирай шаги ради объёма.\\n- Вопросы разведки остались без ответа: отвечать на них некому. Не переноси их\\n  в план шагами «проверить», «убедиться», «уточнить» — реши сам и пиши действие.\\n- Разведка нашла, что нужное поведение уже реализовано? Тогда план — один-два шага:\\n  подтвердить поведение на живом стенде и закрыть задачу. Кода не менять, работу\\n  не выдумывать.\\n- Последний шаг — проверка результата.\\n- На подзадачи сейчас не дроби: разбиение — отдельный шаг после целей.\\n\\nОтвет заверши тем же планом в машинном виде — блоком:\\n```json\\n{\\\"task_plan_json\\\": {\\\"plan_text\\\": \\\"1. шаг\\\\n2. шаг\\\"}}\\n```\\nplan_text — обычный текст, внутри него запрещены двойные кавычки и фрагменты\\nкода. Перед блоком ничего пересказывать не нужно: план целиком лежит внутри.\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (406,55,3,'Менеджер: план',7,'{\"tool_invoke\": {\"tool_name\": \"claude_shell_call\", \"inputs_map\": {\"role\": \"task_shell_role\", \"prompt\": \"manager_prompt\", \"timeout\": \"_const_1200\", \"work_dir\": \"task_shell_work_dir\"}, \"outputs_map\": {\"error\": \"manager_error\", \"status\": \"manager_status\", \"payload_json\": \"task_plan_json\"}}, \"transitions_after\": [{\"value\": \"answered\", \"step_id\": \"420\", \"operator\": \"!=\", \"variable\": \"manager_status\"}, {\"value\": \"\", \"step_id\": \"494\", \"operator\": \"empty\", \"variable\": \"task_plan_json\"}, {\"value\": \"\", \"step_id\": \"412\", \"operator\": \"!=\", \"variable\": \"task_plan_json\"}], \"transitions_before\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (407,55,3,'Счётчик итераций проверки',19,'{\"tool_invoke\": {\"tool_name\": \"counter_increment\", \"inputs_map\": {\"value\": \"review_iteration\"}, \"outputs_map\": {}}, \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (408,55,5,'Обновить счётчик проверки',20,'{\"variable_conversion\": [{\"variable\": \"review_iteration\", \"text\": \"%counter_increment_407_result_int%\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (409,55,5,'Промпт: судья',21,'{\"variable_conversion\": [{\"variable\": \"review_ok\", \"text\": \"\"}, {\"variable\": \"review_target\", \"text\": \"\"}, {\"variable\": \"review_critique_new\", \"text\": \"\"}, {\"variable\": \"manager_prompt\", \"text\": \"Теперь проверь свою работу как строгий рецензент — план, цели и разбиение разом.\\nНичего из этого не пересказывай, ты только что всё выдал. Код не меняй, только оценка.\\n\\nИтерация проверки %review_iteration% из %max_review_iterations%.\\n\\nПЛАН: покрывает описание задачи и цели заказчика; шаги конкретные — видно что делать\\nи где (модули, файлы), шагов вида «разобраться» нет; последний шаг проверяет результат;\\nвидно, что план переиспользует из существующего в проекте, а что изобретает заново;\\nне потеряны миграция, права доступа, обработка ошибок, документация и тесты; порядок\\nшагов исполним и первый же шаг не сорвётся.\\n\\nЦЕЛИ: список не пустой, целей 1-5, каждая — проверяемый результат, а не действие;\\nдублей нет (две цели, различающиеся только местом проверки или порядком слов, — одна\\nцель); цели покрывают план и не теряют требования заказчика; у каждой видно, чем её\\nпроверить — командой, тестом, страницей админки, запросом к API.\\n\\nРАЗБИЕНИЕ: список не пустой, подзадач 1-7 в порядке выполнения, дублей нет; вместе\\nпокрывают план и цели; каждая — самостоятельный кусок, который можно сдать и проверить\\nотдельно; у КАЖДОЙ заполнены plan и goals, и это план и цели именно её работы, а не\\nкопия общего; по ним видно, что делать и когда работа принята, без чтения остальных\\nподзадач.\\n\\nreview_ok=no ставь только тогда, когда работу нельзя отдать исполнителю: шаг плана\\nведёт не туда, пропущено обязательное действие, цель непроверяема, потеряно требование\\nзаказчика, у подзадачи нет плана или целей, кусок нельзя сдать отдельно. Пожелания\\n«раскрыть подробнее», «назвать больше паттернов», «добавить на всякий случай» — это\\nreview_ok=yes с замечанием: круг переделки стоит дороже, чем такая правка приносит.\\n\\nПри review_ok=no назови в review_target ОДИН слой, с которого начинается переделка:\\nplan — дефект в самом плане, цели и разбиение пойдут следом за ним;\\ngoals — план хорош, переделать нужно цели;\\nsplit — план и цели хороши, переделать нужно только разбиение.\\nБери самый верхний слой с дефектом, а не все сразу.\\n\\nЗамечания давай находками и заданиями на доработку, а не пересказом, уложись в 10 строк.\\n\\nОтвет заверши блоком:\\n```json\\n{\\\"review_ok\\\": \\\"yes\\\", \\\"review_target\\\": \\\"\\\", \\\"review_critique_new\\\": \\\"замечания одним абзацем\\\"}\\n```\\nreview_ok — только yes или no. review_target — plan, goals или split, при yes пустая\\nстрока. review_critique_new — обычный текст без двойных кавычек.\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (410,55,3,'Менеджер: судья',22,'{\"tool_invoke\": {\"tool_name\": \"claude_shell_call\", \"inputs_map\": {\"role\": \"task_shell_role\", \"prompt\": \"manager_prompt\", \"timeout\": \"_const_1200\", \"work_dir\": \"task_shell_work_dir\"}, \"outputs_map\": {\"error\": \"manager_error\", \"status\": \"manager_status\", \"review_ok\": \"review_ok\", \"review_target\": \"review_target\", \"review_critique_new\": \"review_critique_new\"}}, \"transitions_before\": [], \"transitions_after\": [{\"variable\": \"manager_status\", \"operator\": \"!=\", \"value\": \"answered\", \"step_id\": \"419\"}, {\"variable\": \"review_ok\", \"operator\": \"empty\", \"value\": \"\", \"step_id\": \"496\"}, {\"variable\": \"review_ok\", \"operator\": \"==\", \"value\": \"yes\", \"step_id\": \"419\"}, {\"variable\": \"review_iteration\", \"operator\": \">=\", \"value\": \"%max_review_iterations%\", \"step_id\": \"419\"}, {\"variable\": \"review_target\", \"operator\": \"==\", \"value\": \"goals\", \"step_id\": \"418\"}, {\"variable\": \"review_target\", \"operator\": \"==\", \"value\": \"split\", \"step_id\": \"430\"}, {\"variable\": \"review_ok\", \"operator\": \"!=\", \"value\": \"yes\", \"step_id\": \"411\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (411,55,5,'План на доработку',25,'{\"variable_conversion\": [{\"variable\": \"plan_critique\", \"text\": \"%review_critique_new%\"}], \"transitions_before\": [], \"transitions_after\": [{\"variable\": \"plan_critique\", \"operator\": \"exists\", \"value\": \"\", \"step_id\": \"405\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (412,55,5,'Промпт: цели',10,'{\"variable_conversion\": [{\"variable\": \"manager_prompt\", \"text\": \"Теперь по своему плану составь список целей задачи — это критерии приёмки,\\nпо ним QA будет проверять результат. Задачу и план не пересказывай, ты их помнишь.\\nКод не меняй.\\n\\n%if goals_critique%=== ЗАМЕЧАНИЯ ПО ПРЕДЫДУЩЕМУ СПИСКУ ЦЕЛЕЙ ===\\n%goals_critique%\\nПерепиши список так, чтобы все замечания были закрыты.\\n\\n%endif%Правила:\\n- Целей столько, сколько нужно: точечная правка — 1-2, крупная работа — до 5.\\n  Пустой список недопустим, но и добирать цели до круглого числа не надо.\\n- Цель, которую задача не затрагивает («на других страницах ничего не сломалось»,\\n  «остальное работает как раньше»), не цель — такие не пиши.\\n- Цели — про то, что просил заказчик. Своих требований не добавляй: их никто не\\n  заказывал, а проверять и чинить их придётся наравне с настоящими.\\n- Техническое усиление, которого в задаче нет, целью не становится: поведение при\\n  равных значениях, крайние случаи, устойчивость после перезагрузки, соседние\\n  элементы страницы. Считаешь это важным — напиши в плане, но не в целях: каждую\\n  цель QA обязан закрыть воспроизведением, а нечего воспроизводить — подзадача\\n  уйдёт на новый круг разработки из-за требования, которого никто не ставил.\\n- Две цели, которые проверяются одним и тем же действием, — это одна цель.\\n- Разведка нашла, что поведение уже реализовано? Тогда цель ровно одна: увидеть\\n  это поведение на живом стенде.\\n- Дублей нет. Две цели, различающиеся только местом проверки или порядком слов, — это одна цель: объедини их в одну формулировку, места перечисли внутри неё.\\n- Если две цели закрываются одной проверкой, оставь одну.\\n- Цели заказчика не теряй, при необходимости уточняй формулировку.\\n- Каждая цель — проверяемый результат, а не действие.\\n- Одна строка до 100 символов, без нумерации.\\n\\nОтвет заверши тем же списком в машинном виде — блоком:\\n```json\\n{\\\"task_goals_json\\\": [\\\"цель 1\\\", \\\"цель 2\\\"]}\\n```\\nВсегда массив строк: одна цель — массив из одной строки. Пустой массив\\nнедопустим. Цели — обычный текст, без двойных кавычек.\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (413,55,3,'Менеджер: цели',11,'{\"tool_invoke\": {\"tool_name\": \"claude_shell_call\", \"inputs_map\": {\"role\": \"task_shell_role\", \"prompt\": \"manager_prompt\", \"timeout\": \"_const_1200\", \"work_dir\": \"task_shell_work_dir\"}, \"outputs_map\": {\"error\": \"manager_error\", \"status\": \"manager_status\", \"payload_json\": \"task_goals_json\"}}, \"transitions_after\": [{\"value\": \"answered\", \"step_id\": \"421\", \"operator\": \"!=\", \"variable\": \"manager_status\"}, {\"value\": \"\", \"step_id\": \"498\", \"operator\": \"empty\", \"variable\": \"task_goals_json\"}, {\"value\": \"[]\", \"step_id\": \"498\", \"operator\": \"==\", \"variable\": \"task_goals_json\"}, {\"value\": \"\", \"step_id\": \"424\", \"operator\": \"!=\", \"variable\": \"task_goals_json\"}], \"transitions_before\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (418,55,5,'Цели на доработку',26,'{\"variable_conversion\": [{\"variable\": \"goals_critique\", \"text\": \"%review_critique_new%\"}], \"transitions_before\": [], \"transitions_after\": [{\"variable\": \"goals_critique\", \"operator\": \"exists\", \"value\": \"\", \"step_id\": \"412\"}]}')
