INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (419,55,4,'Вернуть результат',28,'{\"prompt_user\": \"json:{\\\"plan\\\": %task_plan_json%, \\\"subtasks\\\": %task_subtasks_json%, \\\"goals\\\": %task_goals_json%}\", \"continue_workflow\": false, \"transitions_before\": [], \"transitions_after\": []}')
