INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (420,55,4,'Менеджер недоступен',29,'{\"prompt_user\": \"json:{\\\"plan\\\": {\\\"plan_text\\\": \\\"Менеджер не ответил. Статус: %manager_status%. Ошибка: %manager_error%\\\", \\\"subtasks\\\": []}, \\\"goals\\\": []}\", \"continue_workflow\": false, \"transitions_before\": [], \"transitions_after\": []}')
