  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (422,55,5,'Промпт: разведка',1,'{\"variable_conversion\": [{\"variable\": \"manager_prompt\", \"text\": \"Ты менеджер разработки в этом проекте. Перед планированием проведи разведку задачи.\\nКод не меняй — только изучи проект.\\n\\n=== ЗАДАЧА ===\\nНазвание: %task_title%\\n\\nОписание:\\n%task_description%\\n\\n%if task_goals%==== ЦЕЛИ ОТ ЗАКАЗЧИКА ===\\n%task_goals%\\n%endif%\\n\\n=== ТИП ЗАДАЧИ ===\\n%if task_type%%task_type% — %task_type_title%%else%не указан%endif%\\n\\n%if project_context%=== КОНТЕКСТ ПРОЕКТА ===\\n%project_context%\\n\\n%endif%Что сделать:\\n1. Проверь, нужно ли вообще делать эту задачу. Описанное может быть уже\\n   сделано — тогда править нечего, и весь конвейер отработает впустую. Найди место,\\n   которое отвечает за нужное поведение, и сверь его с описанием. Путь к файлу и номер\\n   строки обязательны: «похоже, работает» — не ответ. Вышло, что уже сделано — так и\\n   напиши, остальные пункты тогда делай коротко.\\n2. Разбей описание на теги — короткие ключевые понятия: подсистемы, файлы, технологии, действия.\\n3. По тегам определи тематику: какую часть проекта задача затрагивает и что в ней меняется.\\n4. Найди в проекте похожие места и уже используемые паттерны, на которые план должен опереться.\\n   Указывай конкретные пути к файлам, а не общие слова.\\n5. Сформулируй вопросы, ответы на которые нужны, чтобы план получился конкретным.\\n   Направление вопросов бери по типу задачи:\\n   - dev — где точка входа, какие существующие паттерны переиспользовать, что менять в схеме БД,\\n     API и фронтенде, что сломается у соседних модулей;\\n   - bug — как воспроизвести, где настоящая причина, какой тест ловит регресс, где ещё живёт\\n     та же ошибка;\\n   - test — что именно проверяем, какие граничные случаи и данные нужны, где место тестов\\n     и как их гонять;\\n   - research — какие варианты сравниваем и по каким критериям, что уже пробовали в проекте,\\n     чем заканчивается исследование;\\n   - plan — из каких этапов состоит работа, что от чего зависит, где риски, чем меряем готовность;\\n   - тип не указан — бери направления по смыслу описания.\\n\\nПлан работ сейчас не пиши и решение не предлагай: это только разведка.\\n\\nОтвечай обычным текстом и коротко: теги — одной строкой, тематика — 1-2 предложения,\\nпаттерны — до 5 пунктов с путями к файлам, вопросы — до 5, по одному в строке.\\nФайлов открывай не больше десяти: важнее точное попадание, чем полнота обзора.\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (423,55,3,'Менеджер: разведка',2,'{\"tool_invoke\": {\"tool_name\": \"claude_shell_call\", \"inputs_map\": {\"role\": \"task_shell_role\", \"prompt\": \"manager_prompt\", \"timeout\": \"_const_1200\", \"work_dir\": \"task_shell_work_dir\"}, \"outputs_map\": {\"error\": \"manager_error\", \"status\": \"manager_status\", \"response\": \"task_recon\"}}, \"transitions_after\": [{\"value\": \"answered\", \"step_id\": \"420\", \"operator\": \"!=\", \"variable\": \"manager_status\"}], \"transitions_before\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (424,55,5,'Промпт: разбиение',15,'{\"variable_conversion\": [{\"variable\": \"manager_prompt\", \"text\": \"План и цели готовы. Теперь реши сам, нужно ли разбивать эту работу на подзадачи,\\nи если нужно — на какие. Задачу, план и цели не пересказывай, ты их помнишь.\\nКод не меняй.\\n\\nСначала ответь себе на вопрос, делится ли работа вообще. Дробить стоит, когда куски\\nложатся в разные модули или слои, идут разными этапами и каждый можно сдать и\\nпроверить отдельно. Точечную правку в одном месте не дроби — у неё одна подзадача\\nна всю задачу, и это нормальный ответ, а не отписка.\\n\\n%if split_critique%=== ЗАМЕЧАНИЯ ПО ПРЕДЫДУЩЕМУ РАЗБИЕНИЮ ===\\n%split_critique%\\nЗакрой все замечания, остальное не трогай.\\n\\n%endif%Правила:\\n- Разбивать не нужно — ровно одна подзадача, покрывающая задачу целиком.\\n- Разбивать нужно — 2-7 подзадач в порядке выполнения, последняя проверяет результат.\\n- title: 3-8 слов. description: 1-3 предложения, что именно сделать и где.\\n- Вместе подзадачи покрывают весь план и все цели и не дублируют друг друга.\\n- Каждая подзадача самостоятельна: исполнитель делает её, не читая остальные.\\n\\nУ каждой подзадачи свои план и цели — общий план задачи исполнителю не выдаётся как\\nруководство к действию, он работает по плану своей подзадачи:\\n- plan — план работы именно по этой подзадаче: 2-6 шагов с новой строки, каждый\\n  начинается с «- ». Пиши конкретику этой подзадачи: какие файлы и функции трогать,\\n  в каком порядке. Общий план задачи сюда не копируй — у разных подзадач планы разные.\\n- goals — 1-4 проверяемые цели именно этой подзадачи: по ним QA примет работу.\\n  Формулируй так, чтобы ответ был «да» или «нет», без «улучшить» и «проверить».\\n  Цели задачи целиком сюда не переписывай, бери только ту их часть, которую\\n  закрывает эта подзадача.\\n- Задача неделимая и подзадача одна — план и цели у неё всё равно свои и всё равно\\n  обязательны: короткий план работы и цели, по которым её примут.\\n\\nРазведка нашла, что поведение уже реализовано? Тогда подзадача ровно одна —\\nподтвердить поведение и закрыть задачу.\\n\\nОтвет заверши тем же разбиением в машинном виде — блоком:\\n```json\\n{\\\"task_subtasks_json\\\": [{\\\"title\\\": \\\"название\\\", \\\"description\\\": \\\"что сделать\\\", \\\"plan\\\": \\\"- шаг\\\\n- шаг\\\", \\\"goals\\\": [\\\"цель\\\"]}]}\\n```\\nВсегда массив объектов: одна подзадача — массив из одного объекта. Пустой массив\\nнедопустим. У каждого объекта ровно четыре поля: title, description, plan, goals;\\ngoals — массив строк. Тексты без двойных кавычек и фрагментов кода.\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (425,55,3,'Менеджер: разбиение',16,'{\"tool_invoke\": {\"tool_name\": \"claude_shell_call\", \"inputs_map\": {\"role\": \"task_shell_role\", \"prompt\": \"manager_prompt\", \"timeout\": \"_const_1200\", \"work_dir\": \"task_shell_work_dir\"}, \"outputs_map\": {\"error\": \"manager_error\", \"status\": \"manager_status\", \"payload_json\": \"task_subtasks_json\"}}, \"transitions_after\": [{\"value\": \"answered\", \"step_id\": \"431\", \"operator\": \"!=\", \"variable\": \"manager_status\"}, {\"value\": \"\", \"step_id\": \"502\", \"operator\": \"empty\", \"variable\": \"task_subtasks_json\"}, {\"value\": \"[]\", \"step_id\": \"502\", \"operator\": \"==\", \"variable\": \"task_subtasks_json\"}, {\"value\": \"yes\", \"step_id\": \"419\", \"operator\": \"==\", \"variable\": \"task_done\"}, {\"value\": \"\", \"step_id\": \"407\", \"operator\": \"!=\", \"variable\": \"task_subtasks_json\"}], \"transitions_before\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (430,55,5,'Разбиение на доработку',27,'{\"variable_conversion\": [{\"variable\": \"split_critique\", \"text\": \"%review_critique_new%\"}], \"transitions_before\": [], \"transitions_after\": [{\"variable\": \"split_critique\", \"operator\": \"exists\", \"value\": \"\", \"step_id\": \"424\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (431,55,5,'Разбиение недоступно',31,'{\"variable_conversion\": [{\"variable\": \"task_subtasks_json\", \"text\": \"[{\\\"title\\\": \\\"Выполнить задачу целиком\\\", \\\"description\\\": \\\"Выполнить задачу по утверждённому плану одной подзадачей: разбиение не получено.\\\"}]\"}], \"transitions_before\": [], \"transitions_after\": [{\"value\": \"\", \"step_id\": \"419\", \"operator\": \"exists\", \"variable\": \"task_subtasks_json\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (432,56,5,'Инициализация',0,'{\"variable_conversion\": [{\"variable\": \"env_ok\", \"text\": \"yes\"}, {\"variable\": \"env_error\", \"text\": \"\"}, {\"variable\": \"dev_critique\", \"text\": \"\"}, {\"variable\": \"dev_critique_new\", \"text\": \"\"}, {\"variable\": \"dev_iteration\", \"text\": \"0\"}, {\"variable\": \"dev_recon\", \"text\": \"\"}, {\"variable\": \"dev_report_json\", \"text\": \"\"}, {\"variable\": \"dev_ok\", \"text\": \"\"}, {\"variable\": \"dev_status\", \"text\": \"\"}, {\"variable\": \"dev_error\", \"text\": \"\"}, {\"variable\": \"dev_report_retry\", \"text\": \"0\"}, {\"variable\": \"dev_check_retry\", \"text\": \"0\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (433,56,5,'Промпт: разбор подзадачи',2,'{\"variable_conversion\": [{\"variable\": \"developer_prompt\", \"text\": \"Ты разработчик в этом проекте. Тебе поручена одна подзадача из плана.\\nСейчас только разбор: код НЕ меняй, файлы не правь, коммитов не делай.\\n%if subtask_work_dir%\\nКод своей подзадачи смотри в каталоге %subtask_work_dir% — это отдельная выкладка\\nрепозитория, твоя ветка в ней уже выкачена. Начни с перехода в этот каталог.\\n%endif%\\n\\n=== ЗАДАЧА ЦЕЛИКОМ ===\\nНазвание: %task_title%\\n\\nОписание:\\n%task_description%\\n\\n=== ПЛАН ЗАДАЧИ ===\\n%if task_plan_current%%task_plan_current%%else%не задан%endif%\\n\\n=== ЦЕЛИ ЗАДАЧИ ===\\n%if task_goals%%task_goals%%else%не заданы%endif%\\n\\n=== ТВОЯ ПОДЗАДАЧА (только она) ===\\n#%subtask_id% %subtask_title%\\n\\n%subtask_description%\\n\\n%if subtask_plan%=== ПЛАН ТВОЕЙ ПОДЗАДАЧИ ===\\n%subtask_plan%\\n\\n%endif%%if subtask_goals%=== ЦЕЛИ ТВОЕЙ ПОДЗАДАЧИ (по ним её примут) ===\\n%subtask_goals%\\n\\n%endif%%if task_last_error%=== ПРЕДЫДУЩАЯ ПОПЫТКА НЕ ПРОШЛА ПРОВЕРКУ QA ===\\n%task_last_error%\\n\\nРазбирайся с этой ошибкой, а не начинай подзадачу заново: рабочее уже сделано.\\n\\n%endif%Что сделать:\\n1. Найди места, которых подзадача касается, — конкретные пути к файлам и функции,\\n   а не общие слова. Посмотри, как рядом решены похожие задачи.\\n2. Прочитай правила проекта, которые тут действуют: CLAUDE.md и нужные файлы\\n   .claude/docs/ и .claude/docs-common/ (именование, размещение кода, схема БД,\\n   API, фронтенд). Назови те правила, что относятся к этой подзадаче.\\n3. Наметь минимальное изменение: какие файлы меняешь, что в них добавляешь,\\n   чем проверишь результат.\\n4. Отдельно назови, что в подзадачу НЕ входит и чего ты трогать не будешь.\\n\\nОтвечай обычным текстом: сначала разбор — файлы, паттерны и правила проекта,\\nна которые опираешься; затем ход работы по шагам: файл — что меняю — чем проверю.\\nJSON сейчас не нужен.\\n\\nКоротко: не длиннее 15 строк, строка на мысль. Без заголовков, таблиц и значков —\\nэтот ответ целиком уходит в следующий промпт, и каждая лишняя строка там читается\\nзаново. Пересказывать прочитанный код не нужно, назови путь и строку.\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (434,56,3,'Разработчик: разбор',3,'{\"tool_invoke\": {\"tool_name\": \"claude_shell_call\", \"inputs_map\": {\"role\": \"task_shell_role\", \"prompt\": \"developer_prompt\", \"work_dir\": \"task_shell_work_dir\", \"timeout\": \"_const_1200\"}, \"outputs_map\": {\"error\": \"dev_error\", \"status\": \"dev_status\", \"response\": \"dev_recon\"}}, \"transitions_before\": [], \"transitions_after\": [{\"variable\": \"dev_status\", \"operator\": \"!=\", \"value\": \"answered\", \"step_id\": \"443\"}, {\"variable\": \"dev_recon\", \"operator\": \"empty\", \"value\": \"\", \"step_id\": \"443\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (435,56,5,'Промпт: реализация',4,'{\"variable_conversion\": [{\"variable\": \"developer_prompt\", \"text\": \"Ты разработчик в этом проекте. Выполни свою подзадачу целиком.\\n\\n=== ЗАДАЧА ЦЕЛИКОМ ===\\nНазвание: %task_title%\\n\\nОписание:\\n%task_description%\\n\\n=== ПЛАН ЗАДАЧИ ===\\n%if task_plan_current%%task_plan_current%%else%не задан%endif%\\n\\n=== ЦЕЛИ ЗАДАЧИ ===\\n%if task_goals%%task_goals%%else%не заданы%endif%\\n\\n=== ТВОЯ ПОДЗАДАЧА (только она) ===\\n#%subtask_id% %subtask_title%\\n\\n%subtask_description%\\n\\n%if subtask_plan%=== ПЛАН ТВОЕЙ ПОДЗАДАЧИ ===\\n%subtask_plan%\\n\\n%endif%%if subtask_goals%=== ЦЕЛИ ТВОЕЙ ПОДЗАДАЧИ (по ним её примут) ===\\n%subtask_goals%\\n\\n%endif%=== ТВОЙ РАЗБОР И НАМЕЧЕННЫЙ ХОД РАБОТЫ ===\\n%dev_recon%\\n\\n%if task_last_error%=== ЧТО НЕ ПРОШЛО QA В ПРОШЛЫЙ РАЗ ===\\n%task_last_error%\\n\\n%endif%%if dev_critique%=== ЗАМЕЧАНИЯ САМОПРОВЕРКИ, ИХ НУЖНО ЗАКРЫТЬ ===\\n%dev_critique%\\n\\nДоделай начатое по этим замечаниям, а не переписывай всё заново.\\n\\n%endif%Правила работы, они не обсуждаются:\\n- Делаешь только свою подзадачу. Соседние подзадачи плана не трогаешь: их делают\\n  в своих кругах, и чужие правки сорвут проверку QA.\\n- Код пишешь по правилам проекта из CLAUDE.md и .claude/docs/: именование с\\n  префиксом модуля, приватные функции внизу файла, файлы небольшие.\\n- Схема БД меняется только в migrations/0001.sql. Данные — через Seed UI или\\n  скрипт в data/migration_manual/. Прод и общие системы не трогаешь.\\n- Работаешь ТОЛЬКО в каталоге своей подзадачи%if subtask_work_dir% %subtask_work_dir%%endif%:\\n  начни с перехода в него. Твоя ветка %subtask_branch% там уже выкачена — создавать\\n  и переключать ветки не нужно, git checkout здесь только навредит: у соседних\\n  подзадач свои каталоги, а общий чекаут держит человек. В master не коммитишь и\\n  master не мержишь: слияние делает человек, приняв merge request.\\n- После правки .py подними сервер своей задачи: ./task_server.sh up %subtask_id%\\n  из каталога проекта — он поднимает отдельный uvicorn поверх твоего каталога, на\\n  нём же потом проверяет QA. Общий uvicorn на :8011 не трогай: на нём работает\\n  человек. Правки шаблонов, JS и CSS перезапуска не требуют.\\n- Документацию обновляешь в том же круге, что и код. Смотришь `CLAUDE.md` и\\n  `.claude/docs/`: если работа изменила описанное там — устройство модуля, схему\\n  БД, контракт API, набор страниц админки, шаги workflow, настройки, — правишь\\n  ровно эти места. Устаревшее описание хуже отсутствующего: по нему планируют\\n  следующую задачу. Ничего из описанного не задето — не трогаешь ничего.\\n- Проверь сделанное сам: синтаксис изменённых файлов, grep по старым ссылкам,\\n  прогон нужных тестов. Полный набор тестов гоняет QA после тебя.\\n\\nРабота не закончена, пока её негде посмотреть. Проверив себя, доведи её до merge request:\\n1. git add по изменённым файлам и git commit; первая строка сообщения —\\n   «task/%subtask_id%: что сделано».\\n2. git push -u origin %subtask_branch%.\\n3. Открой merge request в master:\\n   gh pr create --base master --head %subtask_branch% --title \\\"task/%subtask_id%: кратко о сделанном\\\" --body \\\"что сделано и чем проверял\\\"\\n   Если merge request на эту ветку уже открыт (доработка после QA), второй не заводи —\\n   хватит новых коммитов в ту же ветку, адрес возьми командой\\n   gh pr view %subtask_branch% --json url -q .url\\n4. Запомни полный адрес merge request: по нему человек смотрит работу со страницы\\n   задач, и без него работа считается недоделанной.\\n\\nОтвечай обычным текстом. JSON я попрошу отдельным шагом — сейчас его не пиши.\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (436,56,3,'Разработчик: реализация',5,'{\"tool_invoke\": {\"tool_name\": \"claude_shell_call\", \"inputs_map\": {\"role\": \"task_shell_role\", \"prompt\": \"developer_prompt\", \"work_dir\": \"task_shell_work_dir\", \"timeout\": \"_const_2800\"}, \"outputs_map\": {\"error\": \"dev_error\", \"status\": \"dev_status\"}}, \"transitions_before\": [], \"transitions_after\": [{\"variable\": \"dev_status\", \"operator\": \"!=\", \"value\": \"answered\", \"step_id\": \"443\"}]}')
