INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (438,56,5,'Обновить счётчик самопроверки',9,'{\"variable_conversion\": [{\"variable\": \"dev_iteration\", \"text\": \"%counter_increment_437_result_int%\"}], \"transitions_before\": [], \"transitions_after\": []}')
