INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (439,56,5,'Промпт: самопроверка',10,'{\"variable_conversion\": [{\"variable\": \"dev_ok\", \"text\": \"\"}, {\"variable\": \"dev_critique_new\", \"text\": \"\"}, {\"variable\": \"developer_prompt\", \"text\": \"Теперь проверь собственную работу как строгий рецензент. Правки ты только что\\nсделал — не пересказывай их, а ищи, что с ними не так. Новый код сейчас не пиши.\\n\\nКруг самопроверки %dev_iteration% из %max_dev_iterations%.\\n\\nФормальные требования: подзадача выполнена целиком, а не наполовину; изменения\\nзакоммичены в ветку %subtask_branch% и запушены; merge request в master открыт и его\\nадрес попал в отчёт полем mr_url; ничего лишнего за пределами подзадачи не задето; документация (`CLAUDE.md`,\\n`.claude/docs/`) обновлена там, где работа изменила описанное в ней, и не осталась\\nот прошлой редакции.\\n\\nДальше посмотри на изменение с другого ракурса:\\n1. Соответствие: закрывает ли сделанное описание подзадачи и те цели задачи,\\n   которые к ней относятся? Чего не хватает?\\n2. Регрессии: кто ещё зовёт изменённые функции и шаблоны, что сломается рядом?\\n   Найди эти места в коде и проверь.\\n3. Правила проекта: именование, размещение файлов, схема БД, контракт API,\\n   фронтенд — что нарушено?\\n4. Проверяемость: чем результат подтверждается и пройдут ли существующие тесты\\n   (tests/) — их будет гонять QA.\\n%if task_last_error%5. Прошлая ошибка QA закрыта: %task_last_error%\\n%endif%\\nНе выполнен хотя бы один пункт — dev_ok=no. В замечаниях пиши задания на\\nдоработку, а не пересказ сделанного.\\n\\nОтвечай обычным текстом. JSON я попрошу отдельным шагом — сейчас его не пиши.\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (440,56,3,'Разработчик: самопроверка',11,'{\"tool_invoke\": {\"tool_name\": \"claude_shell_call\", \"inputs_map\": {\"role\": \"task_shell_role\", \"prompt\": \"developer_prompt\", \"work_dir\": \"task_shell_work_dir\", \"timeout\": \"_const_1200\"}, \"outputs_map\": {\"error\": \"dev_error\", \"status\": \"dev_status\"}}, \"transitions_before\": [], \"transitions_after\": [{\"variable\": \"dev_status\", \"operator\": \"!=\", \"value\": \"answered\", \"step_id\": \"538\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
