INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (444,57,5,'Инициализация',0,'{\"variable_conversion\": [{\"variable\": \"env_ok\", \"text\": \"yes\"}, {\"variable\": \"env_error\", \"text\": \"\"}, {\"variable\": \"qa_critique\", \"text\": \"\"}, {\"variable\": \"qa_critique_new\", \"text\": \"\"}, {\"variable\": \"qa_iteration\", \"text\": \"0\"}, {\"variable\": \"qa_recon\", \"text\": \"\"}, {\"variable\": \"qa_report_json\", \"text\": \"\"}, {\"variable\": \"qa_verdict_json\", \"text\": \"\"}, {\"variable\": \"qa_ok\", \"text\": \"\"}, {\"variable\": \"qa_more\", \"text\": \"\"}, {\"variable\": \"qa_status\", \"text\": \"\"}, {\"variable\": \"qa_error\", \"text\": \"\"}, {\"variable\": \"qa_report_retry\", \"text\": \"0\"}, {\"variable\": \"qa_verdict_retry\", \"text\": \"0\"}, {\"variable\": \"qa_goal_index\", \"text\": \"0\"}, {\"variable\": \"qa_goals_summary\", \"text\": \"\"}, {\"variable\": \"qa_goals_open\", \"text\": \"0\"}, {\"variable\": \"qa_goals_open_text\", \"text\": \"\"}, {\"variable\": \"qa_goal_ok\", \"text\": \"no\"}, {\"variable\": \"qa_goal_evidence\", \"text\": \"\"}, {\"variable\": \"qa_goal_text\", \"text\": \"\"}, {\"variable\": \"qa_goal_answer\", \"text\": \"\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (445,57,5,'Промпт: разбор изменений',2,'{\"variable_conversion\": [{\"variable\": \"qa_prompt\", \"text\": \"Ты QA в этом проекте. Разработчик закончил одну подзадачу плана, тебе её проверять.\\nСейчас только разбор: код НЕ меняй, файлы не правь, ничего не чини, коммитов не делай.\\nНашёл дефект — это замечание разработчику, а не повод исправить самому.\\n\\n=== ЗАДАЧА ЦЕЛИКОМ ===\\nНазвание: %task_title%\\n\\nОписание:\\n%task_description%\\n\\n=== ПЛАН ЗАДАЧИ ===\\n%if task_plan_current%%task_plan_current%%else%не задан%endif%\\n\\n=== ЦЕЛИ ЗАДАЧИ ===\\n%if task_goals%%task_goals%%else%не заданы%endif%\\n\\n=== ПОДЗАДАЧА, КОТОРУЮ ПРОВЕРЯЕШЬ ===\\n#%subtask_id% %subtask_title%\\n\\n%subtask_description%\\n\\n%if subtask_plan%=== ПЛАН ПОДЗАДАЧИ ===\\n%subtask_plan%\\n\\n%endif%%if subtask_goals%=== ЦЕЛИ ПОДЗАДАЧИ (критерий приёмки) ===\\n%subtask_goals%\\n\\n%endif%%if task_dev_report%=== ОТЧЁТ РАЗРАБОТЧИКА ===\\n%task_dev_report%\\n\\nОтчёту верь только как подсказке, где смотреть: проверяешь ты код, а не отчёт.\\n\\n%else%Отчёта разработчика нет — изменения ищи сам: ветка %subtask_branch%, git status, git diff.\\n\\n%endif%%if task_last_error%=== ЧЕМ КОНЧИЛСЯ ПРОШЛЫЙ КРУГ ===\\n%task_last_error%\\n\\n%endif%Что сделать:\\n1. Найди сами изменения:%if subtask_work_dir% каталог подзадачи %subtask_work_dir%,%endif% ветка %subtask_branch%,\\n   git diff относительно origin/master.\\n   Перечисли изменённые файлы и что в них поменялось.\\n2. Сопоставь изменения с описанием подзадачи: что закрыто, что не закрыто, что\\n   сделано сверх подзадачи.\\n3. Собери набор проверок, применимый именно здесь. Для каждой цели подзадачи\\n   заранее реши, чем ты воспроизведёшь поведение: браузером, запросом к API или\\n   существующим тестом из tests/. Синтаксис и grep — это довесок, а не проверка.\\n4. Наметь, кого ещё могло задеть: кто зовёт изменённые функции и шаблоны.\\n\\nОтвечай обычным текстом: сначала изменённые файлы и что в них поменялось,\\nзатем проверки по пунктам — что запускаю и что считаю успехом. JSON сейчас не нужен.\\n\\nКоротко: не длиннее 15 строк, строка на файл и строка на проверку. Без заголовков,\\nтаблиц и значков — этот ответ целиком уходит в следующий промпт. Код не пересказывай,\\nназывай путь и строку.\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (446,57,3,'QA: разбор изменений',3,'{\"tool_invoke\": {\"tool_name\": \"claude_shell_call\", \"inputs_map\": {\"role\": \"task_shell_role\", \"prompt\": \"qa_prompt\", \"work_dir\": \"task_shell_work_dir\", \"timeout\": \"_const_1200\"}, \"outputs_map\": {\"error\": \"qa_error\", \"status\": \"qa_status\", \"response\": \"qa_recon\"}}, \"transitions_before\": [], \"transitions_after\": [{\"variable\": \"qa_status\", \"operator\": \"!=\", \"value\": \"answered\", \"step_id\": \"456\"}, {\"variable\": \"qa_recon\", \"operator\": \"empty\", \"value\": \"\", \"step_id\": \"456\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (447,57,5,'Промпт: прогон проверок',4,'{\"variable_conversion\": [{\"variable\": \"qa_prompt\", \"text\": \"Прогони проверки, которые наметил. Код НЕ меняй: ты проверяешь, а не чинишь.\\nПроверка упала — это факт для отчёта, а не задание себе.\\n\\n=== ПОДЗАДАЧА ===\\n#%subtask_id% %subtask_title%\\n\\n%subtask_description%\\n\\n%if subtask_plan%=== ПЛАН ПОДЗАДАЧИ ===\\n%subtask_plan%\\n\\n%endif%%if subtask_goals%=== ЦЕЛИ ПОДЗАДАЧИ (критерий приёмки) ===\\n%subtask_goals%\\n\\n%endif%=== ЧТО ТЫ РАЗОБРАЛ И НАМЕТИЛ ПРОВЕРИТЬ ===\\n%qa_recon%\\n\\n%if qa_critique%=== ЧТО ПРОВЕРИТЬ ДОПОЛНИТЕЛЬНО ===\\n%qa_critique%\\n\\nЭто добор к уже сделанному, а не повторный прогон всего.\\n\\n%endif%Что считается проверкой:\\n- Поведение доказывается воспроизведением. Синтаксис, grep и чтение diff — это не\\n  проверка поведения: они говорят, что код написан, а не что он работает.\\n%if subtask_work_dir%- Проверяешь то, что отдаёт приложение. Код подзадачи лежит в каталоге\\n  %subtask_work_dir%, нужная ветка в нём уже выкачена — переключать её не нужно.\\n  Сервер над этим каталогом поднимается командой ./task_server.sh up %subtask_id%\\n  из каталога проекта, адрес %subtask_server_url%. Общий :8011 доказательством не\\n  считается: на нём код основного чекаута, а не проверяемой ветки. Копия файла в\\n  /tmp и чтение исходника доказательством не считаются.%else%- Проверяешь то, что отдаёт приложение: ветка разработчика выкачена в рабочем\\n  каталоге проекта, сервер запущен (обычно http://localhost:8011). Копия файла в\\n  /tmp и чтение исходника доказательством не считаются.%endif%\\n- Страница админки или её JS — открывай живым браузером: playwright, headless\\n  chromium, вход QA-учёткой; образец логина и работы с селекторами —\\n  tests/test_team_task_pages.py. Кликаешь тот самый элемент и смотришь результат\\n  БЕЗ перезагрузки страницы. Состояние после перезагрузки — отдельная проверка, ею\\n  клик не заменяется.\\n- API — реальный запрос к запущенному серверу: код ответа и тело.\\n- Фоновая логика — прогон существующих тестов проекта из tests/. Адрес сервера\\n  сюита берёт из переменной окружения, поэтому гони её на сервер ветки:\\n  BASE_URL=%subtask_server_url% .venv/bin/python3 -m pytest tests/<файл> -q\\n- Документация: сверь `CLAUDE.md` и `.claude/docs/` с тем, что изменила подзадача.\\n  Это чтение файлов, а не прогон — воспроизводить тут нечего. Ищешь противоречие:\\n  описан старый маршрут, старое имя шага, исчезнувшая настройка, набор колонок или\\n  страниц, которого больше нет. Нашёл — это замечание разработчику, чинит документацию\\n  он. Работа ничего из описанного не меняла — пункт не применим, и придираться не к чему.\\n- Нет данных под сценарий — заведи их сам, записью прямо в базу. Клиента `mysql` в\\n  окружении нет, пиши из чекаута ветки скриптом на `.venv/bin/python3` с\\n  `mysql_.mysql_` — как это делает `tests/conftest.py`, там же решён вопрос адреса\\n  базы с хоста. Через интерфейс или API приложения — только если проверяешь сам\\n  интерфейс: создание сущности в приложении\\n  часто тянет фоновую обработку (новый проект уходит в планирование), и на проверку\\n  сортировки уедут чужие прогоны агентов. Это разрешено: запрет на правки касается кода и рабочего\\n  дерева, а не содержимого таблиц. После проверки удали ровно то, что завёл.\\n  Чужие строки не правишь и не удаляешь — они принадлежат человеку, а не стенду.\\n- Не удалось воспроизвести — так и пиши: проверка не сделана. Честное «не проверил»\\n  полезнее, чем «синтаксис чистый» вместо проверки.\\n\\nГраницы этого хода:\\n- Цели подзадачи здесь не закрываешь. Каждую из них я спрошу отдельным ходом, по\\n  одной, и доказательство попрошу там же. Здесь выше они даны как контекст — чтобы\\n  ты понимал, вокруг чего изменения, а не как список к исполнению.\\n- Твоё дело на этом ходе — общая приёмка: изменения отвечают плану, лишнего в них\\n  нет, существующий набор тестов проходит, побочных эффектов у соседнего поведения\\n  не видно.\\n- Воспроизводить цели сейчас — двойная работа: ход уйдёт на то, что через минуту\\n  придётся повторить поимённо. Тестовые данные под цель заводятся тоже там.\\n\\nПравила прогона, они не обсуждаются:\\n- Гоняешь существующий набор тестов проекта. Новые тесты под этот прогон не\\n  пишешь и произвольный сгенерированный код не исполняешь. Разовый скрипт\\n  браузерной проверки — исключение: он ничего не меняет и в репозиторий не идёт.\\n- Рабочее дерево не меняешь: ничего не правишь, не коммитишь, не пушишь, ветки\\n  не мержишь.\\n- Чужие и общие системы не трогаешь: прод, чужие проекты, внешние сервисы.\\n- Проверяешь ветку разработчика %subtask_branch%, а не master.\\n- Каждую проверку описываешь как «команда — результат», без пересказа кода.\\n\\nОтвечай обычным текстом, по строке на проверку: «команда — результат». Без\\nзаголовков, таблиц и значков, без пересказа кода. Замечания разработчику — отдельным\\nсписком в конце, по пункту на замечание. JSON я попрошу отдельным шагом — сейчас его\\nне пиши.\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (448,57,3,'QA: прогон проверок',5,'{\"tool_invoke\": {\"tool_name\": \"claude_shell_call\", \"inputs_map\": {\"role\": \"task_shell_role\", \"prompt\": \"qa_prompt\", \"work_dir\": \"task_shell_work_dir\", \"timeout\": \"_const_1800\"}, \"outputs_map\": {\"error\": \"qa_error\", \"status\": \"qa_status\"}}, \"transitions_before\": [], \"transitions_after\": [{\"variable\": \"qa_status\", \"operator\": \"!=\", \"value\": \"answered\", \"step_id\": \"456\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
