  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (450,57,5,'Обновить счётчик проверки',18,'{\"variable_conversion\": [{\"variable\": \"qa_iteration\", \"text\": \"%counter_increment_449_result_int%\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (451,57,5,'Промпт: вердикт',19,'{\"variable_conversion\": [{\"variable\": \"qa_ok\", \"text\": \"\"}, {\"variable\": \"qa_more\", \"text\": \"no\"}, {\"variable\": \"qa_critique_new\", \"text\": \"\"}, {\"variable\": \"qa_verdict_json\", \"text\": \"{\\\"ok\\\": false, \\\"error\\\": \\\"QA не вынес вердикт\\\"}\"}, {\"variable\": \"qa_prompt\", \"text\": \"Вынеси вердикт по подзадаче. Новых проверок сейчас не запускай, код не меняй.\\n\\nКруг проверки %qa_iteration% из %max_qa_iterations%.\\n\\n=== ОТЧЁТ О ПРОГОНЕ ===\\n%qa_report_json%\\n\\n%if qa_goals_summary%=== ЦЕЛИ ПОДЗАДАЧИ, КАЖДАЯ ПРОВЕРЕНА ОТДЕЛЬНО ===\\n%qa_goals_summary%\\n\\n%endif%=== ПОДЗАДАЧА ===\\n#%subtask_id% %subtask_title%\\n\\n%subtask_description%\\n\\n%if subtask_plan%=== ПЛАН ПОДЗАДАЧИ ===\\n%subtask_plan%\\n\\n%endif%=== ЦЕЛИ ЗАДАЧИ ===\\n%if task_goals%%task_goals%%else%не заданы%endif%\\n\\nРешай по четырём вопросам:\\n1. В списке целей выше нет ни одной «НЕ закрыта»?\\n2. Проверки прошли, а то, что не прошло, действительно неважно?\\n3. Ничего рядом не сломано и правила проекта не нарушены?\\n4. Документация не противоречит сделанному: описанное в `CLAUDE.md` и `.claude/docs/`\\n   совпадает с новым устройством, а не с прежним?\\n\\nОтвет «нет» хотя бы на один — qa_ok=no.\\nОтдельно реши, нужен ли ещё круг проверок: qa_more=yes, если остались значимые\\nнепроверенные места, и no, если проверять больше нечего.\\n\\nВ поле error пиши замечания разработчику: что именно исправить, по пунктам, без\\nпересказа сделанного. Этот текст уйдёт ему заданием следующего круга, поэтому\\nобщие слова там бесполезны.\\n\\nОтвечай обычным текстом. JSON я попрошу отдельным шагом — сейчас его не пиши.\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (452,57,3,'QA: вердикт',20,'{\"tool_invoke\": {\"tool_name\": \"claude_shell_call\", \"inputs_map\": {\"role\": \"task_shell_role\", \"prompt\": \"qa_prompt\", \"work_dir\": \"task_shell_work_dir\", \"timeout\": \"_const_1200\"}, \"outputs_map\": {\"error\": \"qa_error\", \"status\": \"qa_status\"}}, \"transitions_before\": [], \"transitions_after\": [{\"variable\": \"qa_status\", \"operator\": \"!=\", \"value\": \"answered\", \"step_id\": \"456\"}]}')
