INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (494,55,5,'Промпт JSON: план',8,'{\"variable_conversion\": [{\"variable\": \"task_plan_json\", \"text\": \"\"}, {\"variable\": \"manager_prompt\", \"text\": \"Верни тот же самый ответ в машинном виде. Ничего заново не придумывай\\nи не переделывай — это ровно то, что ты только что написал.\\n\\nОтветь ОДНИМ JSON-объектом, без markdown, без ограды из обратных кавычек\\nи без текста вокруг:\\n{\\\"task_plan_json\\\": {\\\"plan_text\\\": \\\"детальный план текстом\\\"}}\\n\\n- task_plan_json — ВСЕГДА объект с единственным ключом plan_text:\\n  не строка, не массив, не список объектов. План в одну строку — всё равно объект.\\n- plan_text — обычный текст. Внутри него запрещены двойные кавычки и любые\\n  фрагменты JSON или кода.\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (495,55,3,'Ответ JSON: план',9,'{\"tool_invoke\": {\"tool_name\": \"claude_shell_call\", \"inputs_map\": {\"role\": \"task_shell_role\", \"prompt\": \"manager_prompt\", \"timeout\": \"_const_1200\", \"work_dir\": \"task_shell_work_dir\"}, \"outputs_map\": {\"error\": \"manager_error\", \"status\": \"manager_status\", \"payload_json\": \"task_plan_json\"}}, \"transitions_after\": [{\"value\": \"answered\", \"step_id\": \"420\", \"operator\": \"!=\", \"variable\": \"manager_status\"}, {\"value\": \"\", \"step_id\": \"457\", \"operator\": \"empty\", \"variable\": \"task_plan_json\"}], \"transitions_before\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (496,55,5,'Промпт JSON: судья',23,'{\"variable_conversion\": [{\"variable\": \"review_ok\", \"text\": \"\"}, {\"variable\": \"review_target\", \"text\": \"\"}, {\"variable\": \"review_critique_new\", \"text\": \"\"}, {\"variable\": \"manager_prompt\", \"text\": \"Верни тот же самый ответ в машинном виде. Ничего заново не придумывай\\nи не переделывай — это ровно то, что ты только что написал.\\n\\nОтветь ОДНИМ JSON-объектом, без markdown, без ограды из обратных кавычек\\nи без текста вокруг:\\n{\\\"review_ok\\\": \\\"yes\\\", \\\"review_target\\\": \\\"\\\", \\\"review_critique_new\\\": \\\"замечания, пустая строка если всё хорошо\\\"}\\n\\n- review_ok — строго yes или no.\\n- review_target — plan, goals или split; при review_ok=yes пустая строка.\\n- review_critique_new — обычный текст, без двойных кавычек и фрагментов JSON.\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (497,55,3,'Ответ JSON: судья',24,'{\"tool_invoke\": {\"tool_name\": \"claude_shell_call\", \"inputs_map\": {\"role\": \"task_shell_role\", \"prompt\": \"manager_prompt\", \"timeout\": \"_const_1200\", \"work_dir\": \"task_shell_work_dir\"}, \"outputs_map\": {\"error\": \"manager_error\", \"status\": \"manager_status\", \"review_ok\": \"review_ok\", \"review_target\": \"review_target\", \"review_critique_new\": \"review_critique_new\"}}, \"transitions_before\": [], \"transitions_after\": [{\"variable\": \"manager_status\", \"operator\": \"!=\", \"value\": \"answered\", \"step_id\": \"419\"}, {\"variable\": \"review_ok\", \"operator\": \"empty\", \"value\": \"\", \"step_id\": \"467\"}, {\"variable\": \"review_ok\", \"operator\": \"==\", \"value\": \"yes\", \"step_id\": \"419\"}, {\"variable\": \"review_iteration\", \"operator\": \">=\", \"value\": \"%max_review_iterations%\", \"step_id\": \"419\"}, {\"variable\": \"review_target\", \"operator\": \"==\", \"value\": \"goals\", \"step_id\": \"418\"}, {\"variable\": \"review_target\", \"operator\": \"==\", \"value\": \"split\", \"step_id\": \"430\"}, {\"variable\": \"review_ok\", \"operator\": \"!=\", \"value\": \"yes\", \"step_id\": \"411\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (498,55,5,'Промпт JSON: цели',12,'{\"variable_conversion\": [{\"variable\": \"task_goals_json\", \"text\": \"[]\"}, {\"variable\": \"manager_prompt\", \"text\": \"Верни тот же самый ответ в машинном виде. Ничего заново не придумывай\\nи не переделывай — это ровно то, что ты только что написал.\\n\\nОтветь ОДНИМ JSON-объектом, без markdown, без ограды из обратных кавычек\\nи без текста вокруг:\\n{\\\"task_goals_json\\\": [\\\"цель 1\\\", \\\"цель 2\\\", \\\"цель 3\\\"]}\\n\\n- task_goals_json — ВСЕГДА массив строк. Одна цель — массив из одной строки.\\n- Пустой массив недопустим: целей минимум одна.\\n- Цели — обычный текст, без двойных кавычек и без фрагментов JSON.\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (499,55,3,'Ответ JSON: цели',13,'{\"tool_invoke\": {\"tool_name\": \"claude_shell_call\", \"inputs_map\": {\"role\": \"task_shell_role\", \"prompt\": \"manager_prompt\", \"timeout\": \"_const_1200\", \"work_dir\": \"task_shell_work_dir\"}, \"outputs_map\": {\"error\": \"manager_error\", \"status\": \"manager_status\", \"payload_json\": \"task_goals_json\"}}, \"transitions_before\": [], \"transitions_after\": [{\"variable\": \"manager_status\", \"operator\": \"!=\", \"value\": \"answered\", \"step_id\": \"421\"}, {\"variable\": \"task_goals_json\", \"operator\": \"empty\", \"value\": \"\", \"step_id\": \"460\"}, {\"variable\": \"task_goals_json\", \"operator\": \"==\", \"value\": \"[]\", \"step_id\": \"460\"}]}')
