INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (502,55,5,'Промпт JSON: разбиение',17,'{\"variable_conversion\": [{\"variable\": \"task_subtasks_json\", \"text\": \"[]\"}, {\"variable\": \"manager_prompt\", \"text\": \"Верни тот же самый ответ в машинном виде. Ничего заново не придумывай\\nи не переделывай — это ровно то, что ты только что написал.\\n\\nОтветь ОДНИМ JSON-объектом, без markdown, без ограды из обратных кавычек\\nи без текста вокруг:\\n{\\\"task_subtasks_json\\\": [{\\\"title\\\": \\\"краткое название\\\", \\\"description\\\": \\\"что именно сделать\\\", \\\"plan\\\": \\\"- шаг\\\\n- шаг\\\", \\\"goals\\\": [\\\"проверяемая цель\\\"]}]}\\n\\n- task_subtasks_json — ВСЕГДА массив объектов. Одна подзадача — массив из одного\\n  объекта, а не объект и не строка.\\n- Пустой массив недопустим: у неделимой задачи ровно одна подзадача, равная ей самой.\\n- У каждого объекта ровно четыре поля: title, description, plan, goals.\\n- goals — массив строк, не объект и не одна строка через запятую.\\n- title, description и plan — обычный текст, без двойных кавычек и фрагментов JSON.\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (503,55,3,'Ответ JSON: разбиение',18,'{\"tool_invoke\": {\"tool_name\": \"claude_shell_call\", \"inputs_map\": {\"role\": \"task_shell_role\", \"prompt\": \"manager_prompt\", \"timeout\": \"_const_1200\", \"work_dir\": \"task_shell_work_dir\"}, \"outputs_map\": {\"error\": \"manager_error\", \"status\": \"manager_status\", \"payload_json\": \"task_subtasks_json\"}}, \"transitions_after\": [{\"value\": \"answered\", \"step_id\": \"431\", \"operator\": \"!=\", \"variable\": \"manager_status\"}, {\"value\": \"\", \"step_id\": \"463\", \"operator\": \"empty\", \"variable\": \"task_subtasks_json\"}, {\"value\": \"[]\", \"step_id\": \"463\", \"operator\": \"==\", \"variable\": \"task_subtasks_json\"}, {\"value\": \"yes\", \"step_id\": \"419\", \"operator\": \"==\", \"variable\": \"task_done\"}], \"transitions_before\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (506,56,5,'Промпт JSON: отчёт',6,'{\"variable_conversion\": [{\"variable\": \"dev_report_json\", \"text\": \"\"}, {\"variable\": \"developer_prompt\", \"text\": \"Верни тот же самый ответ в машинном виде. Ничего заново не придумывай\\nи не переделывай — это ровно то, что ты только что написал.\\n\\nОтветь ОДНИМ JSON-объектом, без markdown, без ограды из обратных кавычек\\nи без текста вокруг:\\n{\\\"dev_report_json\\\": {\\\"ok\\\": true, \\\"summary\\\": \\\"что сделано, по шагам\\\", \\\"files\\\": [\\\"путь/к/файлу\\\"], \\\"branch\\\": \\\"%subtask_branch%\\\", \\\"mr_url\\\": \\\"полный адрес merge request\\\", \\\"checks\\\": \\\"чем проверял и с каким результатом\\\", \\\"error\\\": \\\"почему не сделано, если ok=false\\\"}}\\n\\n- dev_report_json — ВСЕГДА объект, поля ровно те, что перечислены.\\n- files — массив строк, ok — true или false.\\n- ok=false ставь только если подзадачу выполнить не удалось; тогда в error — причина.\\n- mr_url — полный адрес открытого merge request, пустым не оставляй.\\n- summary, checks и error — обычный текст, без двойных кавычек и фрагментов JSON.\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
