INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (508,56,5,'Промпт JSON: самопроверка',12,'{\"variable_conversion\": [{\"variable\": \"dev_ok\", \"text\": \"\"}, {\"variable\": \"dev_critique_new\", \"text\": \"\"}, {\"variable\": \"developer_prompt\", \"text\": \"Верни тот же самый ответ в машинном виде. Ничего заново не придумывай\\nи не переделывай — это ровно то, что ты только что написал.\\n\\nОтветь ОДНИМ JSON-объектом, без markdown, без ограды из обратных кавычек\\nи без текста вокруг:\\n{\\\"dev_ok\\\": \\\"yes\\\", \\\"dev_score\\\": 7, \\\"dev_critique_new\\\": \\\"замечания, пустая строка если всё хорошо\\\"}\\n\\n- dev_ok — строго yes или no, dev_score — число от 1 до 10.\\n- dev_critique_new — обычный текст, без двойных кавычек и фрагментов JSON.\"}], \"transitions_before\": [], \"transitions_after\": []}')
