INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (510,57,5,'Промпт JSON: отчёт о прогоне',6,'{\"variable_conversion\": [{\"variable\": \"qa_report_json\", \"text\": \"\"}, {\"variable\": \"qa_prompt\", \"text\": \"Верни тот же самый ответ в машинном виде. Ничего заново не придумывай\\nи не переделывай — это ровно то, что ты только что написал.\\n\\nОтветь ОДНИМ JSON-объектом, без markdown, без ограды из обратных кавычек\\nи без текста вокруг:\\n{\\\"qa_report_json\\\": {\\\"summary\\\": \\\"что проверял и чем это кончилось\\\", \\\"checks\\\": [\\\"команда — результат\\\"], \\\"failed\\\": [\\\"что не прошло, пустой список если всё прошло\\\"], \\\"coverage\\\": \\\"что осталось непроверенным и почему\\\"}}\\n\\n- qa_report_json — ВСЕГДА объект, поля ровно те, что перечислены.\\n- checks и failed — массивы строк, пустой список пиши как [].\\n- summary и coverage — обычный текст, без двойных кавычек и фрагментов JSON.\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
