INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (512,57,5,'Промпт JSON: вердикт',21,'{\"variable_conversion\": [{\"variable\": \"qa_ok\", \"text\": \"\"}, {\"variable\": \"qa_more\", \"text\": \"no\"}, {\"variable\": \"qa_critique_new\", \"text\": \"\"}, {\"variable\": \"qa_verdict_json\", \"text\": \"{\\\"ok\\\": false, \\\"error\\\": \\\"QA не вынес вердикт\\\"}\"}, {\"variable\": \"qa_prompt\", \"text\": \"Верни тот же самый ответ в машинном виде. Ничего заново не придумывай\\nи не переделывай — это ровно то, что ты только что написал.\\n\\nОтветь ОДНИМ JSON-объектом, без markdown, без ограды из обратных кавычек\\nи без текста вокруг:\\n{\\\"qa_ok\\\": \\\"yes\\\", \\\"qa_more\\\": \\\"no\\\", \\\"qa_critique_new\\\": \\\"что проверить дополнительно, пустая строка если ничего\\\", \\\"qa_verdict_json\\\": {\\\"ok\\\": true, \\\"summary\\\": \\\"вердикт одной фразой\\\", \\\"checks\\\": [\\\"команда — результат\\\"], \\\"failed\\\": [\\\"что не прошло\\\"], \\\"error\\\": \\\"замечания разработчику, пустая строка при ok=true\\\"}}\\n\\n- qa_ok и qa_more — строго yes или no, qa_verdict_json.ok — true или false.\\n- checks и failed — массивы строк, пустой список пиши как [].\\n- error — замечания разработчику по пунктам, обычным текстом, без двойных кавычек.\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (513,57,3,'Ответ JSON: вердикт',22,'{\"tool_invoke\": {\"tool_name\": \"claude_shell_call\", \"inputs_map\": {\"role\": \"task_shell_role\", \"prompt\": \"qa_prompt\", \"timeout\": \"_const_1200\", \"work_dir\": \"task_shell_work_dir\"}, \"outputs_map\": {\"error\": \"qa_error\", \"status\": \"qa_status\", \"qa_ok\": \"qa_ok\", \"qa_more\": \"qa_more\", \"qa_critique_new\": \"qa_critique_new\", \"qa_verdict_json\": \"qa_verdict_json\"}}, \"transitions_before\": [], \"transitions_after\": [{\"variable\": \"qa_status\", \"operator\": \"!=\", \"value\": \"answered\", \"step_id\": \"456\"}, {\"variable\": \"qa_ok\", \"operator\": \"empty\", \"value\": \"\", \"step_id\": \"491\"}, {\"variable\": \"qa_goals_open\", \"operator\": \">\", \"value\": \"0\", \"step_id\": \"523\"}, {\"variable\": \"qa_ok\", \"operator\": \"==\", \"value\": \"yes\", \"step_id\": \"454\"}, {\"variable\": \"qa_iteration\", \"operator\": \">=\", \"value\": \"%max_qa_iterations%\", \"step_id\": \"455\"}, {\"variable\": \"qa_more\", \"operator\": \"!=\", \"value\": \"yes\", \"step_id\": \"455\"}, {\"variable\": \"qa_more\", \"operator\": \"==\", \"value\": \"yes\", \"step_id\": \"453\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (514,57,5,'Цели: начать обход',8,'{\"variable_conversion\": [{\"variable\": \"qa_goal_index\", \"text\": \"0\"}, {\"variable\": \"qa_goals_summary\", \"text\": \"\"}, {\"variable\": \"qa_goals_open\", \"text\": \"0\"}, {\"variable\": \"qa_goals_open_text\", \"text\": \"\"}], \"transitions_before\": [], \"transitions_after\": []}')
