INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (515,57,3,'Цель: взять следующую',9,'{\"tool_invoke\": {\"tool_name\": \"task_goal_pick\", \"inputs_map\": {\"task_id\": \"subtask_id\", \"index\": \"qa_goal_index\"}, \"outputs_map\": {\"goal_has\": \"qa_goal_has\", \"goal_text\": \"qa_goal_text\", \"goal_number\": \"qa_goal_number\", \"goal_total\": \"qa_goal_total\"}}, \"transitions_before\": [], \"transitions_after\": [{\"variable\": \"qa_goal_has\", \"operator\": \"!=\", \"value\": \"yes\", \"step_id\": \"449\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (516,57,5,'Промпт: проверка цели',10,'{\"variable_conversion\": [{\"variable\": \"qa_goal_ok\", \"text\": \"no\"}, {\"variable\": \"qa_goal_evidence\", \"text\": \"\"}, {\"variable\": \"qa_prompt\", \"text\": \"Проверь ровно одну цель подзадачи — цель %qa_goal_number% из %qa_goal_total%.\\nОстальные цели сейчас не трогай, их спрошу отдельно.\\n\\n=== ЦЕЛЬ ===\\n%qa_goal_text%\\n\\n=== ПОДЗАДАЧА ===\\n#%subtask_id% %subtask_title%\\n\\n%subtask_description%\\n\\n%if qa_report_json%=== ЧТО УЖЕ ПРОГНАЛ ===\\n%qa_report_json%\\n\\nЗасчитывать уже сделанное можно, только если оно проверяло именно эту цель.\\nИначе проверь сейчас.\\n\\n%endif%Что считается проверкой:\\n- Поведение доказывается воспроизведением. Синтаксис, grep и чтение diff — это не\\n  проверка поведения: они говорят, что код написан, а не что он работает.\\n%if subtask_work_dir%- Проверяешь то, что отдаёт приложение. Код подзадачи лежит в каталоге\\n  %subtask_work_dir%, нужная ветка в нём уже выкачена — переключать её не нужно.\\n  Сервер над этим каталогом поднимается командой ./task_server.sh up %subtask_id%\\n  из каталога проекта, адрес %subtask_server_url%. Общий :8011 доказательством не\\n  считается: на нём код основного чекаута, а не проверяемой ветки. Копия файла в\\n  /tmp и чтение исходника доказательством не считаются.%else%- Проверяешь то, что отдаёт приложение: ветка разработчика выкачена в рабочем\\n  каталоге проекта, сервер запущен (обычно http://localhost:8011). Копия файла в\\n  /tmp и чтение исходника доказательством не считаются.%endif%\\n- Страница админки или её JS — открывай живым браузером: playwright, headless\\n  chromium, вход QA-учёткой; образец логина и работы с селекторами —\\n  tests/test_team_task_pages.py. Кликаешь тот самый элемент и смотришь результат\\n  БЕЗ перезагрузки страницы. Состояние после перезагрузки — отдельная проверка, ею\\n  клик не заменяется.\\n- API — реальный запрос к запущенному серверу: код ответа и тело.\\n- Фоновая логика — прогон существующих тестов проекта из tests/. Адрес сервера\\n  сюита берёт из переменной окружения, поэтому гони её на сервер ветки:\\n  BASE_URL=%subtask_server_url% .venv/bin/python3 -m pytest tests/<файл> -q\\n- Нет данных под сценарий — заведи их сам, записью прямо в базу. Клиента `mysql` в\\n  окружении нет, пиши из чекаута ветки скриптом на `.venv/bin/python3` с\\n  `mysql_.mysql_` — как это делает `tests/conftest.py`, там же решён вопрос адреса\\n  базы с хоста. Через интерфейс или API приложения — только если проверяешь сам\\n  интерфейс: создание сущности в приложении\\n  часто тянет фоновую обработку (новый проект уходит в планирование), и на проверку\\n  сортировки уедут чужие прогоны агентов. Это разрешено: запрет на правки касается кода и рабочего\\n  дерева, а не содержимого таблиц. После проверки удали ровно то, что завёл.\\n  Чужие строки не правишь и не удаляешь — они принадлежат человеку, а не стенду.\\n- Не удалось воспроизвести — так и пиши: проверка не сделана. Честное «не проверил»\\n  полезнее, чем «синтаксис чистый» вместо проверки.\\n\\nЕщё правила:\\n- Код не меняй, ничего не чини, не коммить: цель либо закрыта тем, что есть, либо нет.\\n- Ответ по цели — да или нет. «В основном», «формально закрыта» и «по коду видно,\\n  что должно работать» — это нет.\\n\\nОтвечай обычным текстом, не длиннее 6 строк: что запустил, что увидел, закрыта\\nцель или нет. Без заголовков, таблиц и значков — этот ответ уходит в вердикт.\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (517,57,3,'QA: проверка цели',11,'{\"tool_invoke\": {\"tool_name\": \"claude_shell_call\", \"inputs_map\": {\"role\": \"task_shell_role\", \"prompt\": \"qa_prompt\", \"work_dir\": \"task_shell_work_dir\", \"timeout\": \"_const_1800\"}, \"outputs_map\": {\"error\": \"qa_error\", \"status\": \"qa_status\", \"response\": \"qa_goal_answer\"}}, \"transitions_before\": [], \"transitions_after\": [{\"variable\": \"qa_status\", \"operator\": \"!=\", \"value\": \"answered\", \"step_id\": \"456\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (518,57,5,'Промпт JSON: цель',12,'{\"variable_conversion\": [{\"variable\": \"qa_prompt\", \"text\": \"Верни тот же самый ответ в машинном виде. Ничего заново не придумывай\\nи не переделывай — это ровно то, что ты только что написал.\\n\\nОтветь ОДНИМ JSON-объектом, без markdown, без ограды из обратных кавычек\\nи без текста вокруг:\\n{\\\"qa_goal_ok\\\": \\\"yes\\\", \\\"qa_goal_evidence\\\": \\\"команда или действие — что увидел\\\"}\\n\\n- qa_goal_ok — строго yes или no. yes только если поведение воспроизведено.\\n- qa_goal_evidence — одна строка обычным текстом, без переводов строк и двойных кавычек.\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (519,57,3,'Ответ JSON: цель',13,'{\"tool_invoke\": {\"tool_name\": \"claude_shell_call\", \"inputs_map\": {\"role\": \"task_shell_role\", \"prompt\": \"qa_prompt\", \"work_dir\": \"task_shell_work_dir\", \"timeout\": \"_const_1200\"}, \"outputs_map\": {\"error\": \"qa_error\", \"status\": \"qa_status\", \"qa_goal_ok\": \"qa_goal_ok\", \"qa_goal_evidence\": \"qa_goal_evidence\"}}, \"transitions_before\": [], \"transitions_after\": [{\"variable\": \"qa_status\", \"operator\": \"!=\", \"value\": \"answered\", \"step_id\": \"456\"}]}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
