INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (526,55,5,'Промпт JSON: разведка',3,'{\"variable_conversion\": [{\"variable\": \"task_done\", \"text\": \"\"}, {\"variable\": \"manager_prompt\", \"text\": \"Верни вердикт разведки в машинном виде. Ничего заново не изучай и не переделывай —\\nэто ровно то, что ты только что выяснил.\\n\\nОтветь ОДНИМ JSON-объектом, без markdown, без ограды из обратных кавычек\\nи без текста вокруг:\\n{\\\"task_done\\\": \\\"no\\\", \\\"task_size\\\": \\\"small\\\"}\\n\\n- task_done — yes, если нужное поведение уже реализовано и менять нечего, иначе no.\\n- task_size — small при правке в одном-трёх файлах без изменений схемы БД и\\n  контракта API, иначе large. Сомневаешься — large.\"}], \"transitions_before\": [], \"transitions_after\": []}')
  ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
