-- ---------------------------------------------------------------- После
SELECT 'ПОСЛЕ' AS этап,
       (SELECT COUNT(*) FROM agent_workflow)                   AS workflow,
       (SELECT COUNT(*) FROM agent_workflow_step)              AS шагов,
       (SELECT COUNT(*) FROM agent_workflow_variable)          AS переменных,
       (SELECT COUNT(*) FROM agent_workflow_variable_workflow) AS связей,
       (SELECT COUNT(*) FROM node_variable)                    AS узловых;

-- Целостность переходов: каждый `step_id` ведёт на существующий шаг.
--
-- `JSON_VALID` обязателен: у части шагов `metadata` — пустая строка, а не NULL, и
-- `JSON_EXTRACT` на ней падает целиком («The document is empty»), унося с собой всю
-- проверку. `COALESCE` от этого не спасает: он ловит NULL, а не пустую строку.
SELECT COUNT(*) AS битых_переходов
  FROM agent_workflow_step s
  JOIN JSON_TABLE(IF(JSON_VALID(s.metadata), JSON_EXTRACT(s.metadata, '$.transitions_after'), '[]'),
                  '$[*]' COLUMNS (step_id VARCHAR(20) PATH '$.step_id')) jt
  LEFT JOIN agent_workflow_step t ON t.id = jt.step_id
 WHERE jt.step_id IS NOT NULL AND jt.step_id <> '' AND t.id IS NULL;

-- Шаги без своего workflow — таких быть не должно.
SELECT COUNT(*) AS шагов_без_workflow
  FROM agent_workflow_step s LEFT JOIN agent_workflow w ON w.id = s.workflow_id
 WHERE w.id IS NULL;

-- Связи переменных, потерявшие концы.
SELECT COUNT(*) AS битых_связей
  FROM agent_workflow_variable_workflow vw
  LEFT JOIN agent_workflow_variable v ON v.id = vw.variable_id
  LEFT JOIN agent_workflow w ON w.id = vw.workflow_id
 WHERE v.id IS NULL OR w.id IS NULL;

-- Workflow, у которых нет ни одного агента: их некому вызвать.
SELECT w.id, w.name
  FROM agent_workflow w
  LEFT JOIN agent a ON a.workflow_id = w.id
 WHERE w.subflow = 0 AND a.id IS NULL
 ORDER BY w.id;
